const VERTS_PER_QUAD: usize = 6;
// Reichlich: der offene Chat bringt Unterstriche fuer Links mit, die Textauswahl eine
// Markierung je ausgewaehltem Textstueck.
const MAX_UI_RECTS: usize = 4096;
