// Die vier Regler der Schadens-Faerbung (s. Settings::damage_tint_*). Eigene Aufzaehlung
// fuer genau diese Farbe.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum DamageTintAxis {
    Hue,
    Saturation,
    Value,
    Alpha,
}

impl DamageTintAxis {
    // Reihenfolge der Zeilen im Video-Tab, ab DAMAGE_TINT_FIRST_ROW.
    const ALL: [DamageTintAxis; 4] = [DamageTintAxis::Hue, DamageTintAxis::Saturation, DamageTintAxis::Value, DamageTintAxis::Alpha];

    // Alle Achsen teilen sich die Zeile des Farbfelds.
    fn row(self) -> usize {
        DAMAGE_TINT_FIRST_ROW
    }

    fn label(self) -> &'static str {
        match self {
            DamageTintAxis::Hue => "Ton",
            DamageTintAxis::Saturation => "Sättigung",
            DamageTintAxis::Value => "Helligkeit",
            DamageTintAxis::Alpha => "Deckkraft",
        }
    }

    fn unit(self) -> &'static str {
        match self {
            DamageTintAxis::Hue => "\u{b0}",
            _ => "%",
        }
    }

    // Ton ist ZYKLISCH (0 und 360 sind dieselbe Farbe), die uebrigen klemmen -- genau wie
    // ueberall im Farbfenster.
    fn cyclic(self) -> bool {
        self == DamageTintAxis::Hue
    }

    fn range(self) -> (u32, u32, u32) {
        match self {
            DamageTintAxis::Hue => (HSV_HUE_MIN, HSV_HUE_MAX, HSV_HUE_STEP),
            _ => (HSV_SAT_VAL_MIN, HSV_SAT_VAL_MAX, HSV_SAT_VAL_STEP),
        }
    }
}

// Die drei Regler der Himmelsfarbe (s. ModuleId::SkyColor). KEINE Deckkraft: der Himmel ist
// das Hinterste im Bild, es gibt nichts, wogegen er mischen koennte.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum SkyColorAxis {
    Hue,
    Saturation,
    Value,
}

// Uhrzeit-Regler des Himmels: ein Tag in Ticks, Schritt 15 Minuten (250 Ticks), zyklisch.
const SKY_TIME_DAY: u32 = 24_000;
const SKY_TIME_STEP: u32 = 250;

fn adjust_sky_time(set: &mut Settings, dir: i32) {
    set.module_sky_time = (set.module_sky_time as i32 + dir * SKY_TIME_STEP as i32).rem_euclid(SKY_TIME_DAY as i32) as u32;
}

// Ticks des Tages als Uhrzeit "hh:mm" (Tick 0 = 6:00).
fn sky_time_label(ticks: u32) -> String {
    let stunde = (ticks / 1000 + 6) % 24;
    let minute = (ticks % 1000) * 60 / 1000;
    format!("{stunde:02}:{minute:02}")
}

// Modul "Wetter": was vom Himmel faellt. Server = wie vom Server geschickt (Regenstaerke, Gewitter, je
// Biom Regen/Schnee/nichts), sonst fest und ueberall gleich. Nur fuers Bild: der Dreizack
// mit Sog fragt weiter das echte Wetter (s. touching_water_or_rain).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum WeatherMode {
    Server,
    Clear,
    Rain,
    Snow,
}

impl WeatherMode {
    const ALL: [WeatherMode; 4] = [WeatherMode::Server, WeatherMode::Clear, WeatherMode::Rain, WeatherMode::Snow];

    fn label(self) -> &'static str {
        match self {
            WeatherMode::Server => "Server",
            WeatherMode::Clear => "Klar",
            WeatherMode::Rain => "Regen",
            WeatherMode::Snow => "Schnee",
        }
    }

    // Name in der Einstellungsdatei.
    fn key(self) -> &'static str {
        match self {
            WeatherMode::Server => "server",
            WeatherMode::Clear => "clear",
            WeatherMode::Rain => "rain",
            WeatherMode::Snow => "snow",
        }
    }

    fn from_key(key: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|m| m.key() == key)
    }

    fn next(self) -> Self {
        let i = Self::ALL.iter().position(|&m| m == self).unwrap_or(0);
        Self::ALL[(i + 1) % Self::ALL.len()]
    }
}

// Modul Himmel: was statt Vanillas Himmel zu sehen ist (nur im Leistungs-Pfad).
//   Einfarbig  eine feste Farbe, Tag wie Nacht; die Uhrzeit spielt keine Rolle.
//   Verlauf    der Verlaufshimmel des fruehen Shader-Pfads (render::gradient_sky) mit Sonne
//              und Mond, beide abschaltbar.
//   Skin       der Himmel aus dem Resourcepack (s. custom_sky), ohne Pack-Himmel die
//              Himmelsfarbe der Tageszeit.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum SkyMode {
    Solid,
    Gradient,
    Skin,
}

impl SkyMode {
    const ALL: [SkyMode; 3] = [SkyMode::Solid, SkyMode::Gradient, SkyMode::Skin];

    fn label(self) -> &'static str {
        match self {
            SkyMode::Solid => "Einfarbig",
            SkyMode::Gradient => "Verlauf",
            SkyMode::Skin => "Skin",
        }
    }

    fn key(self) -> &'static str {
        match self {
            SkyMode::Solid => "solid",
            SkyMode::Gradient => "gradient",
            SkyMode::Skin => "skin",
        }
    }

    fn from_key(key: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|m| m.key() == key)
    }

    fn next(self) -> Self {
        let i = Self::ALL.iter().position(|&m| m == self).unwrap_or(0);
        Self::ALL[(i + 1) % Self::ALL.len()]
    }
}

// Ton in Grad (0..360, zyklisch), Saettigung/Helligkeit in
// Prozent wie ueberall sonst im Menue (inventory_transparency, module_hitbox_opacity, ...).
// Von ALLEN Farbwaehlern des Clients benutzt (Hitbox-Modul, Schadens-Faerbung) -- deshalb
// neutral benannt und nicht nach ihrem ersten Einsatzort.
const HSV_HUE_MIN: u32 = 0;
const HSV_HUE_MAX: u32 = 360;
const HSV_HUE_STEP: u32 = 10;
const HSV_SAT_VAL_MIN: u32 = 0;
const HSV_SAT_VAL_MAX: u32 = 100;
const HSV_SAT_VAL_STEP: u32 = 5;

// Einen Regler der Schadens-Faerbung um einen Schritt verstellen. `dir` ist +1/-1. Der Ton
// laeuft zyklisch um (0 und 360 sind dieselbe Farbe), die uebrigen klemmen -- dieselbe Regel
// wie ueberall im Farbfenster.
//
// Freie Funktion statt Methode: der Aufrufer haelt bereits `&mut self.settings` und koennte
// daneben nicht noch `&self` ausleihen.
// Anzeige der Blitzdauer: Sekunden mit Komma, zwei Stellen (ein Tick = 0,05 s).
fn damage_tint_duration_text(ticks: u32) -> String {
    format!("{:.2} s", ticks as f32 / 20.0).replace('.', ",")
}

// Ein Schritt an einer Schild-Farbe: Ton zyklisch (0 und 360 sind dieselbe Farbe), der Rest
// klemmt.
fn adjust_shield_color(set: &mut Settings, farbe: ShieldColor, achse: DamageTintAxis, dir: i32) {
    let (min, max, step) = achse.range();
    let Some(wert) = set.shield_color_mut(farbe, achse) else { return };
    let neu = *wert as i32 + dir * step as i32;
    *wert = if achse.cyclic() { neu.rem_euclid(max as i32) as u32 } else { neu.clamp(min as i32, max as i32) as u32 };
}

// HSV (h in Grad 0..360, s/v in 0..1) -> RGB (0..1). Standardformel (Wikipedia "HSL and HSV"),
// kein echter Farbwaehler-Widget noetig (s. Kommentar an build_module_menu zu Drag-
// Interaktion) -- drei Stepper pro Variante reichen fuer ein Debug-Overlay.
fn hsv_to_rgb(hue_deg: f32, saturation: f32, value: f32) -> [f32; 3] {
    let c = value * saturation;
    let h_prime = (hue_deg / 60.0).rem_euclid(6.0);
    let x = c * (1.0 - (h_prime % 2.0 - 1.0).abs());
    let (r1, g1, b1) = match h_prime as i32 {
        0 => (c, x, 0.0),
        1 => (x, c, 0.0),
        2 => (0.0, c, x),
        3 => (0.0, x, c),
        4 => (x, 0.0, c),
        _ => (c, 0.0, x),
    };
    let m = value - c;
    [r1 + m, g1 + m, b1 + m]
}
// "Dichte" der Hitbox-Anzeige, in Bildschirm-PIXELN -- IMMER die Kantenbreite (egal ob
// gepunktet oder durchgezogen, s. build_hitbox_vertices), im gepunkteten Modus zusaetzlich
// die Strich+Luecke-Laenge (dieselbe Zahl fuer beides: ein dichterer Wert macht die Linie
// gleichzeitig dicker UND -- falls gepunktet -- die Striche laenger, statt zwei getrennte
// Regler fuer eine einzige "wie deutlich soll die Anzeige sein"-Frage zu brauchen).
const HITBOX_DENSITY_MIN: u32 = 1;
const HITBOX_DENSITY_MAX: u32 = 10;
const HITBOX_DENSITY_STEP: u32 = 1;
// Linienbreite des eigenen Blockumrisses (s. ModuleId::BlockOutline), in Bildschirmpixeln.
const BLOCK_OUTLINE_WIDTH_MIN: u32 = 1;
const BLOCK_OUTLINE_WIDTH_MAX: u32 = 10;
// Wie lang ein Strich+Luecke-Paar im Vergleich zur Linienbreite ist (s.
// build_hitbox_vertices). Striche in Breite der Linie waeren optisch Punkte -- der Faktor
// macht daraus erkennbare Striche, ohne einen zweiten Regler dafuer zu brauchen.
const HITBOX_DASH_PER_DENSITY: f32 = 6.0;
// Wie weit um das Auge Spinnennetze eine Hitbox bekommen, in Bloecken. Der Wuerfel wird jedes
// Bild abgesucht; 8 sind gut 5000 Bloecke und reichen fuer den Nahkampf.
const HITBOX_COBWEB_RADIUS: i32 = 8;

#[repr(C)]
#[derive(Copy, Clone, bytemuck::Pod, bytemuck::Zeroable)]
struct CrosshairVertex {
    position: [f32; 2],
    uv: [f32; 2],
    // Glyphen-UV im Font-Atlas (Gruppe 1), nur fuer die Glyphen-Arten (s. kind).
    glyph_uv: [f32; 2],
    // Was dieses Dreieck ist (s. crosshair.wgsl): 0 = Flaeche in Fadenkreuz-Farbe, 1 = schwarze
    // Kontur, 2 = Glyphe in Fadenkreuz-Farbe, 3 = Glyphe schwarz (Kontur), 4 = Glyphe weiss,
    // 5 = Kreis in Fadenkreuz-Farbe, 6 = Kreis schwarz (Kontur).
    // Als Attribut und nicht als Uniform, weil alles in EINEM Zeichenaufruf rausgeht.
    kind: f32,
    // Deckkraft (Pfeil-Anzeige hat eine eigene).
    alpha: f32,
    // Nur fuer Kreise (Arten 5 und 6): innerer und aeusserer Radius in Pixeln; glyph_uv ist
    // dann der Abstand zur Kreismitte in Pixeln.
    circle: [f32; 2],
}

const CROSSHAIR_KIND_FILL: f32 = 0.0;
const CROSSHAIR_KIND_OUTLINE: f32 = 1.0;
const CROSSHAIR_KIND_DISC: f32 = 5.0;
const CROSSHAIR_KIND_DISC_OUTLINE: f32 = 6.0;
const CROSSHAIR_KIND_GLYPH: f32 = 2.0;
const CROSSHAIR_KIND_GLYPH_BLACK: f32 = 3.0;
const CROSSHAIR_KIND_GLYPH_WHITE: f32 = 4.0;

// s. App::area_font_scope: stellt beim Fallen die vorige Messschrift wieder her.
struct LayoutFontScope<'a> {
    gpu: &'a GpuState,
    vorher: Option<FontKind>,
    ruhig_vorher: bool,
}

impl Drop for LayoutFontScope<'_> {
    fn drop(&mut self) {
        self.gpu.set_layout_font(self.vorher);
        self.gpu.plain_numbers.set(self.ruhig_vorher);
    }
}

// Eine HUD-Zahl, die im Fadenkreuz-Pass gezeichnet wird (Schild-Countdown, Pfeile): so kann
// sie die Gegenfarbe zum Untergrund bekommen wie das Kreuz selbst.
struct CrosshairText {
    text: String,
    // Mitte in Bildschirmpixeln.
    center_px: (f32, f32),
    scale: f32,
    // true = weiss mit schwarzer Kontur, false = Fadenkreuz-Farbe (Kontur nur, wenn das
    // Fadenkreuz eine hat).
    white: bool,
    // Schrift (GpuState::hud_font).
    font: FontKind,
    alpha: f32,
}

// Zustand des Pixel-Editors: Malmodus und der laufende Strich (gesetzter Wert, letzter Pixel).
struct CrosshairPainter {
    symmetry: crosshair_editor::Symmetry,
    stroke: Option<(crosshair_editor::Pixel, (i32, i32))>,
}

impl Default for CrosshairPainter {
    fn default() -> Self {
        Self { symmetry: crosshair_editor::Symmetry::Quad, stroke: None }
    }
}

// Ein eigenes Fadenkreuz fuer den Fadenkreuz-Pass: Laeufe (x, y, Breite) relativ zur Mitte.
struct CustomCrosshair {
    fill: Vec<(i32, i32, i32)>,
    outline: Vec<(i32, i32, i32)>,
}

// Pixel-genau, je Lauf ein Viereck: Kontur zuerst, dann die Fuellung.
fn custom_crosshair_vertices(c: &CustomCrosshair, center_px: (f32, f32), screen_px: (f32, f32)) -> Vec<CrosshairVertex> {
    let mut out = Vec::with_capacity((c.fill.len() + c.outline.len()) * 6);
    for (laeufe, art) in [(&c.outline, 1.0), (&c.fill, CROSSHAIR_KIND_FILL)] {
        for &(x, y, w) in laeufe {
            let (x0, y0) = (center_px.0 + x as f32, center_px.1 + y as f32);
            out.extend(crosshair_quad_verts(x0, y0, x0 + w as f32, y0 + 1.0, screen_px, art));
        }
    }
    out
}

// Alles, was der Fadenkreuz-Pass ausser dem Kreuz zeichnet.
#[derive(Default)]
struct CrosshairExtras {
    // Eigenes Fadenkreuz statt des eingebauten (s. crosshair_editor).
    custom: Option<CustomCrosshair>,
    // Form und Groesse des eingebauten (s. CROSSHAIR_SHAPES); Groesse 0 = Standard des Kreuzes.
    shape: usize,
    size: u32,
    texts: Vec<CrosshairText>,
    // Schild-Cooldown als Kreis: Mitte (normiert) und verbleibender Anteil 0..1.
    ring: Option<((f32, f32), f32)>,
    // Kontur um den Ring (Settings::crosshair_ring_outline).
    ring_outline: bool,
    // Feuer-Modus "Fadenkreuz" beim Brennen: diese Farbe nur fuer Kreuz und Ring -- die
    // Zahlen (Pfeile, Countdown) behalten die normale Fadenkreuz-Farbe.
    fire_rgb: Option<[f32; 3]>,
}

// Ring um `center_px`, ab 12 Uhr im Uhrzeigersinn bis `fraction` des Umfangs (verbleibende
// Zeit) -- als Segment-Vierecke. Mit Kontur zuerst ein breiterer schwarzer Ring.
fn crosshair_ring_vertices(center_px: (f32, f32), fraction: f32, screen_px: (f32, f32), outline: bool) -> Vec<CrosshairVertex> {
    let fraction = fraction.clamp(0.0, 1.0);
    let n = ((SHIELD_RING_SEGMENTS as f32 * fraction).ceil() as usize).max(1);
    let mut out = Vec::new();
    let mut ring = |inner: f32, outer: f32, kind: f32| {
        for i in 0..n {
            let a0 = std::f32::consts::TAU * fraction * i as f32 / n as f32;
            let a1 = std::f32::consts::TAU * fraction * (i + 1) as f32 / n as f32;
            // 0 = oben, im Uhrzeigersinn (Bildschirm-y zeigt nach unten).
            let p = |a: f32, r: f32| (center_px.0 + r * a.sin(), center_px.1 - r * a.cos());
            let (i0, o0, o1, i1) = (p(a0, inner), p(a0, outer), p(a1, outer), p(a1, inner));
            let v = |(x, y): (f32, f32)| CrosshairVertex {
                position: pixel_to_ndc(x, y, screen_px),
                uv: [x / screen_px.0, y / screen_px.1],
                glyph_uv: [0.0, 0.0],
                kind,
                alpha: 1.0,
                circle: [0.0; 2],
            };
            out.extend_from_slice(&[v(i0), v(o0), v(o1), v(i0), v(o1), v(i1)]);
        }
    };
    let (r, t) = (SHIELD_RING_RADIUS_PX, SHIELD_RING_THICKNESS_PX / 2.0);
    if outline {
        ring(r - t - CROSSHAIR_OUTLINE_PX, r + t + CROSSHAIR_OUTLINE_PX, 1.0);
    }
    ring(r - t, r + t, CROSSHAIR_KIND_FILL);
    out
}

// UV hier ist die ABSOLUTE Position im gesamten offscreen_view (0..1 ueber den ganzen
// Bildschirm), nicht mehr relativ zu einem kleinen Kopierbereich.
fn crosshair_quad_verts(x0: f32, y0: f32, x1: f32, y1: f32, screen_px: (f32, f32), outline: f32) -> [CrosshairVertex; 6] {
    let uv_of = |px: f32, py: f32| [px / screen_px.0, py / screen_px.1];
    let to_vert =
        |px: f32, py: f32| CrosshairVertex { position: pixel_to_ndc(px, py, screen_px), uv: uv_of(px, py), glyph_uv: [0.0, 0.0], kind: outline, alpha: 1.0, circle: [0.0; 2] };
    [to_vert(x0, y0), to_vert(x1, y0), to_vert(x1, y1), to_vert(x0, y0), to_vert(x1, y1), to_vert(x0, y1)]
}

// Hoechstzahl der Vertices im Fadenkreuz-Pass: Kreuz mit Kontur (24), der Schild-Kreis (48
// Segmente, mit Kontur doppelt) und Glyphen-Text (je Zeichen mit Kontur 9 Vierecke) --
// reichlich bemessen. (Frueher stand hier eine eigene 3x5-Pixelschrift fuer den Countdown;
// jetzt kommen die Glyphen aus dem Font-Atlas, s. GpuState::crosshair_glyph_vertices.)
// Ein eigenes Kreuz (s. crosshair_editor) kann bis zu GRID*GRID/2 Laeufe haben.
const CROSSHAIR_MAX_VERTICES: usize = 4096 + crosshair_editor::GRID * crosshair_editor::GRID * 3;

// Das eingebaute Fadenkreuz um `center_px` (Bildschirmpixel, die Bildmitte samt Wackeln),
// aus den Bausteinen von crosshair_parts: Balken als Vierecke,
// Kreise als Viereck um den Kreis, dessen Kante der Shader je Pixel ausrechnet.
//
// ECHTER BUG gewesen: die Kontur lief zuerst ueber die normalen UI-Rechtecke. Der HUD-Pass
// zeichnet aber in DIESELBE Offscreen-Textur, die der Fadenkreuz-Pass danach abtastet, um die
// Gegenfarbe zu bestimmen. Unter dem Kreuz stand damit ueberall die eigene schwarze Kontur;
// Schwarz hat keinen definierten Farbton (rgb_to_hue faellt auf 0 zurueck), also kam immer
// dieselbe Farbe heraus. Jetzt entsteht die Kontur im Fadenkreuz-Pass selbst -- also NACH dem
// Abtasten und damit unsichtbar fuer die eigene Farbwahl.
fn crosshair_vertices(shape: usize, size: u32, center_px: (f32, f32), screen_px: (f32, f32), outline: bool) -> Vec<CrosshairVertex> {
    let mut out = Vec::new();
    for (teil, kontur) in crosshair_parts(shape, size, center_px, outline) {
        match teil {
            CrosshairPart::Bar(r) => {
                let art = if kontur { CROSSHAIR_KIND_OUTLINE } else { CROSSHAIR_KIND_FILL };
                out.extend(crosshair_quad_verts(r.x, r.y, r.x + r.w, r.y + r.h, screen_px, art));
            }
            CrosshairPart::Disc { center, inner, outer } => {
                // Ein Pixel mehr als der Radius: Platz fuer die weiche Kante.
                let e = outer + 1.0;
                let kind = if kontur { CROSSHAIR_KIND_DISC_OUTLINE } else { CROSSHAIR_KIND_DISC };
                let v = |dx: f32, dy: f32| {
                    let (px, py) = (center.0 + dx, center.1 + dy);
                    CrosshairVertex {
                        position: pixel_to_ndc(px, py, screen_px),
                        uv: [px / screen_px.0, py / screen_px.1],
                        glyph_uv: [dx, dy],
                        kind,
                        alpha: 1.0,
                        circle: [inner, outer],
                    }
                };
                out.extend_from_slice(&[v(-e, -e), v(e, -e), v(e, e), v(-e, -e), v(e, e), v(-e, e)]);
            }
        }
    }
    out
}

fn rotate_point(p: (f32, f32), center: (f32, f32), degrees: f32) -> (f32, f32) {
    let (sin, cos) = degrees.to_radians().sin_cos();
    let (dx, dy) = (p.0 - center.0, p.1 - center.1);
    (center.0 + dx * cos - dy * sin, center.1 + dx * sin + dy * cos)
}

// Die Punkte des Zeigers in Bildschirm-Pixeln: erst die Kite-Form, dann der Griff. `tip_pos` ist die Position, an der die
// Pfeilspitze sitzt -- das ist die uebliche Hotspot-Konvention: der Klickpunkt ist die
// Spitze der Form, nicht die Mitte ihrer Bounding-Box.
// `fx_scale` staucht den Zeiger beim Druecken, `fx_rotation_deg` dreht ihn beim Ziehen und
// `fx_additive` faerbt den Kern beim Druecken in der Akzentfarbe -- alle drei kommen aus cursor_fx und sind 1.0 / 0.0 /
// 0.0, solange nichts passiert.
//
// Gedreht und skaliert wird um die SPITZE, nicht um die Mitte: die Spitze ist der Punkt, auf
// den man zeigt, und der darf sich beim Klicken nicht verschieben.
// Ersetzt die Ecke `corner` (zwischen `prev` und `next`) durch einen Kreisbogen mit Radius
// `r`, der beide Kanten tangential beruehrt -- als `n` Punkte von der prev- zur next-Seite.
fn round_corner(prev: (f32, f32), corner: (f32, f32), next: (f32, f32), r: f32, n: usize) -> Vec<(f32, f32)> {
    let unit = |p: (f32, f32)| {
        let (dx, dy) = (p.0 - corner.0, p.1 - corner.1);
        let len = (dx * dx + dy * dy).sqrt();
        (dx / len, dy / len)
    };
    let (u1, u2) = (unit(prev), unit(next));
    let halb = (u1.0 * u2.0 + u1.1 * u2.1).clamp(-1.0, 1.0).acos() / 2.0;
    let tangente = r / halb.tan();
    let bis = {
        let (bx, by) = (u1.0 + u2.0, u1.1 + u2.1);
        let len = (bx * bx + by * by).sqrt();
        (bx / len, by / len)
    };
    let mitte = (corner.0 + bis.0 * r / halb.sin(), corner.1 + bis.1 * r / halb.sin());
    let winkel = |p: (f32, f32)| (p.1 - mitte.1).atan2(p.0 - mitte.0);
    let a0 = winkel((corner.0 + u1.0 * tangente, corner.1 + u1.1 * tangente));
    let a1 = winkel((corner.0 + u2.0 * tangente, corner.1 + u2.1 * tangente));
    // Den kurzen Weg um die Aussenseite der Ecke nehmen.
    let mut spanne = a1 - a0;
    if spanne > std::f32::consts::PI {
        spanne -= std::f32::consts::TAU;
    } else if spanne < -std::f32::consts::PI {
        spanne += std::f32::consts::TAU;
    }
    (0..n)
        .map(|i| {
            let a = a0 + spanne * i as f32 / (n - 1) as f32;
            (mitte.0 + r * a.cos(), mitte.1 + r * a.sin())
        })
        .collect()
}

// Der Pfeil-Umriss im 100x130-Raum (noch ungedreht): CURSOR_KITE mit abgerundeten Fluegeln,
// die Fluegel um `breite` von der Mittelachse (x = 50) weg gestreckt.
fn cursor_kite_outline(breite: f32) -> Vec<(f32, f32)> {
    let [spitze, rechts, kerbe, links] = CURSOR_KITE;
    let strecken = |(x, y): (f32, f32)| (50.0 + (x - 50.0) * breite, y);
    let (rechts, links) = (strecken(rechts), strecken(links));
    let mut out = vec![spitze];
    out.extend(round_corner(spitze, rechts, kerbe, CURSOR_WING_RADIUS, CURSOR_WING_ARC_POINTS));
    out.push(kerbe);
    out.extend(round_corner(kerbe, links, spitze, CURSOR_WING_RADIUS, CURSOR_WING_ARC_POINTS));
    out
}

fn cursor_polygons(tip_pos: (f32, f32), screen_px: (f32, f32), fx: CursorFxFrame) -> CursorUniform {
    let (fx_scale, fx_rotation_deg, fx_additive) = (fx.scale, fx.rotation_deg, fx.additive);
    let local_center = (50.0, 50.0);
    let rotate = |p: (f32, f32)| rotate_point(p, local_center, CURSOR_ROTATION_DEG);

    let kite: Vec<(f32, f32)> = cursor_kite_outline(fx.width).into_iter().map(rotate).collect();
    let tip = rotate(CURSOR_KITE[0]);

    let scale = CURSOR_HEIGHT_PX / 130.0 * fx_scale;
    // lokal (rotiert, unskaliert) -> Bildschirm-Pixel: skalieren, um die Spitze drehen, dann
    // so verschieben, dass die Spitze exakt auf tip_pos landet.
    let (sin_fx, cos_fx) = fx_rotation_deg.to_radians().sin_cos();
    let to_screen = |p: (f32, f32)| {
        let (dx, dy) = ((p.0 - tip.0) * scale, (p.1 - tip.1) * scale);
        (tip_pos.0 + dx * cos_fx - dy * sin_fx, tip_pos.1 + dx * sin_fx + dy * cos_fx)
    };

    let mitte = to_screen(rotate(CURSOR_CIRCLE_CENTER));
    let tail = [mitte, mitte];
    // Ohne Kreis: ein stark negativer Radius -- der Abstand zur "Kapsel" ist dann ueberall
    // riesig, sie deckt nichts ab. Die Zeichenflaeche richtet sich nur nach dem Pfeil.
    let tail_radius = if fx.circle { CURSOR_CIRCLE_RADIUS * scale } else { -1.0e6 };
    let flat: Vec<(f32, f32)> = kite.iter().map(|&p| to_screen(p)).chain(tail).collect();
    debug_assert_eq!(flat.len(), CURSOR_POINTS);
    let colors = [COLOR_CURSOR_OUTLINE, COLOR_CURSOR_FILL];

    // Je zwei Punkte teilen sich ein vec4 (s. cursor.wgsl: Uniform-Arrays brauchen
    // 16-Byte-Schrittweite, ein Array aus vec2 waere sonst mit Fuellbytes durchsetzt).
    let mut points = [[0.0; 4]; CURSOR_POINTS / 2];
    for (i, &(x, y)) in flat.iter().enumerate() {
        points[i / 2][(i % 2) * 2] = x;
        points[i / 2][(i % 2) * 2 + 1] = y;
    }

    // Zeichenflaeche = Bounding-Box aller Punkte plus Rand, damit die Kantenglaettung
    // (greift bis ~0.5 px ausserhalb der Form) nicht am Quadrand abgeschnitten wird.
    let (mut x0, mut y0, mut x1, mut y1) = (f32::MAX, f32::MAX, f32::MIN, f32::MIN);
    let r = tail_radius.max(0.0);
    let kapselrand = tail.iter().flat_map(|&(x, y)| [(x - r, y - r), (x + r, y + r)]);
    let pfeil = if fx.circle { &flat[..] } else { &flat[..CURSOR_KITE_POINTS] };
    for (x, y) in pfeil.iter().copied().chain(kapselrand) {
        x0 = x0.min(x);
        y0 = y0.min(y);
        x1 = x1.max(x);
        y1 = y1.max(y);
    }
    let pad = CURSOR_AA_PADDING_PX;
    // Die Akzentfarbe des Themes (schon linear, wie die Oberflaeche rechnet).
    let [ar, ag, ab, _] = theme::get(theme::Slot::Accent);
    let kontur = CURSOR_OUTLINE_PX;
    CursorUniform {
        points,
        colors,
        additive: [ar, ag, ab, fx_additive * CURSOR_PRESS_TINT],
        bounds: [x0 - pad, y0 - pad, x1 + pad, y1 + pad],
        screen: [screen_px.0, screen_px.1, kontur, tail_radius],
    }
}

#[repr(C)]
#[derive(Copy, Clone, bytemuck::Pod, bytemuck::Zeroable)]
struct TextVertex {
    position: [f32; 2],
    uv: [f32; 2],
    color: [f32; 4],
    // Nur fuer Kontur/Schatten (s. font.wgsl): Atlas-Rechteck des Glyphen und die Art samt
    // UV je Bildschirmpixel. Alles 0 = gewoehnlicher Glyph bzw. Sprite.
    bounds: [f32; 4],
    mode: [f32; 4],
}

// Wie Text einen Rand bekommt. Kontur = duenne schwarze Linie rundherum (eigene Vorgabe),
// Vanilla = Minecrafts Schatten ein Schriftpixel nach rechts unten in einem Viertel der
// Textfarbe.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum TextShadow {
    Outline,
    Vanilla,
    // Weicher Schatten unter dem Text, wie in osu!: nach unten versetzt und verschwommen.
    Below,
    // Derselbe weiche Schatten ohne Versatz: rundherum gleich stark.
    Around,
    Off,
}

impl TextShadow {
    fn label(self) -> &'static str {
        match self {
            TextShadow::Outline => "Kontur",
            TextShadow::Vanilla => "Vanilla",
            TextShadow::Below => "Unten",
            TextShadow::Around => "Außen",
            TextShadow::Off => "Aus",
        }
    }
}

// Die Bereiche, deren Textrand sich eigens einstellen laesst (Settings::area_shadow). Je
// Bereich 0 = wie die allgemeine Einstellung, 1 = Kontur, 2 = Vanilla, 3 = aus.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ShadowArea {
    Chat,
    Hotbar,
    PlayerList,
    Scoreboard,
    Inventory,
    Title,
    ActionBar,
    ShieldCountdown,
    ArrowNumber,
    // Die FPS-Anzeige (Modul unter Debug, s. push_hud_perf_texts).
    Fps,
    // Name und Timer der detaillierten Effekt-Anzeige (s. build_effect_hud).
    Effects,
    // Namensschilder ueber Entities und Text-Displays (s. build_world_labels).
    Nametags,
    // Text auf Schildern in der Welt (s. build_sign_texts).
    Signs,
    // Die Haltbarkeitszahlen des Ruestungs-HUD (s. push_armor_hud).
    ArmorHud,
}

const TEXT_AREA_COUNT: usize = 14;

// Schildtext je Bild hoechstens (Vertices, mit Kontur 9 Vierecke je Zeichen).
const MAX_SIGN_TEXT_VERTICES: usize = 65_536;

impl ShadowArea {
    // Reihenfolge = Index in Settings::area_shadow/area_font und Zeile im Schrift-Tab -- neue
    // Bereiche hinten anhaengen.
    const ALL: [ShadowArea; TEXT_AREA_COUNT] = [
        ShadowArea::Chat,
        ShadowArea::Hotbar,
        ShadowArea::PlayerList,
        ShadowArea::Scoreboard,
        ShadowArea::Inventory,
        ShadowArea::Title,
        ShadowArea::ActionBar,
        ShadowArea::ShieldCountdown,
        ShadowArea::ArrowNumber,
        ShadowArea::Fps,
        ShadowArea::Effects,
        ShadowArea::Nametags,
        ShadowArea::Signs,
        ShadowArea::ArmorHud,
    ];

    // Schild-Countdown und Pfeil-Zahl haben statt eines Randes ihre eigene Faerbung (s.
    // HUD_TEXT_STYLE_NAMES) -- dort gibt es nur die Schrift.
    fn has_shadow(self) -> bool {
        !matches!(self, ShadowArea::ShieldCountdown | ShadowArea::ArrowNumber)
    }

    fn index(self) -> usize {
        self as usize
    }

    // Text, der sich nicht aendert: dort halten Zahlen keinen Platz frei (s.
    // push_plain_numbers_marker).
    fn plain_numbers(self) -> bool {
        self == ShadowArea::Chat
    }

    fn label(self) -> &'static str {
        match self {
            ShadowArea::Chat => "Chat",
            ShadowArea::Hotbar => "Hotbar",
            ShadowArea::PlayerList => "Spielerliste",
            ShadowArea::Scoreboard => "Scoreboard",
            ShadowArea::Inventory => "Inventar",
            ShadowArea::Title => "Titel",
            ShadowArea::ActionBar => "Actionbar",
            ShadowArea::ShieldCountdown => "Schild-Countdown",
            ShadowArea::ArrowNumber => "Pfeil-Zahl",
            ShadowArea::Fps => "FPS-Anzeige",
            ShadowArea::Effects => "Effekte",
            ShadowArea::Nametags => "Nametags",
            ShadowArea::Signs => "Schilder",
            ShadowArea::ArmorHud => "Rüstungs-HUD",
        }
    }

    fn key(self) -> &'static str {
        match self {
            ShadowArea::Chat => "shadow_chat",
            ShadowArea::Hotbar => "shadow_hotbar",
            ShadowArea::PlayerList => "shadow_player_list",
            ShadowArea::Scoreboard => "shadow_scoreboard",
            ShadowArea::Inventory => "shadow_inventory",
            ShadowArea::Title => "shadow_title",
            ShadowArea::ActionBar => "shadow_actionbar",
            ShadowArea::ShieldCountdown => "shadow_shield_cd",
            ShadowArea::ArrowNumber => "shadow_arrow_number",
            ShadowArea::Fps => "shadow_fps",
            ShadowArea::Effects => "shadow_effects",
            ShadowArea::Nametags => "shadow_nametags",
            ShadowArea::Signs => "shadow_signs",
            ShadowArea::ArmorHud => "shadow_armor_hud",
        }
    }

    // Schluessel der eigenen Schrift in settings.conf (s. Settings::area_font).
    fn font_key(self) -> &'static str {
        match self {
            ShadowArea::Chat => "font_chat",
            ShadowArea::Hotbar => "font_hotbar",
            ShadowArea::PlayerList => "font_player_list",
            ShadowArea::Scoreboard => "font_scoreboard",
            ShadowArea::Inventory => "font_inventory",
            ShadowArea::Title => "font_title",
            ShadowArea::ActionBar => "font_actionbar",
            ShadowArea::ShieldCountdown => "font_shield_cd",
            ShadowArea::ArrowNumber => "font_arrow_number",
            ShadowArea::Fps => "font_fps",
            ShadowArea::Effects => "font_effects",
            ShadowArea::Nametags => "font_nametags",
            ShadowArea::Signs => "font_signs",
            ShadowArea::ArmorHud => "font_armor_hud",
        }
    }
}

const AREA_SHADOW_CHOICES: u8 = 6;

// Dicke der Kontur in Zehntelpixeln (s. Settings::shadow_thickness): Vorgabe und Bereich.
const SHADOW_THICKNESS_DEFAULT: u8 = 10;
const SHADOW_THICKNESS_RANGE: (u8, u8) = (5, 40);

// Wert je Bereich -> Rand; None = allgemeine Einstellung.
fn area_shadow_style(v: u8) -> Option<TextShadow> {
    match v {
        1 => Some(TextShadow::Outline),
        2 => Some(TextShadow::Vanilla),
        3 => Some(TextShadow::Off),
        4 => Some(TextShadow::Below),
        5 => Some(TextShadow::Around),
        _ => None,
    }
}

// Umkehrung von area_shadow_style.
fn area_shadow_code(stil: TextShadow) -> u8 {
    (1..AREA_SHADOW_CHOICES).find(|&v| area_shadow_style(v) == Some(stil)).unwrap_or(0)
}

// Schrift je Bereich: 0 = die allgemeine, sonst FontKind-Index + 1.
fn area_font_kind(v: u8) -> Option<FontKind> {
    (v > 0).then(|| FontKind::ALL.get(v as usize - 1).copied()).flatten()
}

fn area_font_code(font: Option<FontKind>) -> u8 {
    font.and_then(|k| FontKind::ALL.iter().position(|&f| f == k)).map_or(0, |i| i as u8 + 1)
}

// Was man im Schrift-Tab in ein Kaestchen zieht: eine Schrift oder einen Rand.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FontTile {
    Font(FontKind),
    Shadow(TextShadow),
}

impl FontTile {
    // Die Auswahl rechts, in ihrer Reihenfolge: erst die Schriften, dann die Raender.
    fn palette() -> impl Iterator<Item = FontTile> {
        let raender = [TextShadow::Outline, TextShadow::Vanilla, TextShadow::Below, TextShadow::Around, TextShadow::Off];
        FontKind::ALL.into_iter().map(FontTile::Font).chain(raender.into_iter().map(FontTile::Shadow))
    }

    fn label(self) -> &'static str {
        match self {
            FontTile::Font(k) => k.label(),
            FontTile::Shadow(s) => s.label(),
        }
    }

    fn box_w(self) -> f32 {
        match self {
            FontTile::Font(_) => FONT_BOX_W,
            FontTile::Shadow(_) => SHADOW_BOX_W,
        }
    }
}

// Ein Kaestchen im Schrift-Tab: Standard-Schrift und -Schatten (nie leer) oder die Ausnahme
// eines Bereichs (leer = wie der Standard).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum FontSlot {
    DefaultFont,
    DefaultShadow,
    AreaFont(ShadowArea),
    AreaShadow(ShadowArea),
}

impl FontSlot {
    fn all() -> impl Iterator<Item = FontSlot> {
        let bereiche = ShadowArea::ALL.into_iter().flat_map(|a| {
            let rand = a.has_shadow().then_some(FontSlot::AreaShadow(a));
            std::iter::once(FontSlot::AreaFont(a)).chain(rand)
        });
        [FontSlot::DefaultFont, FontSlot::DefaultShadow].into_iter().chain(bereiche)
    }

    fn accepts(self, tile: FontTile) -> bool {
        match self {
            FontSlot::DefaultFont | FontSlot::AreaFont(_) => matches!(tile, FontTile::Font(_)),
            FontSlot::DefaultShadow | FontSlot::AreaShadow(_) => matches!(tile, FontTile::Shadow(_)),
        }
    }

    fn is_default(self) -> bool {
        matches!(self, FontSlot::DefaultFont | FontSlot::DefaultShadow)
    }

    // Zeile im Schrift-Tab und linke Kante.
    fn cell(self) -> (usize, f32) {
        match self {
            FontSlot::DefaultFont => (0, FONT_CTRL_X),
            FontSlot::DefaultShadow => (0, FONT_SHADOW_X),
            FontSlot::AreaFont(a) => (FONT_EXCEPTIONS_ROW + a.index(), FONT_CTRL_X),
            FontSlot::AreaShadow(a) => (FONT_EXCEPTIONS_ROW + a.index(), FONT_SHADOW_X),
        }
    }

    // In Inhaltskoordinaten; None, solange die Zeile weggescrollt ist.
    fn rect(self) -> Option<Rect> {
        let (row, x) = self.cell();
        let y = settings_row_y(row);
        let w = match self {
            FontSlot::DefaultFont | FontSlot::AreaFont(_) => FONT_BOX_W,
            FontSlot::DefaultShadow | FontSlot::AreaShadow(_) => SHADOW_BOX_W,
        };
        (y >= 0.0).then(|| Rect { x, y: y - (FONT_SLOT_H - SETTINGS_CTRL_H) / 2.0, w, h: FONT_SLOT_H })
    }
}

// Ein Kaestchen, das gerade gezogen wird (s. App::font_drag): was, woher (None = aus der
// Auswahl rechts), und wo der Zeiger es gepackt hat.
#[derive(Clone, Copy, Debug)]
struct FontDrag {
    tile: FontTile,
    from: Option<FontSlot>,
    grab: (f32, f32),
}

// Die Auswahl rechts im Schrift-Tab (s. App::font_palette): linke Kante, Ueberschriften mit
// ihrer Oberkante, die Kaestchen, und wo darunter Platz fuer die Erklaerungen ist.
struct FontPalette {
    x: f32,
    headings: Vec<(&'static str, f32)>,
    tiles: Vec<(FontTile, Rect)>,
    // Strich zwischen Schriften und Schatten und das Raster der Schatten.
    lines: Vec<Rect>,
    bottom: f32,
}

// Hoehe des Namensfelds unter der Probe in den Kacheln der Auswahl.
fn font_palette_name_h(gpu: &GpuState) -> f32 {
    (gpu.text_height(UI_SCALE_SMALL) + 12.0).round()
}

const TEXT_MODE_GLYPH: f32 = 0.0;
const TEXT_MODE_OUTLINE: f32 = 1.0;
const TEXT_MODE_SHADOW: f32 = 2.0;
// Reglerstand der weichen Raender ("Unten", "Aussen"), der ihrer frueheren vollen Staerke
// entspricht -- darueber werden sie kraeftiger.
const SOFT_SHADOW_FULL_PERCENT: f32 = 40.0;
const TEXT_MODE_BELOW: f32 = 3.0;
const TEXT_MODE_AROUND: f32 = 4.0;
// Auf die Art addiert: farbiges Bild aus dem Pack-Glyphenblatt (s. font.wgsl).
const TEXT_MODE_PACK: f32 = 8.0;

#[allow(clippy::too_many_arguments)]
fn text_quad(
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
    uv_min: [f32; 2],
    uv_max: [f32; 2],
    color: [f32; 4],
    screen_px: (f32, f32),
) -> [TextVertex; 6] {
    text_quad_fx(x0, y0, x1, y1, uv_min, uv_max, color, [0.0; 4], [TEXT_MODE_GLYPH, 0.0, 0.0, 0.0], screen_px)
}

// Glyphen-Vierecke als farbiges Pack-Bild kennzeichnen (s. font.wgsl: Art + TEXT_MODE_PACK).
fn mark_pack_glyph(verts: &mut [TextVertex]) {
    for v in verts {
        v.mode[0] += TEXT_MODE_PACK;
    }
}

// Wie text_quad, mit Glyphen-Rechteck und Art fuer Kontur/Schatten (s. font.wgsl).
#[allow(clippy::too_many_arguments)]
fn text_quad_fx(
    x0: f32,
    y0: f32,
    x1: f32,
    y1: f32,
    uv_min: [f32; 2],
    uv_max: [f32; 2],
    color: [f32; 4],
    bounds: [f32; 4],
    mode: [f32; 4],
    screen_px: (f32, f32),
) -> [TextVertex; 6] {
    let (w, h) = screen_px;
    let to_ndc = |px: f32, py: f32, u: f32, v: f32| TextVertex { position: [(px / w) * 2.0 - 1.0, 1.0 - (py / h) * 2.0], uv: [u, v], color, bounds, mode };
    [
        to_ndc(x0, y0, uv_min[0], uv_min[1]),
        to_ndc(x1, y0, uv_max[0], uv_min[1]),
        to_ndc(x1, y1, uv_max[0], uv_max[1]),
        to_ndc(x0, y0, uv_min[0], uv_min[1]),
        to_ndc(x1, y1, uv_max[0], uv_max[1]),
        to_ndc(x0, y1, uv_min[0], uv_max[1]),
    ]
}

// Fuer render_world (s. dortigen Kommentar zu offscreen_texture) -- RENDER_ATTACHMENT zum
// Hineinzeichnen (Welt+HUD), COPY_SRC fuer den Blit zur Swapchain-Textur, TEXTURE_BINDING
// weil der Crosshair-Shader direkt daraus sampelt (s. crosshair_vertices-Kommentar). Bei
// jedem resize() mit neuer Groesse neu erzeugt.
fn create_offscreen_texture(
    device: &wgpu::Device,
    format: wgpu::TextureFormat,
    width: u32,
    height: u32,
) -> (wgpu::Texture, wgpu::TextureView) {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("offscreen color texture"),
        size: wgpu::Extent3d { width: width.max(1), height: height.max(1), depth_or_array_layers: 1 },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format,
        usage: wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC | wgpu::TextureUsages::TEXTURE_BINDING,
        // Dasselbe Bild ohne sRGB-Umrechnung: darin mischt der Pack-Himmel im Gamma-Raum
        // (s. render::custom_sky).
        view_formats: &[format.remove_srgb_suffix()],
    });
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    (texture, view)
}

// Ausgabetextur des CMAA2-Compute-Durchgangs (s. cmaa2.wgsl) -- bewusst Rgba8Unorm (linear,
// KEIN sRGB-Suffix): WebGPU erlaubt keine Speicher-Texturen in sRGB-Formaten, anders als
// offscreen_texture. STORAGE_BINDING zum Hineinschreiben (Compute), TEXTURE_BINDING zum
// Herauslesen (Blit-Fragment-Shader, s. cmaa2_blit.wgsl). Bei jedem resize() neu erzeugt.
fn create_cmaa2_output_texture(device: &wgpu::Device, width: u32, height: u32) -> (wgpu::Texture, wgpu::TextureView) {
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("cmaa2 output texture"),
        size: wgpu::Extent3d { width: width.max(1), height: height.max(1), depth_or_array_layers: 1 },
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba8Unorm,
        usage: wgpu::TextureUsages::STORAGE_BINDING | wgpu::TextureUsages::TEXTURE_BINDING,
        view_formats: &[],
    });
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    (texture, view)
}

// Haengt an den konkreten offscreen_view/cmaa2_output_view-Identitaeten -- bei jedem
// resize() (neue Texturen, neue Views) neu erzeugt.
fn create_cmaa2_compute_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    offscreen_view: &wgpu::TextureView,
    cmaa2_output_view: &wgpu::TextureView,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("cmaa2 compute bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(offscreen_view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::TextureView(cmaa2_output_view) },
        ],
    })
}

// Fuer den Blit-Durchgang (s. cmaa2_blit.wgsl) -- haengt an der cmaa2_output_view-Identitaet,
// bei jedem resize() neu erzeugt.
fn create_cmaa2_blit_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    cmaa2_output_view: &wgpu::TextureView,
    sampler: &wgpu::Sampler,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("cmaa2 blit bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(cmaa2_output_view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
        ],
    })
}

// Fuer den Farb-Durchgang (s. color.wgsl) -- haengt an der offscreen_view-Identitaet, bei
// jedem resize() neu erzeugt.
fn create_color_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    offscreen_view: &wgpu::TextureView,
    settings_buffer: &wgpu::Buffer,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("color bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(offscreen_view) },
            wgpu::BindGroupEntry { binding: 1, resource: settings_buffer.as_entire_binding() },
        ],
    })
}

// Haengt an einer konkreten offscreen_view-Identitaet -- bei jedem resize() (neue Textur,
// neue View) neu erzeugt.
fn create_crosshair_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    offscreen_view: &wgpu::TextureView,
    sampler: &wgpu::Sampler,
    mode_buffer: &wgpu::Buffer,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("crosshair bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(offscreen_view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
            wgpu::BindGroupEntry { binding: 2, resource: mode_buffer.as_entire_binding() },
        ],
    })
}

struct GpuState {
    surface: wgpu::Surface<'static>,
    // Arc: der Animations-Thread laedt selbst in den Atlas hoch (s. block_anim::UploadTarget).
    device: std::sync::Arc<wgpu::Device>,
    queue: std::sync::Arc<wgpu::Queue>,
    config: wgpu::SurfaceConfiguration,
    window: Arc<Window>,
    offscreen_texture: wgpu::Texture,
    offscreen_view: wgpu::TextureView,
    quad_pipeline: wgpu::RenderPipeline,
    quad_vertex_buffer: wgpu::Buffer,
    line_vertex_buffer: wgpu::Buffer,
    // Mauszeiger: eigene Pipeline mit analytischer Kantenglaettung (s. cursor.wgsl) --
    // ein Quad ueber der Bounding-Box, die Form entsteht im Fragment-Shader aus dem Uniform.
    cursor_pipeline: wgpu::RenderPipeline,
    cursor_uniform_buffer: wgpu::Buffer,
    cursor_bind_group: wgpu::BindGroup,
    // Crosshair-Invertierung per direktem Sampling aus offscreen_view + Fragment-Shader
    // statt GPU-Blend-Trick (s. crosshair_vertices-Kommentar): die Pipeline sampelt
    // offscreen_view direkt (kein Kopierschritt mehr) und gibt 1-Farbe aus. Der Bind-Group
    // haengt an einer konkreten TextureView-Identitaet -- bei jedem resize() neu erzeugt.
    crosshair_pipeline: wgpu::RenderPipeline,
    crosshair_vertex_buffer: wgpu::Buffer,
    crosshair_bind_group_layout: wgpu::BindGroupLayout,
    crosshair_sampler: wgpu::Sampler,
    crosshair_mode_buffer: wgpu::Buffer,
    crosshair_bind_group: wgpu::BindGroup,
    // CMAA2 (s. cmaa2.wgsl-Kommentar): Compute-Infrastruktur + gather-basierte,
    // kontrastadaptive Kantenglaettung.
    cmaa2_output_texture: wgpu::Texture,
    cmaa2_output_view: wgpu::TextureView,
    cmaa2_compute_pipeline: wgpu::ComputePipeline,
    cmaa2_compute_bind_group_layout: wgpu::BindGroupLayout,
    cmaa2_compute_bind_group: wgpu::BindGroup,
    cmaa2_blit_pipeline: wgpu::RenderPipeline,
    cmaa2_blit_bind_group_layout: wgpu::BindGroupLayout,
    cmaa2_blit_sampler: wgpu::Sampler,
    cmaa2_blit_bind_group: wgpu::BindGroup,
    // Modul "Farbe" (s. color.wgsl): ersetzt die Schlusskopie in die Swapchain, solange die
    // Saettigung nicht 100 % ist. Der Puffer haelt die Saettigung (16 Byte, s. Shader).
    color_pipeline: wgpu::RenderPipeline,
    color_bind_group_layout: wgpu::BindGroupLayout,
    color_settings_buffer: wgpu::Buffer,
    color_bind_group: wgpu::BindGroup,
    text_pipeline: wgpu::RenderPipeline,
    text_vertex_buffer: wgpu::Buffer,
    // Schildtext im Welt-Durchgang, mit Tiefentest (s. App::build_sign_texts): Pipeline,
    // Puffer, die Glyphen dieses Bildes und ihre Schrift (Bereich Schilder).
    world_text_pipeline: wgpu::RenderPipeline,
    sign_text_buffer: wgpu::Buffer,
    sign_glyphs: std::cell::RefCell<Vec<TextVertex>>,
    sign_font: std::cell::Cell<Option<FontKind>>,
    // Schrift der Weltbeschriftungen (Bereich Nametags), s. world_label_glyphs.
    label_font: std::cell::Cell<Option<FontKind>>,
    font_atlas: FontAtlas,
    // Weitere Atlanten in anderen Schriften, nur solange eine Anzeige oder ein Bereich sie
    // will (s. App::wanted_fonts und ensure_fonts). Teilen das Layout des ersten.
    extra_fonts: Vec<FontAtlas>,
    // Schriften der Resourcepacks (Server-HUD, Symbole), geteilt von allen Atlanten.
    pack_glyphs: Option<Arc<font_atlas::PackGlyphCache>>,
    // Mit welcher Schrift gerade gemessen wird (None = allgemeine): App setzt sie fuer die
    // Dauer eines Bereichs mit eigener Schrift (s. App::begin_text_area), shape_text folgt
    // den Schrift-Markern. So stimmen Layout und Zeichnen ueberein.
    layout_font: std::cell::Cell<Option<FontKind>>,
    // Gerade ruhiger Text (s. push_plain_numbers_marker): Messen ohne reservierten Platz.
    plain_numbers: std::cell::Cell<bool>,
    // Wie viele Sprites am Anfang der HUD-Liste UNTER allen Flaechen liegen (das Feuer vor
    // den Augen, s. App::build_fire_overlay) -- sonst verdeckte es Chat-Hintergrund und
    // Keystrokes. Von build_hud gesetzt, von render_world verbraucht.
    under_sprites: std::cell::Cell<usize>,
    // Allgemeiner Textrand (Settings::global_text_shadow), s. shape_text.
    text_shadow_style: TextShadow,
    // Staerke des allgemeinen Rands (s. Settings::shadow_strength).
    text_shadow_strength: f32,
    // Wo die Zeichen des zuletzt gezeichneten Textes stehen (s. shape_text, TextRun).
    text_runs: std::cell::RefCell<Vec<TextRun>>,
    // Welche Zahlen wechseln und wie viel Platz sie brauchen (s. stable_numbers). Lernt in
    // shape_text, wirkt in measure_text und shape_text.
    stable_numbers: std::cell::RefCell<stable_numbers::StableNumbers>,
    // Text-Displays als echte Flaechen in der Welt (s. App::build_display_text): schon auf
    // den Bildschirm projizierte Glyphen und Hintergruende. render_world nimmt sie je Bild
    // heraus und zeichnet sie VOR dem HUD (Glyphen vor dem HUD-Text, Hintergruende vor den
    // HUD-Flaechen).
    world_label_glyphs: std::cell::RefCell<Vec<TextVertex>>,
    world_label_quads: std::cell::RefCell<Vec<Vertex>>,
    // Texturierte 2D-Quads (Hotbar-/Inventar-Sheets, Item-Icons -- s. sprite.wgsl). Zwei
    // Bind-Groups gegen DENSELBEN Layout: der UI-Atlas (GUI + flache Item-Sprites) und der
    // Blockatlas (isometrische Blockitems). Eigener Nearest-Sampler ohne Mipmaps, damit
    // Pixel-Art in der Vergroesserung scharf bleibt -- der Welt-Sampler filtert linear.
    sprite_pipeline: wgpu::RenderPipeline,
    // Verzauberungs-Glint ueber Item-Icons (s. sprite.wgsl::fs_glint): additive Pipeline mit
    // demselben Vertex-Layout, dazu Glint-Textur, Sampler und die wandernde Matrix.
    glint_sprite_pipeline: wgpu::RenderPipeline,
    glint_gui_bind_group_layout: wgpu::BindGroupLayout,
    glint_gui_bind_group: wgpu::BindGroup,
    glint_gui_uniform: wgpu::Buffer,
    glint_gui_sampler: wgpu::Sampler,
    sprite_vertex_buffer: wgpu::Buffer,
    sprite_bind_group_layout: wgpu::BindGroupLayout,
    sprite_sampler: wgpu::Sampler,
    ui_atlas_bind_group: wgpu::BindGroup,
    // Die Textur dahinter, fuer die animierten Item-Bilder (s. App::advance_atlas_animations).
    ui_atlas_texture: wgpu::Texture,
    block_atlas_sprite_bind_group: wgpu::BindGroup,
    entity_atlas_sprite_bind_group: wgpu::BindGroup,
    // Hintergrundbild des Startbildschirms samt Pixelgroesse (s. wallpaper.rs), None = keins.
    // Eigener, LINEARER Sampler: ein Foto wird fast nie pixelgenau gezeichnet, Nearest waere
    // dort Treppchen.
    wallpaper: Option<(wgpu::BindGroup, (u32, u32))>,
    wallpaper_sampler: wgpu::Sampler,
    // Letzter Weltblick (s. last_view.rs): Hintergrund des HUD-Editors ohne Verbindung.
    last_view: Option<(wgpu::BindGroup, (u32, u32))>,
    // Letzter Blick des Servereintrags, mit dem gerade verbunden wird (s. App::connect_view_shown).
    connect_view: Option<(wgpu::BindGroup, (u32, u32))>,
    // Steht in offscreen_texture gerade ein Weltbild OHNE HUD (hinter einem Menue gezeichnet)?
    // Nur so eins taugt als letzter Weltblick -- wer mitten im Spiel getrennt wird, haette sonst
    // Hotbar und Herzen im Hintergrund des HUD-Editors.
    offscreen_world_only: bool,
    // Server-Icons der Server-Liste: ein Atlas mit SERVER_ICON_GRID^2 Plaetzen zu 64x64,
    // angelegt beim ersten Icon (s. upload_server_icon).
    server_icons: Option<(wgpu::Texture, wgpu::BindGroup)>,
    // Pack-Bilder des Skin-Tabs: skin_tab::ICON_GRID^2 Plaetze zu skin_tab::ICON_PX.
    pack_icons: Option<(wgpu::Texture, wgpu::BindGroup)>,
    // GitHub- und Discord-Logo der Kategorienleiste (s. upload_logos).
    logos: Option<(wgpu::Texture, wgpu::BindGroup)>,
    // Das zuletzt gezeichnete Weltbild (offscreen_view) als Sprite-Textur: Hintergrund der
    // Menues, solange man verbunden ist -- wie Vanillas Pausemenue ueber der Welt. None, bis
    // die Welt einmal gezeichnet wurde bzw. nach einem Resize (die Textur ist dann neu/leer).
    world_backdrop: Option<wgpu::BindGroup>,
    block_renderer: render::BlockRenderer,
    // Vom Treiber gelieferte Present-Modi, in der Reihenfolge der Auswahl.
    // Adapter-Info (Name, Hersteller) -- wgpu liefert das ohnehin mit dem Adapter, kein
    // separates Tool (lspci/glxinfo) noetig. Bestimmt, ob TearFree ueberhaupt Sinn ergibt:
    // die Eigenschaft existiert nur beim amdgpu-Treiber (PCI-Vendor-ID 0x1002).
    adapter_info: wgpu::AdapterInfo,
    // Fuer das echte Render-Ahead-Limit 0 (s. frame_latency-Kommentar bei Settings): der
    // Submission-Index des LETZTEN Frames. Bei aktivem Zero-Modus wartet der naechste Frame
    // per device.poll(WaitForSubmissionIndex) explizit darauf, BEVOR er anfaengt -- das ist
    // Sodiums Ansatz (Fence-Wait im Renderer selbst) statt sich auf den Swapchain-Parameter
    // zu verlassen, den wgpu bei 0 ohnehin auf einen hoeheren Wert clamped (s.
    // wgpu-types-Dokumentation zu desired_maximum_frame_latency).
    last_submission: Option<wgpu::SubmissionIndex>,
    // Debug-Flag CORAL_SCREENSHOT (s. screenshot.rs): ob die Swapchain lesbar ist, und ob der
    // naechste Frame kopiert werden soll (F2).
    screenshot_supported: bool,
    screenshot_requested: bool,
    // Ob der Zero-Modus gerade aktiv ist (settings.frame_latency == 0), s. set_frame_latency.
    fence_wait_zero: bool,
    // Fuer den Frame-Profiler: Zeit in render_world fuer Kamera, Zeichenreihenfolge,
    // Translucent-Sortierung und Spalten-Versaetze (vor dem Encoding), letzter Frame.
    last_sort_ms: f32,
    // Profiler: nach dem Present auf das GPU-Ende dieses Frames warten und den Zeitpunkt
    // festhalten. Erst dann schaltet bei Immediate das Bild um -- das ist der Moment, der
    // ueber die Risszeile entscheidet, nicht der Present-Aufruf. Aendert das Timing leicht
    // (die CPU wartet frueher), deshalb nur, solange der Profiler laeuft.
    measure_gpu_done: bool,
    // GPU-Zeit je Pass (s. gpu_timer), None ohne Timestamp-Unterstuetzung. Misst immer: die
    // Gesamtzeit geht in die Leistungsanzeige (s. FrameStats), die Passes in den Profiler.
    gpu_timer: Option<gpu_timer::GpuTimer>,
    // Renderpfad (Settings::render_path): false = PvP (Forward), true = Shader (s.
    // render::shader_path). Die App setzt das jeden Frame; die Ziele des Shader-Pfads
    // entstehen erst bei seinem ersten Frame. Der Shader-Pfad ist veraltet (s. dort): neue
    // Funktionen nur im PvP-Pfad.
    use_shader_path: bool,
    shader_path: Option<render::shader_path::ShaderPath>,
    // Fernsicht des Moduls Chunk-Saver (s. lod.rs); `lod_active`: in diesem Frame zeichnen.
    lod: Option<render::lod_renderer::LodRenderer>,
    lod_active: bool,
    // Sonnenstand dieses Frames (world::sky::sky_angle) fuer Sonne/Mond im Shader-Pfad.
    sky_angle: f32,
    // Himmel aus Resourcepacks (s. custom_sky) und seine Ebenen in diesem Frame.
    custom_sky: render::custom_sky::SkyRenderer,
    sky_layers: Vec<render::custom_sky::SkyLayerDraw>,
    // Leucht-Umriss leuchtender Entities (s. render::entity_outline).
    entity_outline: render::entity_outline::EntityOutline,
    // Modul Himmel, Art Verlauf: der Verlaufshimmel dieses Frames (None = Loeschfarbe).
    gradient_sky: render::gradient_sky::GradientSky,
    sky_gradient: Option<render::gradient_sky::GradientFrame>,
    // Oberwelt: der Shader-Pfad rechnet den Himmel als Atmosphaere.
    atmosphere: bool,
    // Lichtstreuung der Atmosphaere, 1.0 = Erde (s. Settings::shader_scattering_percent).
    scattering: f32,
    // Scheinbare Sonnengroesse in Grad (s. Settings::shader_sun_size_tenths).
    sun_size_deg: f32,
    // Blocklicht-Schatten (s. Settings::shader_block_shadows).
    block_shadows: bool,
    block_softness_deg: f32,
    // Lichtkarten-Ansicht (s. Settings::shader_lightmap_debug).
    lightmap_debug: u8,
    // Riss-Steuerung: genau zu diesem Zeitpunkt (MONOTONIC, ns) praesentieren, s.
    // submit_and_present. Gilt fuer einen Frame.
    present_at_ns: Option<i64>,
}

// Den UI-Atlas (GUI-Sheets + flache Item-Sprites) als GPU-Textur hochladen und daran eine
// Bind-Group fuer die Sprite-Pipeline haengen. Ohne Mipmaps: die Oberflaeche zeichnet nie
// verkleinert.
// Vanillas Glint-Texturen (ItemRenderer.ITEM_ENCHANTMENT_GLINT / ENTITY_ENCHANTMENT_GLINT).
// Fehlt eine (kaputte Installation), bleibt der Glint weiss statt den Start zu verhindern.
fn load_glint_textures(installation: &mut assets::MinecraftInstallation) -> [Option<assets::DecodedTexture>; 2] {
    ["enchanted_glint_item", "enchanted_glint_armor"]
        .map(|name| installation.load_texture(&format!("minecraft/textures/misc/{name}.png")).ok())
}

// Vanillas Niederschlags-Texturen (WeatherEffectRenderer: environment/rain.png, snow.png),
// je Art die des obersten Packs und die von Vanilla. Viele PvP-Packs schalten das Wetter ab,
// indem sie beide Bilder voll durchsichtig machen -- das respektiert der Client, solange das
// Modul "Wetter" aus ist. Ist es an, will man den Niederschlag sehen: dann ersetzt Vanillas
// Bild ein leeres aus dem Pack (s. WeatherTexture::chosen).
struct WeatherTexture {
    pack: Option<assets::DecodedTexture>,
    vanilla: Option<assets::DecodedTexture>,
}

impl WeatherTexture {
    fn pack_is_empty(&self) -> bool {
        self.pack.as_ref().is_some_and(|t| t.rgba.chunks_exact(4).all(|p| p[3] == 0))
    }

    fn chosen(&self, module: bool) -> Option<&assets::DecodedTexture> {
        if module && self.pack_is_empty() { self.vanilla.as_ref() } else { self.pack.as_ref() }
    }
}

fn load_weather_textures(installation: &mut assets::MinecraftInstallation) -> [WeatherTexture; 2] {
    let texturen = ["rain", "snow"].map(|name| {
        let pfad = format!("minecraft/textures/environment/{name}.png");
        let dekodiert = |bytes: &[u8]| {
            let img = image::load_from_memory(bytes).ok()?.to_rgba8();
            let (width, height) = img.dimensions();
            Some(assets::DecodedTexture { width, height, rgba: img.into_raw() })
        };
        // load_layers: Vanilla zuerst, das oberste Pack zuletzt.
        let vanilla = installation.load_layers(&pfad).first().and_then(|b| dekodiert(b));
        WeatherTexture { pack: installation.load_texture(&pfad).ok(), vanilla }
    });
    let zustand = |t: &WeatherTexture| match &t.pack {
        None => "fehlt".to_string(),
        Some(p) if t.pack_is_empty() => format!("{}x{}, im Pack leer", p.width, p.height),
        Some(p) => format!("{}x{}", p.width, p.height),
    };
    eprintln!("[wetter] Texturen: Regen {}, Schnee {}", zustand(&texturen[0]), zustand(&texturen[1]));
    texturen
}

fn weather_texture_part(t: Option<&assets::DecodedTexture>) -> (&[u8], u32, u32) {
    match t {
        Some(t) => (&t.rgba[..], t.width, t.height),
        None => (&[0, 0, 0, 0][..], 1, 1),
    }
}

fn set_glint_textures(
    renderer: &mut render::BlockRenderer,
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    texturen: &[Option<assets::DecodedTexture>; 2],
) {
    renderer.set_glint_textures(device, queue, glint_texture_part(&texturen[0]), glint_texture_part(&texturen[1]));
}

fn create_gui_glint_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    view: &wgpu::TextureView,
    sampler: &wgpu::Sampler,
    uniform: &wgpu::Buffer,
) -> wgpu::BindGroup {
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("gui glint bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
            wgpu::BindGroupEntry { binding: 2, resource: uniform.as_entire_binding() },
        ],
    })
}

fn glint_texture_part(t: &Option<assets::DecodedTexture>) -> (&[u8], u32, u32) {
    match t {
        Some(t) => (&t.rgba[..], t.width, t.height),
        None => (&[255, 255, 255, 255][..], 1, 1),
    }
}

fn create_ui_atlas_bind_group(
    device: &wgpu::Device,
    queue: &wgpu::Queue,
    layout: &wgpu::BindGroupLayout,
    sampler: &wgpu::Sampler,
    rgba: &[u8],
    size: u32,
) -> (wgpu::BindGroup, wgpu::Texture) {
    let extent = wgpu::Extent3d { width: size, height: size, depth_or_array_layers: 1 };
    let texture = device.create_texture(&wgpu::TextureDescriptor {
        label: Some("ui atlas"),
        size: extent,
        mip_level_count: 1,
        sample_count: 1,
        dimension: wgpu::TextureDimension::D2,
        format: wgpu::TextureFormat::Rgba8UnormSrgb,
        usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
        view_formats: &[],
    });
    queue.write_texture(
        wgpu::ImageCopyTexture { texture: &texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
        rgba,
        wgpu::ImageDataLayout { offset: 0, bytes_per_row: Some(size * 4), rows_per_image: Some(size) },
        extent,
    );
    let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
    let group = device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("ui atlas bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
        ],
    });
    (group, texture)
}

// Zweite Bind-Group auf DIESELBE Blockatlas-Textur, die auch die Welt benutzt -- nur mit
// dem Nearest-Sampler der Oberflaeche und ohne Mipmaps (s. sprite_sampler). Blockitems im
// Inventar brauchen keine eigene Textur.
fn create_entity_sprite_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    sampler: &wgpu::Sampler,
    block_renderer: &render::BlockRenderer,
) -> wgpu::BindGroup {
    let view = block_renderer.entity_atlas_texture().create_view(&wgpu::TextureViewDescriptor {
        label: Some("entity atlas sprite view"),
        mip_level_count: Some(1),
        ..Default::default()
    });
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("entity atlas sprite bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
        ],
    })
}

fn create_block_sprite_bind_group(
    device: &wgpu::Device,
    layout: &wgpu::BindGroupLayout,
    sampler: &wgpu::Sampler,
    block_renderer: &render::BlockRenderer,
) -> wgpu::BindGroup {
    let view = block_renderer.atlas_texture().create_view(&wgpu::TextureViewDescriptor {
        label: Some("block atlas sprite view"),
        mip_level_count: Some(1),
        ..Default::default()
    });
    device.create_bind_group(&wgpu::BindGroupDescriptor {
        label: Some("block atlas sprite bind group"),
        layout,
        entries: &[
            wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&view) },
            wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(sampler) },
        ],
    })
}

// PCI-Vendor-IDs der grossen GPU-Hersteller, wie sie wgpu/Vulkan meldet.
const PCI_VENDOR_AMD: u32 = 0x1002;
const PCI_VENDOR_NVIDIA: u32 = 0x10de;
const PCI_VENDOR_INTEL: u32 = 0x8086;

impl GpuState {
    fn new(
        window: Arc<Window>,
        installation: &mut assets::MinecraftInstallation,
        atlas_mips: &[Vec<u8>],
        atlas_size: u32,
        entity_atlas_rgba: &[u8],
        entity_atlas_size: u32,
        particle_atlas: &assets::ParticleAtlas,
        ui_atlas_rgba: &[u8],
        ui_atlas_size: u32,
        font: FontKind,
    ) -> Self {
        let size = window.inner_size();

        let backends = if cfg!(windows) { wgpu::Backends::DX12 } else { wgpu::Backends::VULKAN };
        let instance = wgpu::Instance::new(wgpu::InstanceDescriptor { backends, ..Default::default() });

        let surface = instance.create_surface(window.clone()).expect("Surface konnte nicht erstellt werden");

        let adapter = pollster::block_on(instance.request_adapter(&wgpu::RequestAdapterOptions {
            power_preference: wgpu::PowerPreference::HighPerformance,
            compatible_surface: Some(&surface),
            force_fallback_adapter: false,
        }))
        .expect("kein passender Vulkan-Adapter gefunden");
        let adapter_info = adapter.get_info();
        println!("[gpu] {} (Vendor 0x{:04x}, Treiber: {})", adapter_info.name, adapter_info.vendor, adapter_info.driver);

        let (device, queue) = pollster::block_on(adapter.request_device(
            &wgpu::DeviceDescriptor {
                label: Some("Coral Client device"),
                // Zeitstempel fuer die GPU-Zeit je Pass im Frame-Profiler (s. gpu_timer) -- nur,
                // wenn der Adapter sie kann; kostet nichts, solange niemand misst.
                // Dazu Mehrfach-Indirekt-Zeichnen fuers Gelaende (ein Aufruf statt ~1800, s.
                // render::BlockRenderer::prepare_terrain_draws); fehlt es, zeichnet der
                // Renderer je Spalte einzeln.
                required_features: adapter.features()
                    & (wgpu::Features::TIMESTAMP_QUERY
                        | wgpu::Features::TIMESTAMP_QUERY_INSIDE_PASSES
                        | wgpu::Features::MULTI_DRAW_INDIRECT
                        | wgpu::Features::INDIRECT_FIRST_INSTANCE),
                // Groessere Speicher-Puffer fuer die Lichtkarten des Shader-Pfads.
                required_limits: render::voxel_volume::VoxelVolume::required_limits(&adapter),
                memory_hints: wgpu::MemoryHints::Performance,
            },
            None,
        ))
        .expect("Device konnte nicht erstellt werden");

        let surface_caps = surface.get_capabilities(&adapter);
        let surface_format = surface_caps.formats.iter().copied().find(|f| f.is_srgb()).unwrap_or(surface_caps.formats[0]);

        // Immer Immediate: kein Warten auf den VBlank, minimale Latenz. Den Riss legt die
        // Riss-Steuerung in die Austastluecke. Eine Auswahl gibt es nicht mehr. Kann der Treiber
        // kein Immediate, Mailbox (reisst nicht, wartet aber auch nicht), sonst Fifo -- den
        // garantiert Vulkan.
        let present_modes = &surface_caps.present_modes;
        let present_mode = [wgpu::PresentMode::Immediate, wgpu::PresentMode::Mailbox]
            .into_iter()
            .find(|m| present_modes.contains(m))
            .unwrap_or(wgpu::PresentMode::Fifo);
        println!("[gpu] Present-Modi laut Treiber: {present_modes:?}, nehme {present_mode:?}");

        // CORAL_SCREENSHOT: die Swapchain zusaetzlich lesbar machen, sonst nicht (s. screenshot.rs).
        let screenshot_supported = screenshot::enabled() && surface_caps.usages.contains(wgpu::TextureUsages::COPY_SRC);
        if screenshot::enabled() {
            println!("[screenshot] F2 kopiert das Bild in die Zwischenablage: {}", if screenshot_supported { "bereit" } else { "Swapchain nicht lesbar, aus" });
        }

        let config = wgpu::SurfaceConfiguration {
            // COPY_DST zusaetzlich zu RENDER_ATTACHMENT: der letzte Schritt jedes Frames
            // kopiert das fertige Bild aus offscreen_texture in die Swapchain-Textur (s.
            // dortigen Kommentar), statt direkt hineinzuzeichnen -- braucht Schreibzugriff
            // per Kopie.
            usage: wgpu::TextureUsages::RENDER_ATTACHMENT
                | wgpu::TextureUsages::COPY_DST
                | if screenshot_supported { wgpu::TextureUsages::COPY_SRC } else { wgpu::TextureUsages::empty() },
            format: surface_format,
            width: size.width.max(1),
            height: size.height.max(1),
            present_mode,
            alpha_mode: surface_caps.alpha_modes[0],
            view_formats: vec![],
            desired_maximum_frame_latency: 1,
        };
        surface.configure(&device, &config);

        // Offscreen-Farbtextur, in die render_world tatsaechlich zeichnet (Welt, HUD-Text,
        // Crosshair) -- NICHT direkt in die Swapchain-Textur. Grund: das Crosshair-
        // Invertieren muss den bereits gezeichneten Bildinhalt zurücklesen (s.
        // crosshair_sample_texture), und ein Rueck-Kopieren direkt aus der praesentierbaren
        // Swapchain-Textur ist auf manchen Treibern (dieser RADV-Treiber meldet sich selbst
        // als "not a conformant Vulkan implementation") unzuverlaessig -- vermutlich
        // dieselbe Klasse Problem wie beim zuerst versuchten Blend-Trick. Eine selbst
        // verwaltete Textur mit klar definierter COPY_SRC-Nutzung umgeht das. Der letzte
        // Schritt jedes Frames kopiert das fertige Bild einmal komplett in die Swapchain-
        // Textur (s. render_world).
        let (offscreen_texture, offscreen_view) = create_offscreen_texture(&device, surface_format, config.width, config.height);

        // --- Quad-Pipeline (gefuellte, farbige Flaechen) ---
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("quad shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("quad.wgsl").into()),
        });
        let quad_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("quad pipeline layout"),
            bind_group_layouts: &[],
            push_constant_ranges: &[],
        });
        let quad_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("quad pipeline"),
            layout: Some(&quad_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<Vertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &wgpu::vertex_attr_array![0 => Float32x2, 1 => Float32x4, 2 => Float32x4, 3 => Float32x4, 4 => Float32x4],
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    // ALPHA_BLENDING, nicht REPLACE. ECHTER BUG gewesen (bei 50 % Deckkraft
                    // sah man die Kamera gar nicht): mit REPLACE wird der Alphawert jeder
                    // UI-Flaeche schlicht ignoriert, jedes Rechteck ueberschreibt das Bild
                    // deckend. Die halbdurchsichtige Abdunklung hinter dem Inventar wurde so
                    // zu deckendem Schwarz, egal welcher Prozentwert eingestellt war.
                    //
                    // Betraf ALLE bewusst durchscheinenden Flaechen dieser Pipeline (auch die
                    // Linien, die als duenne Quads durchlaufen): Slot-Hervorhebung (0.25),
                    // Scoreboard-Hintergrund (0.4), Sterbe-Ueberlagerung (0.55), Graph-
                    // Hintergrund (0.55), Raster und Griffe im HUD-Editor (0.08/0.35/0.6).
                    // Die sahen alle deckend aus. Text- und Sprite-Pipeline hatten die
                    // Blendung von Anfang an, nur diese hier nicht.
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });
        let quad_vertex_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("quad vertex buffer"),
            size: (std::mem::size_of::<Vertex>() * VERTS_PER_QUAD * MAX_UI_RECTS) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        // Eigener Puffer fuer Liniensegmente (F3-CPU-Graph, s. render_world) -- getrennt vom
        // quad_vertex_buffer, weil ein voller Graph (16+ Kerne * 89 Segmente) die dort fuer
        // normale UI-Rechtecke vorgesehene Kapazitaet (MAX_UI_RECTS) um ein Vielfaches
        // sprengen wuerde.
        let line_vertex_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("line vertex buffer"),
            size: (std::mem::size_of::<Vertex>() * VERTS_PER_QUAD * MAX_UI_LINE_SEGMENTS) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        // --- Zeiger-Pipeline: zeichnet EIN Quad, die Form entsteht im Fragment-Shader aus
        // dem Uniform (s. cursor.wgsl). Ein eigener Zeichendurchgang bleibt noetig, damit der
        // Zeiger NACH Flaechen, Sprites und Text ganz vorn liegt (s. render_menu).
        let cursor_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("cursor shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("cursor.wgsl").into()),
        });
        let cursor_uniform_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("cursor uniform buffer"),
            size: std::mem::size_of::<CursorUniform>() as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let cursor_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("cursor bind group layout"),
            entries: &[wgpu::BindGroupLayoutEntry {
                binding: 0,
                visibility: wgpu::ShaderStages::VERTEX_FRAGMENT,
                ty: wgpu::BindingType::Buffer { ty: wgpu::BufferBindingType::Uniform, has_dynamic_offset: false, min_binding_size: None },
                count: None,
            }],
        });
        let cursor_bind_group = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("cursor bind group"),
            layout: &cursor_bind_group_layout,
            entries: &[wgpu::BindGroupEntry { binding: 0, resource: cursor_uniform_buffer.as_entire_binding() }],
        });
        let cursor_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("cursor pipeline layout"),
            bind_group_layouts: &[&cursor_bind_group_layout],
            push_constant_ranges: &[],
        });
        let cursor_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("cursor pipeline"),
            layout: Some(&cursor_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &cursor_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[],
            },
            fragment: Some(wgpu::FragmentState {
                module: &cursor_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    // Die geglaetteten Randpixel sind halbdurchsichtig -- ohne Blendung
                    // waeren sie deckend und die Treppe waere nur bunt statt weg.
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // --- Crosshair-Pipeline: sampelt offscreen_view DIREKT (kein Kopierschritt mehr,
        // s. crosshair_vertices-Kommentar) und gibt im Fragment-Shader 1.0 - Farbe aus --
        // die Komplementaerfarbe des Untergrunds (Schwarz->Weiss, Rot->Gruen, ...).
        // Vor der Fadenkreuz-Pipeline: die zeichnet HUD-Zahlen mit den Glyphen dieses Atlas und
        // bindet dafuer sein Layout als Gruppe 1 (s. crosshair.wgsl).
        let mut font_atlas = FontAtlas::build(&device, &queue, installation, font).expect("Minecraft-Font konnte nicht geladen werden");
        let pack_fonts = installation.load_pack_fonts();
        let crosshair_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("crosshair shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("crosshair.wgsl").into()),
        });
        let crosshair_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("crosshair bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
            ],
        });
        let crosshair_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("crosshair sampler"),
            mag_filter: wgpu::FilterMode::Nearest,
            min_filter: wgpu::FilterMode::Nearest,
            ..Default::default()
        });
        // Farbmodus, Aufhellung und feste Farbe (s. crosshair.wgsl::CrosshairSettings/
        // CROSSHAIR_COLOR_MODES). 16 Byte, weil Uniform-Bloecke in WGSL ein Vielfaches von 16
        // gross sein muessen -- belegt sind davon zwoelf (u32 Modus, f32 Aufhellung, RGBA8
        // Farbe). Wird bei jedem
        // Frame mit den aktuellen Settings-Werten ueberschrieben (render_world), keine eigene
        // Bind-Group-Neuerzeugung noetig.
        let crosshair_mode_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("crosshair settings buffer"),
            size: 16,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let crosshair_bind_group =
            create_crosshair_bind_group(&device, &crosshair_bind_group_layout, &offscreen_view, &crosshair_sampler, &crosshair_mode_buffer);
        let crosshair_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("crosshair pipeline layout"),
            bind_group_layouts: &[&crosshair_bind_group_layout, &*font_atlas.bind_group_layout],
            push_constant_ranges: &[],
        });
        let crosshair_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("crosshair pipeline"),
            layout: Some(&crosshair_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &crosshair_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<CrosshairVertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &[
                        wgpu::VertexAttribute { offset: 0, shader_location: 0, format: wgpu::VertexFormat::Float32x2 },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 2]>() as wgpu::BufferAddress,
                            shader_location: 1,
                            format: wgpu::VertexFormat::Float32x2,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 4]>() as wgpu::BufferAddress,
                            shader_location: 2,
                            format: wgpu::VertexFormat::Float32x2,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 6]>() as wgpu::BufferAddress,
                            shader_location: 3,
                            format: wgpu::VertexFormat::Float32,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 7]>() as wgpu::BufferAddress,
                            shader_location: 4,
                            format: wgpu::VertexFormat::Float32,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 8]>() as wgpu::BufferAddress,
                            shader_location: 5,
                            format: wgpu::VertexFormat::Float32x2,
                        },
                    ],
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &crosshair_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                // Alpha-Blending wegen der Glyphen-Kanten (DM Sans ist kantengeglaettet) und der
                // Deckkraft der Pfeil-Zahl. Kreuz und Kontur geben Alpha 1 aus -- fuer sie aendert
                // sich nichts gegenueber dem frueheren REPLACE.
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // --- CMAA2 (s. cmaa2.wgsl-Kommentar) -- Compute-Infrastruktur + gather-basierte,
        // kontrastadaptive Kantenglaettung.
        let (cmaa2_output_texture, cmaa2_output_view) = create_cmaa2_output_texture(&device, config.width, config.height);
        let cmaa2_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("cmaa2 compute shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("cmaa2.wgsl").into()),
        });
        let cmaa2_compute_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("cmaa2 compute bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::COMPUTE,
                    ty: wgpu::BindingType::StorageTexture {
                        access: wgpu::StorageTextureAccess::WriteOnly,
                        format: wgpu::TextureFormat::Rgba8Unorm,
                        view_dimension: wgpu::TextureViewDimension::D2,
                    },
                    count: None,
                },
            ],
        });
        let cmaa2_compute_bind_group =
            create_cmaa2_compute_bind_group(&device, &cmaa2_compute_bind_group_layout, &offscreen_view, &cmaa2_output_view);
        let cmaa2_compute_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("cmaa2 compute pipeline layout"),
            bind_group_layouts: &[&cmaa2_compute_bind_group_layout],
            push_constant_ranges: &[],
        });
        let cmaa2_compute_pipeline = device.create_compute_pipeline(&wgpu::ComputePipelineDescriptor {
            label: Some("cmaa2 compute pipeline"),
            layout: Some(&cmaa2_compute_pipeline_layout),
            module: &cmaa2_shader,
            entry_point: "cmaa2_cs",
            compilation_options: wgpu::PipelineCompilationOptions::default(),
            cache: None,
        });
        let cmaa2_blit_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("cmaa2 blit shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("cmaa2_blit.wgsl").into()),
        });
        let cmaa2_blit_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("cmaa2 blit bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let cmaa2_blit_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("cmaa2 blit sampler"),
            mag_filter: wgpu::FilterMode::Nearest,
            min_filter: wgpu::FilterMode::Nearest,
            ..Default::default()
        });
        let cmaa2_blit_bind_group =
            create_cmaa2_blit_bind_group(&device, &cmaa2_blit_bind_group_layout, &cmaa2_output_view, &cmaa2_blit_sampler);
        let cmaa2_blit_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("cmaa2 blit pipeline layout"),
            bind_group_layouts: &[&cmaa2_blit_bind_group_layout],
            push_constant_ranges: &[],
        });
        let cmaa2_blit_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("cmaa2 blit pipeline"),
            layout: Some(&cmaa2_blit_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &cmaa2_blit_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[],
            },
            fragment: Some(wgpu::FragmentState {
                module: &cmaa2_blit_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState::REPLACE),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // --- Farb-Durchgang (Modul "Farbe", s. color.wgsl) ---
        let color_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("color shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("color.wgsl").into()),
        });
        let color_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("color bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: false },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Buffer { ty: wgpu::BufferBindingType::Uniform, has_dynamic_offset: false, min_binding_size: None },
                    count: None,
                },
            ],
        });
        let color_settings_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("color settings buffer"),
            size: 16,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let color_bind_group = create_color_bind_group(&device, &color_bind_group_layout, &offscreen_view, &color_settings_buffer);
        let color_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("color pipeline layout"),
            bind_group_layouts: &[&color_bind_group_layout],
            push_constant_ranges: &[],
        });
        let color_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("color pipeline"),
            layout: Some(&color_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &color_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[],
            },
            fragment: Some(wgpu::FragmentState {
                module: &color_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState { format: surface_format, blend: None, write_mask: wgpu::ColorWrites::ALL })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });

        // Zwei Balken (Rechtecke) als "+"-Form -- 12 Vertices (2 Quads * 6), plus noch einmal
        // so viele fuer die optionale Kontur (s. crosshair_vertices). Feste Groesse.
        let crosshair_vertex_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("crosshair vertex buffer"),
            size: (std::mem::size_of::<CrosshairVertex>() * CROSSHAIR_MAX_VERTICES) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        // --- Text-Pipeline (Font-Atlas, alpha-geblendet, per-Vertex-Farbe) ---
        let text_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("font shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("font.wgsl").into()),
        });
        let text_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("text pipeline layout"),
            bind_group_layouts: &[&*font_atlas.bind_group_layout],
            push_constant_ranges: &[],
        });
        let text_attributes = [
            wgpu::VertexAttribute { offset: 0, shader_location: 0, format: wgpu::VertexFormat::Float32x2 },
            wgpu::VertexAttribute {
                offset: std::mem::size_of::<[f32; 2]>() as wgpu::BufferAddress,
                shader_location: 1,
                format: wgpu::VertexFormat::Float32x2,
            },
            wgpu::VertexAttribute {
                offset: std::mem::size_of::<[f32; 4]>() as wgpu::BufferAddress,
                shader_location: 2,
                format: wgpu::VertexFormat::Float32x4,
            },
            wgpu::VertexAttribute {
                offset: std::mem::size_of::<[f32; 8]>() as wgpu::BufferAddress,
                shader_location: 3,
                format: wgpu::VertexFormat::Float32x4,
            },
            wgpu::VertexAttribute {
                offset: std::mem::size_of::<[f32; 12]>() as wgpu::BufferAddress,
                shader_location: 4,
                format: wgpu::VertexFormat::Float32x4,
            },
        ];
        let text_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("text pipeline"),
            layout: Some(&text_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &text_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<TextVertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &text_attributes,
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &text_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    // Alpha-Blending, damit Glyphen ueber farbigen Flaechen (Buttons) sitzen,
                    // statt deren Hintergrund mit Schwarz zu ueberschreiben.
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });
        // Dieselbe Schrift mit Tiefentest gegen die Welt (Schilder, s. font.wgsl::vs_world):
        // verdeckt von allem, was davor steht, auch von Entities. Tiefe des Welt-Durchgangs
        // (render::block_renderer::DEPTH_FORMAT), selbst ohne Tiefe zu schreiben.
        let world_text_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("world text pipeline"),
            layout: Some(&text_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &text_shader,
                entry_point: "vs_world",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<TextVertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &text_attributes,
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &text_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState { format: surface_format, blend: Some(wgpu::BlendState::ALPHA_BLENDING), write_mask: wgpu::ColorWrites::ALL })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: Some(wgpu::DepthStencilState {
                format: wgpu::TextureFormat::Depth32Float,
                depth_write_enabled: false,
                depth_compare: wgpu::CompareFunction::LessEqual,
                stencil: wgpu::StencilState::default(),
                bias: wgpu::DepthBiasState::default(),
            }),
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });
        let sign_text_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("sign text vertex buffer"),
            size: (std::mem::size_of::<TextVertex>() * MAX_SIGN_TEXT_VERTICES) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let text_vertex_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("text vertex buffer"),
            size: (std::mem::size_of::<TextVertex>() * VERTS_PER_QUAD * MAX_UI_GLYPHS) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });

        // --- Sprite-Pipeline (texturierte UI-Quads: GUI-Sheets, Item-Icons) ---
        let sprite_shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("sprite shader"),
            source: wgpu::ShaderSource::Wgsl(include_str!("sprite.wgsl").into()),
        });
        let sprite_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("sprite bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
            ],
        });
        let sprite_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("sprite sampler"),
            // Nearest in beide Richtungen: Item-Icons werden fast immer VERGROESSERT
            // gezeichnet (16px-Sprite auf 32-64px Slot) -- linear waere ein Weichzeichner.
            mag_filter: wgpu::FilterMode::Nearest,
            min_filter: wgpu::FilterMode::Nearest,
            mipmap_filter: wgpu::FilterMode::Nearest,
            ..Default::default()
        });
        let wallpaper_sampler = device.create_sampler(&wgpu::SamplerDescriptor {
            label: Some("wallpaper sampler"),
            mag_filter: wgpu::FilterMode::Linear,
            min_filter: wgpu::FilterMode::Linear,
            ..Default::default()
        });
        let sprite_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("sprite pipeline layout"),
            bind_group_layouts: &[&sprite_bind_group_layout],
            push_constant_ranges: &[],
        });
        let sprite_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("sprite pipeline"),
            layout: Some(&sprite_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &sprite_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                // Gleiches Vertex-Layout wie der Text (Position, UV, Farbe) -- s. TextVertex.
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<TextVertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &[
                        wgpu::VertexAttribute { offset: 0, shader_location: 0, format: wgpu::VertexFormat::Float32x2 },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 2]>() as wgpu::BufferAddress,
                            shader_location: 1,
                            format: wgpu::VertexFormat::Float32x2,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 4]>() as wgpu::BufferAddress,
                            shader_location: 2,
                            format: wgpu::VertexFormat::Float32x4,
                        },
                    ],
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &sprite_shader,
                entry_point: "fs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState::ALPHA_BLENDING),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });
        // GUI-Glint: Gruppe 0 wie beim Sprite (der Icon-Atlas als Maske), Gruppe 1 Glint-
        // Textur + Sampler + Matrix. Gemischt wie in der Welt: additiv, das Ziel-Alpha bleibt.
        let glint_gui_bind_group_layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("gui glint bind group layout"),
            entries: &[
                wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Texture {
                        sample_type: wgpu::TextureSampleType::Float { filterable: true },
                        view_dimension: wgpu::TextureViewDimension::D2,
                        multisampled: false,
                    },
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 1,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Sampler(wgpu::SamplerBindingType::Filtering),
                    count: None,
                },
                wgpu::BindGroupLayoutEntry {
                    binding: 2,
                    visibility: wgpu::ShaderStages::FRAGMENT,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: None,
                    },
                    count: None,
                },
            ],
        });
        let glint_sprite_pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("gui glint pipeline layout"),
            bind_group_layouts: &[&sprite_bind_group_layout, &glint_gui_bind_group_layout],
            push_constant_ranges: &[],
        });
        let glint_sprite_pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("gui glint pipeline"),
            layout: Some(&glint_sprite_pipeline_layout),
            vertex: wgpu::VertexState {
                module: &sprite_shader,
                entry_point: "vs_main",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                buffers: &[wgpu::VertexBufferLayout {
                    array_stride: std::mem::size_of::<TextVertex>() as wgpu::BufferAddress,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: &[
                        wgpu::VertexAttribute { offset: 0, shader_location: 0, format: wgpu::VertexFormat::Float32x2 },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 2]>() as wgpu::BufferAddress,
                            shader_location: 1,
                            format: wgpu::VertexFormat::Float32x2,
                        },
                        wgpu::VertexAttribute {
                            offset: std::mem::size_of::<[f32; 4]>() as wgpu::BufferAddress,
                            shader_location: 2,
                            format: wgpu::VertexFormat::Float32x4,
                        },
                    ],
                }],
            },
            fragment: Some(wgpu::FragmentState {
                module: &sprite_shader,
                entry_point: "fs_glint",
                compilation_options: wgpu::PipelineCompilationOptions::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: surface_format,
                    blend: Some(wgpu::BlendState {
                        color: wgpu::BlendComponent {
                            src_factor: wgpu::BlendFactor::One,
                            dst_factor: wgpu::BlendFactor::One,
                            operation: wgpu::BlendOperation::Add,
                        },
                        alpha: wgpu::BlendComponent {
                            src_factor: wgpu::BlendFactor::Zero,
                            dst_factor: wgpu::BlendFactor::One,
                            operation: wgpu::BlendOperation::Add,
                        },
                    }),
                    write_mask: wgpu::ColorWrites::ALL,
                })],
            }),
            primitive: wgpu::PrimitiveState::default(),
            depth_stencil: None,
            multisample: wgpu::MultisampleState::default(),
            multiview: None,
            cache: None,
        });
        let glint_gui_uniform = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("gui glint uniform"),
            size: std::mem::size_of::<render::glint::GlintUniform>() as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let glint_gui_sampler = render::glint::create_sampler(&device);
        let sprite_vertex_buffer = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("sprite vertex buffer"),
            // +1: das Hintergrundbild des Startbildschirms vorneweg (s. render_menu).
            size: (std::mem::size_of::<TextVertex>() * VERTS_PER_QUAD * (MAX_UI_SPRITES + 1)) as wgpu::BufferAddress,
            usage: wgpu::BufferUsages::VERTEX | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        let (ui_atlas_bind_group, ui_atlas_texture) =
            create_ui_atlas_bind_group(&device, &queue, &sprite_bind_group_layout, &sprite_sampler, ui_atlas_rgba, ui_atlas_size);

        // Startet leer -- gefuellt wird ausschliesslich aus echten Server-Chunks,
        // sobald die Verbindung steht (s. App::mesh_pending_columns).
        let block_renderer = render::BlockRenderer::new(
            &device,
            &queue,
            surface_format,
            config.width,
            config.height,
            atlas_mips,
            atlas_size,
            entity_atlas_rgba,
            entity_atlas_size,
            &particle_atlas.rgba,
            particle_atlas.size,
        );
        let mut block_renderer = block_renderer;
        let glint_texturen = load_glint_textures(installation);
        set_glint_textures(&mut block_renderer, &device, &queue, &glint_texturen);
        let (glint_rgba, glint_w, glint_h) = glint_texture_part(&glint_texturen[0]);
        let glint_gui_view = render::glint::upload_texture(&device, &queue, glint_rgba, glint_w, glint_h);
        let glint_gui_bind_group =
            create_gui_glint_bind_group(&device, &glint_gui_bind_group_layout, &glint_gui_view, &glint_gui_sampler, &glint_gui_uniform);
        let block_atlas_sprite_bind_group =
            create_block_sprite_bind_group(&device, &sprite_bind_group_layout, &sprite_sampler, &block_renderer);
        let entity_atlas_sprite_bind_group =
            create_entity_sprite_bind_group(&device, &sprite_bind_group_layout, &sprite_sampler, &block_renderer);
        let gpu_timer = gpu_timer::GpuTimer::new(&device, &queue);
        println!("[gpu] Zeitstempel je Pass: {}", if gpu_timer.is_some() { "verfuegbar" } else { "nicht unterstuetzt" });

        let custom_sky = render::custom_sky::SkyRenderer::new(&device, surface_format.remove_srgb_suffix());
        let entity_outline = render::entity_outline::EntityOutline::new(&device, surface_format.remove_srgb_suffix());
        let gradient_sky = render::gradient_sky::GradientSky::new(&device, surface_format);
        let device = std::sync::Arc::new(device);
        let queue = std::sync::Arc::new(queue);
        let pack_glyphs = Some(Arc::new(font_atlas::PackGlyphCache::new(&device, queue.clone(), pack_fonts)));
        font_atlas.set_pack(&device, pack_glyphs.clone());
        Self {
            surface,
            device,
            queue,
            config,
            window,
            offscreen_texture,
            offscreen_view,
            quad_pipeline,
            quad_vertex_buffer,
            line_vertex_buffer,
            cursor_pipeline,
            cursor_uniform_buffer,
            cursor_bind_group,
            crosshair_pipeline,
            crosshair_vertex_buffer,
            crosshair_bind_group_layout,
            crosshair_sampler,
            crosshair_mode_buffer,
            crosshair_bind_group,
            cmaa2_output_texture,
            cmaa2_output_view,
            cmaa2_compute_pipeline,
            cmaa2_compute_bind_group_layout,
            cmaa2_compute_bind_group,
            cmaa2_blit_pipeline,
            cmaa2_blit_bind_group_layout,
            cmaa2_blit_sampler,
            cmaa2_blit_bind_group,
            color_pipeline,
            color_bind_group_layout,
            color_settings_buffer,
            color_bind_group,
            text_pipeline,
            text_vertex_buffer,
            world_text_pipeline,
            sign_text_buffer,
            sign_glyphs: Default::default(),
            sign_font: Default::default(),
            label_font: Default::default(),
            font_atlas,
            extra_fonts: Vec::new(),
            pack_glyphs,
            layout_font: Default::default(),
            plain_numbers: Default::default(),
            under_sprites: Default::default(),
            text_shadow_style: TextShadow::Outline,
            text_shadow_strength: 1.0,
            text_runs: Default::default(),
            stable_numbers: Default::default(),
            world_label_glyphs: Default::default(),
            world_label_quads: Default::default(),
            sprite_pipeline,
            glint_sprite_pipeline,
            glint_gui_bind_group_layout,
            glint_gui_bind_group,
            glint_gui_uniform,
            glint_gui_sampler,
            sprite_vertex_buffer,
            sprite_bind_group_layout,
            sprite_sampler,
            ui_atlas_bind_group,
            ui_atlas_texture,
            block_atlas_sprite_bind_group,
            entity_atlas_sprite_bind_group,
            wallpaper: None,
            last_view: None,
            connect_view: None,
            offscreen_world_only: false,
            server_icons: None,
            pack_icons: None,
            logos: None,
            world_backdrop: None,
            wallpaper_sampler,
            block_renderer,
            adapter_info,
            last_submission: None,
            screenshot_supported,
            screenshot_requested: false,
            fence_wait_zero: false,
            last_sort_ms: 0.0,
            measure_gpu_done: false,
            gpu_timer,
            use_shader_path: false,
            shader_path: None,
            lod: None,
            lod_active: false,
            sky_angle: 0.0,
            custom_sky,
            entity_outline,
            sky_layers: Vec::new(),
            gradient_sky,
            sky_gradient: None,
            atmosphere: true,
            scattering: 1.0,
            sun_size_deg: 2.0,
            block_shadows: true,
            block_softness_deg: 6.0,
            lightmap_debug: 0,
            present_at_ns: None,
        }
    }

    fn gpu_label(&self) -> String {
        let vendor = match self.adapter_info.vendor {
            PCI_VENDOR_AMD => "AMD",
            PCI_VENDOR_NVIDIA => "Nvidia",
            PCI_VENDOR_INTEL => "Intel",
            _ => "?",
        };
        format!("{vendor}: {}", self.adapter_info.name)
    }

    // Taktet der Present-Modus schon selbst? Bei Fifo (und FifoRelaxed) blockiert
    // get_current_texture(), bis ein Swapchain-Bild frei wird -- der VBlank gibt den Takt
    // vor. Ein eigener Timer daneben ist dann nicht nur ueberfluessig, sondern schaedlich:
    // zwei unabhaengige Uhren schweben gegeneinander, wir verpassen mal einen VBlank und
    // draengeln mal zwei Frames. Immediate und Mailbox blockieren dagegen nicht und
    // brauchen unseren Deckel, sonst rendern sie ungebremst.
    fn present_mode_self_paces(&self) -> bool {
        matches!(self.config.present_mode, wgpu::PresentMode::Fifo | wgpu::PresentMode::FifoRelaxed | wgpu::PresentMode::AutoVsync)
    }

    // CPU-Render-Ahead-Limit umschalten -- ein sofortiges configure(),
    // aber OHNE Treiber-Rueckfrage: wgpu akzeptiert jeden Wert >=1 auf jedem Backend, es gibt
    // also keine Liste "unterstuetzter" Werte wie bei present_modes.
    // value=0 ist der Sodium-Style-Zero-Modus (echte Fence-Wait vor jedem Frame statt eines
    // Swapchain-Parameters, s. fence_wait_zero-Feldkommentar) -- die Swapchain selbst bekommt
    // dabei trotzdem einen gueltigen Wert (1), wgpu wuerde eine 0 ohnehin nur darauf clampen.
    fn set_frame_latency(&mut self, value: u32) {
        let wants_zero_mode = value == 0;
        let swapchain_value = value.max(1);
        if self.config.desired_maximum_frame_latency != swapchain_value {
            self.config.desired_maximum_frame_latency = swapchain_value;
            self.surface.configure(&self.device, &self.config);
        }
        self.fence_wait_zero = wants_zero_mode;
        println!("[gpu] Render-Ahead-Limit -> {value} (Swapchain-Wert {swapchain_value}, Zero-Modus {})", self.fence_wait_zero);
    }

    // Am Anfang jedes Frames aufgerufen (vor get_current_texture()): im Zero-Modus wird hart
    // auf das GPU-Ende des VORHERIGEN Frames gewartet, bevor dieser Frame ueberhaupt anfaengt
    // -- damit steht nie mehr als das gerade angezeigte Frame in der Pipeline (Sodiums "CPU
    // Render-Ahead Limit: 0"). Ausserhalb des Zero-Modus ein No-Op (die Swapchain uebernimmt
    // die Drosselung selbst, s. desired_maximum_frame_latency).
    fn wait_for_previous_frame_if_zero_mode(&self) {
        if self.fence_wait_zero {
            if let Some(index) = &self.last_submission {
                self.device.poll(wgpu::Maintain::WaitForSubmissionIndex(index.clone()));
            }
        }
    }

    fn resize(&mut self, width: u32, height: u32) {
        if width == 0 || height == 0 {
            return;
        }
        self.config.width = width;
        self.config.height = height;
        self.surface.configure(&self.device, &self.config);
        self.block_renderer.resize(&self.device, width, height);
        if let Some(lod) = self.lod.as_mut() {
            lod.resize(&self.device, width, height);
        }
        let (offscreen_texture, offscreen_view) = create_offscreen_texture(&self.device, self.config.format, width, height);
        self.offscreen_texture = offscreen_texture;
        self.offscreen_view = offscreen_view;
        self.world_backdrop = None;
        self.offscreen_world_only = false;
        // Der Crosshair-Bind-Group haengt an der alten offscreen_view-Identitaet -- neu
        // erzeugen, sonst zeigt er nach einem Resize auf eine bereits zerstoerte Textur.
        self.crosshair_bind_group = create_crosshair_bind_group(
            &self.device,
            &self.crosshair_bind_group_layout,
            &self.offscreen_view,
            &self.crosshair_sampler,
            &self.crosshair_mode_buffer,
        );
        self.color_bind_group =
            create_color_bind_group(&self.device, &self.color_bind_group_layout, &self.offscreen_view, &self.color_settings_buffer);
        // CMAA2-Ausgabetextur haengt an der Bildschirmgroesse (s. create_cmaa2_output_texture)
        // und beide Bind-Groups an den konkreten View-Identitaeten -- alle drei bei jedem
        // resize() neu erzeugen, aus demselben Grund wie beim Crosshair oben.
        let (cmaa2_output_texture, cmaa2_output_view) = create_cmaa2_output_texture(&self.device, width, height);
        self.cmaa2_output_texture = cmaa2_output_texture;
        self.cmaa2_output_view = cmaa2_output_view;
        self.cmaa2_compute_bind_group = create_cmaa2_compute_bind_group(
            &self.device,
            &self.cmaa2_compute_bind_group_layout,
            &self.offscreen_view,
            &self.cmaa2_output_view,
        );
        self.cmaa2_blit_bind_group = create_cmaa2_blit_bind_group(
            &self.device,
            &self.cmaa2_blit_bind_group_layout,
            &self.cmaa2_output_view,
            &self.cmaa2_blit_sampler,
        );
    }

    fn size(&self) -> (f32, f32) {
        (self.config.width as f32, self.config.height as f32)
    }

    // Pixelbreite eines Textes bei gegebener Skalierung -- fuer Caret-/Layout-Berechnung.
    // Mit dem Platz, den eine wechselnde Zahl darin reserviert hat (s. stable_numbers) --
    // sonst lagen Ausrichtung (mittig, rechtsbuendig) und Zeichnen auseinander.
    //
    // Gemessen wird der Text in der Sprache der Oberflaeche (s. i18n) -- dieselbe, in der
    // shape_text ihn zeichnet.
    fn measure_text(&self, text: &str, scale: f32) -> f32 {
        self.measure_raw(&i18n::tr(text), scale)
    }

    // Ohne Uebersetzung: fuer Text, der schon uebersetzt ist (Umbruch, Kuerzen).
    fn measure_raw(&self, text: &str, scale: f32) -> f32 {
        let text = &*self.layout_atlas().display_text(text);
        if self.plain_numbers.get() {
            return text.chars().map(|c| self.advance(c)).sum::<f32>() * scale;
        }
        self.stable_numbers.borrow().width(text, |c| self.advance(c)) * scale
    }

    // Vorschub eines Zeichens in Schriftpixeln; 0 fuer Zeichen, die die Schrift nicht hat
    // (die werden beim Zeichnen uebersprungen).
    fn advance(&self, ch: char) -> f32 {
        self.layout_atlas().glyph(ch).map(|g| g.advance_px).unwrap_or(0.0)
    }

    // Startposition jedes Zeichens in Bildschirmpixeln relativ zum Zeilenanfang, mit
    // reserviertem Platz fuer wechselnde Zahlen. Fuer Zeilen, die aus mehreren UiTexts
    // bestehen (Farbabschnitte, s. App::build_server_hud) und trotzdem als EINE Zeile
    // ausgerichtet werden muessen.
    fn char_positions(&self, text: &str, scale: f32) -> (Vec<f32>, f32) {
        let text = &*self.layout_atlas().display_text(text);
        if self.plain_numbers.get() {
            let mut x = 0.0;
            let pos = text
                .chars()
                .map(|c| {
                    let hier = x;
                    x += self.advance(c) * scale;
                    hier
                })
                .collect();
            return (pos, x);
        }
        let (pos, w) = self.stable_numbers.borrow().layout(text, |c| self.advance(c));
        (pos.into_iter().map(|p| p * scale).collect(), w * scale)
    }

    // Zeilen, die nicht als EIN UiText gezeichnet werden (s. char_positions), selbst
    // anmelden -- shape_text sieht von ihnen nur die Stuecke.
    fn observe_numbers<'a>(&self, texts: impl IntoIterator<Item = &'a str>) {
        self.stable_numbers.borrow_mut().observe(texts, Instant::now(), |c| self.advance(c));
    }

    // Zeilenhoehe bei gegebenem Faktor -- damit sich Layout-Werte aus dem Font ergeben,
    // statt irgendwo als Zahl zu stehen, die zur Font passen muss.
    // Breite in Vanilla-Einheiten (Minecraft-Schrift, Fett ein Pixel mehr je Zeichen), egal in
    // welcher Schrift gezeichnet wird.
    fn vanilla_width(&self, text: &str, style: u8) -> f32 {
        let atlas = self.layout_atlas();
        let fett = if style & protocol::nbt::STYLE_BOLD != 0 { 1.0 } else { 0.0 };
        text.chars().map(|c| atlas.vanilla_advance(c) + fett).sum()
    }

    fn text_height(&self, scale: f32) -> f32 {
        self.layout_atlas().cell_height_px() * scale
    }

    // Text mittig in ein Rechteck. Die Position wird auf ganze Pixel gerundet: ein
    // halber Pixel Versatz zerlegt den Bitmap-Font genauso wie eine Bruchskalierung,
    // nur subtiler -- die Glyphen wirken dann unruhig statt scharf.
    fn centered_text(&self, rect: Rect, text: String, color: [f32; 4], scale: f32) -> UiText {
        let width = self.measure_text(&text, scale);
        let height = self.text_height(scale);
        UiText { text, x: (rect.x + (rect.w - width) / 2.0).round(), y: (rect.y + (rect.h - height) / 2.0).round(), color, scale }
    }

    // Text zu Vertices. Nebenbei merkt sich jede Zeile, wo ihre Zeichen stehen (text_runs) --
    // daraus waehlt die Textauswahl aus (s. App::text_selection).
    //
    // Rand um den Text je nach TextShadow: Kontur (duenne schwarze Linie, genau EIN
    // Bildschirmpixel in alle Richtungen -- ein Schriftpixel liess bei Skala >= 2 Luecken an den
    // Diagonalen) oder Vanillas Schatten (ein Schriftpixel nach rechts unten, ein Viertel der
    // Farbe). Beides ist je Glyph EIN zusaetzliches Viereck, dessen Deckung der Shader rechnet
    // (s. font.wgsl) -- so blendet Text mit Rand sauber aus, statt grau zu werden.
    //
    // Welcher Rand gilt, stellt text_shadow_style ein; Marker in der Textliste (s.
    // push_shadow_marker) aendern ihn fuer die folgenden Texte (Chat, Hotbar, ...). Ebenso
    // die Schrift (push_font_marker).
    //
    // Rueckgabe: ab welchem Vertex (Index in `out`) welche Schrift gilt -- je Schrift ein
    // eigener Zeichenaufruf mit ihrem Atlas (s. draw_ui_top). Davor gilt die allgemeine.
    fn shape_text(&self, texts: &[UiText], screen_px: (f32, f32), out: &mut Vec<TextVertex>) -> Vec<(u32, FontKind)> {
        // Oberflaeche in der eingestellten Sprache (s. i18n): erst hier, nicht an den vielen
        // Stellen, die Beschriftungen bauen. measure_text uebersetzt genauso, Ausrichtung und
        // Zeichnen sehen also denselben Text.
        // Getippter Text (s. push_typed_marker) bleibt, wie er ist: wer "An" tippt, meint
        // nicht den Schalter "On".
        let uebersetzt: Vec<UiText>;
        let texts = if i18n::ui_language() == i18n::Language::German {
            texts
        } else {
            let mut getippt = false;
            uebersetzt = texts
                .iter()
                .map(|t| {
                    let text = if getippt { t.text.clone() } else { i18n::tr(&t.text).into_owned() };
                    getippt = is_typed_marker(t);
                    UiText { text, x: t.x, y: t.y, color: t.color, scale: t.scale }
                })
                .collect();
            &uebersetzt
        };
        let mut wechsel = Vec::new();
        self.set_layout_font(None);
        self.shape_text_in(texts, screen_px, out, &mut wechsel);
        self.set_layout_font(None);
        wechsel
    }

    fn shape_text_in(&self, texts: &[UiText], screen_px: (f32, f32), out: &mut Vec<TextVertex>, wechsel: &mut Vec<(u32, FontKind)>) {
        let mut runs = self.text_runs.borrow_mut();
        runs.clear();
        let mut group = 0u32;
        let allgemein = (self.text_shadow_style, self.text_shadow_strength);
        let mut stil = allgemein;
        let mut aktuell = self.font_atlas.kind();
        // Schattenfarbe des Servers und Fettdruck fuer den naechsten Text (s. push_span_shadow,
        // push_bold_marker).
        let mut vom_server: Option<[f32; 4]> = None;
        let mut fett_naechster = false;
        for t in texts {
            if let Some(neu) = shadow_marker(t) {
                stil = neu.unwrap_or(allgemein);
                continue;
            }
            if let Some(farbe) = span_shadow_marker(t) {
                vom_server = Some(farbe);
                continue;
            }
            if is_bold_marker(t) {
                fett_naechster = true;
                continue;
            }
            if is_typed_marker(t) {
                continue;
            }
            if let Some(an) = plain_numbers_marker(t) {
                self.plain_numbers.set(an);
                continue;
            }
            if let Some(neu) = font_marker(t) {
                self.set_layout_font(neu);
                continue;
            }
            let atlas = self.layout_atlas();
            if atlas.kind() != aktuell {
                aktuell = atlas.kind();
                wechsel.push((out.len() as u32, aktuell));
            }
            if is_selection_boundary(t) {
                group += 1;
                continue;
            }
            // t.y ist die Oberkante der Zeile; ueber den ascent zur Grundlinie.
            let scale = t.scale;
            let baseline_y = t.y + atlas.ascent_px() * scale;
            let mut glyphs = Vec::with_capacity(t.text.len());
            let (stil_hier, staerke) = stil;
            let mut rand = if t.color[3] > 0.0 && staerke > 0.0 { stil_hier } else { TextShadow::Off };
            let mut randfarbe = match rand {
                TextShadow::Vanilla => vanilla_shadow_color(t.color),
                _ => [0.0, 0.0, 0.0, t.color[3]],
            };
            // Hat der Server die Schattenfarbe gesetzt, gilt sie wie in Vanilla (Alpha mal
            // Textdeckkraft, Alpha 0 = kein Schatten). Der Server waehlt nur die FARBE: die Art
            // (Kontur, Vanilla, Unten, Aussen) bleibt die eingestellte, und ist der Rand hier aus,
            // bleibt er aus.
            if let Some([r, g, b, a]) = vom_server.take().filter(|_| rand != TextShadow::Off) {
                if a > 0.0 {
                    randfarbe = [r, g, b, a * t.color[3]];
                } else {
                    rand = TextShadow::Off;
                }
            }
            if is_black(t.color) && is_black(randfarbe) {
                rand = TextShadow::Off;
            }
            // Erst alle Raender, dann alle Glyphen: sonst laege der Rand des naechsten Zeichens
            // ueber dem vorigen.
            let durchgaenge: &[bool] = if rand == TextShadow::Off { &[false] } else { &[true, false] };
            // Zeichenpositionen mit reserviertem Platz fuer wechselnde Zahlen (s.
            // stable_numbers) -- dieselben, mit denen measure_text ausgerichtet hat. Einmal je
            // Text, nicht je Durchgang.
            let (positionen, _) = self.char_positions(&t.text, scale);
            // Fett: je Zeichen ein Font-Pixel mehr Vorschub. Gezeichnet in echtem Fettdruck
            // (s. FontAtlas::place_bold), mittig in diesem Vorschub; wo es den nicht gibt
            // (Minecraft-Schrift, Symbole) wie Vanilla zweimal, bei 0 und +1 Pixel.
            let fett = std::mem::take(&mut fett_naechster);
            let mehr = if fett { scale } else { 0.0 };
            for &ist_rand in durchgaenge {
                for (k, (ch, &rel)) in atlas.display_text(&t.text).chars().zip(&positionen).enumerate() {
                    let pen_x = t.x + rel + k as f32 * mehr;
                    if out.len() + VERTS_PER_QUAD * 2 > MAX_UI_GLYPHS * VERTS_PER_QUAD {
                        runs.push(TextRun { top: t.y, bottom: t.y + self.text_height(scale), glyphs, group });
                        return; // Buffer-Limit erreicht -- Rest weglassen statt ueberlaufen
                    }
                    let Some(g) = atlas.glyph(ch) else { continue };
                    let advance = g.advance_px * scale;
                    let echt_fett = if fett { atlas.place_bold(ch, scale) } else { None };
                    let (gesetzt, versaetze): (_, &[f32]) = match echt_fett {
                        Some((p, fett_vorschub)) => (Some((p, pen_x + (advance + mehr - fett_vorschub * scale) / 2.0)), &[0.0]),
                        None => (atlas.place(ch, scale).map(|p| (p, pen_x)), if fett { &[0.0, scale] } else { &[0.0] }),
                    };
                    if let Some((p, pen_x)) = gesetzt.filter(|(p, _)| p.size[0] > 0.0 && p.size[1] > 0.0) {
                        // Genau fuer diese Groesse gerasterte Glyphen (DM Sans) auf ganze
                        // Pixel setzen -- der Vorschub bleibt dabei unrund, der Startpunkt
                        // rastet ein, mit der Subpixel-Fassung fuer den Rest (s. snap_x). So
                        // trifft jedes Texel genau einen Bildschirmpixel, ohne dass sich
                        // Fehler aufsummieren.
                        let (p, pen_x) = atlas.snap_x(ch, scale, echt_fett.is_some(), p, pen_x);
                        let (ox, oy) = if p.snap { (pen_x, baseline_y.round()) } else { (pen_x, baseline_y) };
                        for &dx in versaetze {
                            let x0 = ox + dx + p.offset[0];
                            let y0 = oy + p.offset[1];
                            let (x1, y1) = (x0 + p.size[0], y0 + p.size[1]);
                            let erstes = out.len();
                            if ist_rand {
                                out.extend_from_slice(&text_border_quad(rand, staerke, [x0, y0, x1, y1], p.uv_min, p.uv_max, scale, p.snap, randfarbe, screen_px));
                            } else {
                                out.extend_from_slice(&text_quad(x0, y0, x1, y1, p.uv_min, p.uv_max, t.color, screen_px));
                            }
                            if p.pack {
                                mark_pack_glyph(&mut out[erstes..]);
                            }
                        }
                    }
                    if !ist_rand {
                        glyphs.push((ch, pen_x, pen_x + advance + mehr));
                    }
                }
            }
            runs.push(TextRun { top: t.y, bottom: t.y + self.text_height(scale), glyphs, group });
        }
        // ERST NACH dem Zeichnen lernen: so gilt fuer dieses Bild noch derselbe Stand, mit
        // dem measure_text vorhin ausgerichtet hat.
        drop(runs);
        self.set_layout_font(None);
        self.plain_numbers.set(false);
        let getippt = |i: usize| i > 0 && is_typed_marker(&texts[i - 1]);
        let mut ruhig = false;
        let ruhig_je_text: Vec<bool> = texts
            .iter()
            .map(|t| {
                if let Some(an) = plain_numbers_marker(t) {
                    ruhig = an;
                }
                ruhig
            })
            .collect();
        self.observe_numbers(
            texts.iter().enumerate().filter(|&(i, t)| !is_selection_boundary(t) && !getippt(i) && !ruhig_je_text[i]).map(|(_, t)| t.text.as_str()),
        );
    }

    // Eine Textzeile auf einer beliebig im Raum liegenden Flaeche (Text-Display). `project`
    // bildet einen Punkt der Textebene (Schriftpixel, x nach rechts, y nach unten) auf
    // Bildschirmpixel ab, oder None hinter der Kamera. `raster` = Bildschirmpixel je
    // Schriftpixel, waehlt nur die Rasterstufe der Glyphen (DM Sans). `rand`: Farbe der
    // Kontur, None = keine (s. world_text_border). `depth`: NDC-Tiefe je Punkt der Textebene
    // fuer den Welt-Durchgang (Schilder, s. font.wgsl::vs_world), steht in mode.w. Gesetzt
    // wird in der Schrift, mit der gerade gemessen wird (layout_atlas). Rueckgabe: Vorschub.
    //
    // Die Glyphen-Vierecke werden erst hier projiziert und dann ganz normal als Dreiecke
    // gezeichnet -- ohne perspektivisch korrekte Texturierung. Bei Glyphengroesse ist der
    // Unterschied unsichtbar.
    #[allow(clippy::too_many_arguments)]
    fn shape_projected_text(
        &self,
        text: &str,
        x: f32,
        top: f32,
        color: [f32; 4],
        rand: Option<[f32; 4]>,
        raster: f32,
        project: &dyn Fn(f32, f32) -> Option<(f32, f32)>,
        depth: Option<&dyn Fn(f32, f32) -> f32>,
        screen_px: (f32, f32),
        out: &mut Vec<TextVertex>,
    ) -> f32 {
        const RICHTUNGEN: [(f32, f32); 8] = [(-1.0, -1.0), (0.0, -1.0), (1.0, -1.0), (-1.0, 0.0), (1.0, 0.0), (-1.0, 1.0), (0.0, 1.0), (1.0, 1.0)];
        let atlas = self.layout_atlas();
        let tiefe = |x: f32, y: f32| depth.map_or(0.0, |f| f(x, y));
        let baseline = top + atlas.ascent_px();
        let mut pen = x;
        let (w, h) = screen_px;
        let ndc = |p: (f32, f32)| [(p.0 / w) * 2.0 - 1.0, 1.0 - (p.1 / h) * 2.0];
        for ch in atlas.display_text(text).chars() {
            let Some(g) = atlas.glyph(ch) else { continue };
            if let Some(p) = atlas.place(ch, raster).filter(|p| p.size[0] > 0.0 && p.size[1] > 0.0) {
                let x0 = pen + p.offset[0] / raster;
                let y0 = baseline + p.offset[1] / raster;
                let (x1, y1) = (x0 + p.size[0] / raster, y0 + p.size[1] / raster);
                if let (Some(a), Some(b), Some(c), Some(d)) = (project(x0, y0), project(x1, y0), project(x1, y1), project(x0, y1)) {
                    let (u0, v0, u1, v1) = (p.uv_min[0], p.uv_min[1], p.uv_max[0], p.uv_max[1]);
                    let (za, zb, zc, zd) = (tiefe(x0, y0), tiefe(x1, y0), tiefe(x1, y1), tiefe(x0, y1));
                    let mut quad = |dx: f32, dy: f32, color: [f32; 4]| {
                        let v = |q: (f32, f32), u: f32, vv: f32, z: f32| TextVertex {
                            position: ndc((q.0 + dx, q.1 + dy)),
                            uv: [u, vv],
                            color,
                            bounds: [0.0; 4],
                            mode: [0.0, 0.0, 0.0, z],
                        };
                        let (va, vb, vc, vd) = (v(a, u0, v0, za), v(b, u1, v0, zb), v(c, u1, v1, zc), v(d, u0, v1, zd));
                        let erstes = out.len();
                        out.extend_from_slice(&[va, vb, vc, va, vc, vd]);
                        if p.pack {
                            mark_pack_glyph(&mut out[erstes..]);
                        }
                    };
                    // Dieselbe Kontur wie auf dem Bildschirm (s. shape_text).
                    if let Some(rand) = rand {
                        for (dx, dy) in RICHTUNGEN {
                            quad(dx, dy, rand);
                        }
                    }
                    quad(0.0, 0.0, color);
                }
            }
            pen += g.advance_px;
        }
        pen - x
    }

    // Die Kontur eines Abschnitts Weltschrift (Schild, Text-Display): schwarz, oder in der
    // Schattenfarbe, die der Server dem Abschnitt gibt (Alpha 0 = keine). `erlaubt` = der Ort
    // zeichnet ueberhaupt einen Rand -- beim Text-Display entscheidet das der Server ueber
    // sein Schatten-Flag, wie in Vanilla.
    fn world_text_border(&self, color: [f32; 4], shadow: Option<u32>, erlaubt: bool) -> Option<[f32; 4]> {
        if !erlaubt || self.text_shadow_style == TextShadow::Off || color[3] <= 0.0 {
            return None;
        }
        let rand = match shadow.and_then(ego_name::shadow) {
            None => [0.0, 0.0, 0.0, color[3]],
            Some(argb) => {
                let [r, g, b, a] = argb_to_rgba(argb as i32);
                [r, g, b, a * color[3]]
            }
        };
        (rand[3] > 0.0 && !(is_black(color) && is_black(rand))).then_some(rand)
    }

    // UiSprites zu Vertices. Rueckgabe: die zusammenhaengenden Laeufe (Atlas, Startvertex,
    // Anzahl) -- ein Draw-Call je Lauf, weil ein Atlas-Wechsel eine andere Bind-Group
    // braucht. Die Reihenfolge der Sprites bleibt erhalten (Hintergrund vor Icons).
    fn shape_sprites(sprites: &[UiSprite], screen_px: (f32, f32), out: &mut Vec<TextVertex>) -> Vec<(SpriteAtlas, u32, u32)> {
        let mut runs: Vec<(SpriteAtlas, u32, u32)> = Vec::new();
        for sprite in sprites.iter().take(MAX_UI_SPRITES) {
            let [u0, v0, u1, v1] = sprite.uv;
            let uvs = [[u0, v0], [u1, v0], [u1, v1], [u0, v1]];
            // Glint-Zwillinge tragen in der Farbe ihre Glint-UV: lokal 0..1 ueber das Quad, mal
            // Vanillas Item-Massstab (s. render::glint::GLINT_SCALE_ITEM); Alpha bleibt.
            let lokal = [[0.0, 0.0], [1.0, 0.0], [1.0, 1.0], [0.0, 1.0]];
            let s = render::glint::GLINT_SCALE_ITEM;
            let vertex = |i: usize| TextVertex {
                position: pixel_to_ndc(sprite.corners[i][0], sprite.corners[i][1], screen_px),
                uv: uvs[i],
                // z = Helligkeit des Icons darunter (Mittel der Toenung), s. sprite.wgsl::fs_glint.
                // Aus dem UI-Atlas (flache Items): x = -1 heisst "Glint-UV aus der Atlas-UV", s.
                // sprite.wgsl::fs_glint -- ein Icon aus vielen Pixel-Quads (Angel) bekam sonst
                // auf jedem Quad den ganzen Glint.
                color: if sprite.atlas == SpriteAtlas::GlintUi {
                    [-1.0, 0.0, (sprite.color[0] + sprite.color[1] + sprite.color[2]) / 3.0, sprite.color[3]]
                } else if sprite.atlas.is_glint() {
                    [lokal[i][0] * s, lokal[i][1] * s, (sprite.color[0] + sprite.color[1] + sprite.color[2]) / 3.0, sprite.color[3]]
                } else {
                    sprite.color
                },
                bounds: [0.0; 4],
                mode: [0.0; 4],
            };
            let start = out.len() as u32;
            out.extend_from_slice(&[vertex(0), vertex(1), vertex(2), vertex(0), vertex(2), vertex(3)]);
            match runs.last_mut() {
                Some((atlas, _, count)) if *atlas == sprite.atlas => *count += VERTS_PER_QUAD as u32,
                _ => runs.push((sprite.atlas, start, VERTS_PER_QUAD as u32)),
            }
        }
        runs
    }

    fn sprite_bind_group(&self, atlas: SpriteAtlas) -> &wgpu::BindGroup {
        match atlas {
            SpriteAtlas::ServerIcons => self.server_icons.as_ref().map_or(&self.ui_atlas_bind_group, |(_, b)| b),
            SpriteAtlas::PackIcons => self.pack_icons.as_ref().map_or(&self.ui_atlas_bind_group, |(_, b)| b),
            SpriteAtlas::Logos => self.logos.as_ref().map_or(&self.ui_atlas_bind_group, |(_, b)| b),
            SpriteAtlas::Ui | SpriteAtlas::GlintUi => &self.ui_atlas_bind_group,
            SpriteAtlas::Block | SpriteAtlas::GlintBlock => &self.block_atlas_sprite_bind_group,
            SpriteAtlas::Entity | SpriteAtlas::GlintEntity => &self.entity_atlas_sprite_bind_group,
        }
    }

    // Zeichnet die Sprite-Laeufe (s. shape_sprites) aus dem schon gebundenen
    // sprite_vertex_buffer. Glint-Laeufe wechseln auf die additive Glint-Pipeline und binden
    // zusaetzlich Glint-Textur + Matrix (Gruppe 1).
    fn draw_sprite_runs(&self, pass: &mut wgpu::RenderPass<'_>, runs: &[(SpriteAtlas, u32, u32)]) {
        let mut glint_aktiv = None;
        for (atlas, start, count) in runs {
            if glint_aktiv != Some(atlas.is_glint()) {
                glint_aktiv = Some(atlas.is_glint());
                if atlas.is_glint() {
                    pass.set_pipeline(&self.glint_sprite_pipeline);
                    pass.set_bind_group(1, &self.glint_gui_bind_group, &[]);
                } else {
                    pass.set_pipeline(&self.sprite_pipeline);
                }
            }
            pass.set_bind_group(0, self.sprite_bind_group(*atlas), &[]);
            pass.draw(*start..(*start + *count), 0..1);
        }
    }

    // Das gerade in offscreen_view stehende Weltbild als Menue-Hintergrund bereitstellen (s.
    // world_backdrop). Die Bind-Group haengt an der View und bleibt bis zum naechsten Resize.
    fn keep_world_backdrop(&mut self) {
        if self.world_backdrop.is_some() {
            return;
        }
        self.world_backdrop = Some(self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("world backdrop bind group"),
            layout: &self.sprite_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&self.offscreen_view) },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.wallpaper_sampler) },
            ],
        }));
    }

    // Neues Hintergrundbild hochladen (None = keins mehr).
    // Ein Server-Icon (64x64 RGBA) in Platz `slot` des Icon-Atlas legen.
    // Ecken abgerundet wie die Flaeche darunter (Radius 6 auf dem Bildschirm, s.
    // upload_pack_icon).
    fn upload_server_icon(&mut self, slot: usize, rgba: &[u8]) {
        let mut rund = rgba.to_vec();
        round_icon_corners(&mut rund, server_status::ICON_SIZE, 6.0 * server_status::ICON_SIZE as f32 / server_icon_px());
        let mut atlas = self.server_icons.take();
        self.upload_icon(&mut atlas, "server icons", SERVER_ICON_GRID, server_status::ICON_SIZE, slot, &rund);
        self.server_icons = atlas;
    }

    // Ein Pack-Bild (skin_tab::ICON_PX zum Quadrat, RGBA) in Platz `slot` des Pack-Atlas. Die
    // Ecken werden dabei abgerundet wie die Flaechen darunter und darueber (Radius 6 auf dem
    // Bildschirm) -- ein Sprite selbst kennt keine runden Ecken.
    fn upload_pack_icon(&mut self, slot: usize, rgba: &[u8]) {
        let mut rund = rgba.to_vec();
        let anzeige = skin_icon_rect(skin_tile_rect(skin_tab::Column::Available, 0.0)).w.max(1.0);
        round_icon_corners(&mut rund, skin_tab::ICON_PX, 6.0 * skin_tab::ICON_PX as f32 / anzeige);
        let mut atlas = self.pack_icons.take();
        self.upload_icon(&mut atlas, "pack icons", skin_tab::ICON_GRID, skin_tab::ICON_PX, slot, &rund);
        self.pack_icons = atlas;
    }

    // Die Logos aus SIDEBAR_LINKS in ihren Atlas, Platz = Index.
    fn upload_logos(&mut self) {
        for (slot, (_, _, png)) in SIDEBAR_LINKS.iter().enumerate() {
            let Ok(bild) = image::load_from_memory_with_format(png, image::ImageFormat::Png) else { continue };
            let mut atlas = self.logos.take();
            self.upload_icon(&mut atlas, "logos", LOGO_GRID, LOGO_PX, slot, &bild.to_rgba8());
            self.logos = atlas;
        }
    }

    // Gemeinsam fuer alle Icon-Atlanten: `n` x `n` Plaetze zu `s` Pixeln, angelegt beim
    // ersten Bild.
    fn upload_icon(&self, atlas: &mut Option<(wgpu::Texture, wgpu::BindGroup)>, label: &str, n: u32, s: u32, slot: usize, rgba: &[u8]) {
        if atlas.is_none() {
            let texture = self.device.create_texture(&wgpu::TextureDescriptor {
                label: Some(label),
                size: wgpu::Extent3d { width: n * s, height: n * s, depth_or_array_layers: 1 },
                mip_level_count: 1,
                sample_count: 1,
                dimension: wgpu::TextureDimension::D2,
                format: wgpu::TextureFormat::Rgba8UnormSrgb,
                usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
                view_formats: &[],
            });
            let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
            let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
                label: Some(label),
                layout: &self.sprite_bind_group_layout,
                entries: &[
                    wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&view) },
                    wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.wallpaper_sampler) },
                ],
            });
            *atlas = Some((texture, bind_group));
        }
        let Some((texture, _)) = atlas.as_ref() else { return };
        let (x, y) = ((slot as u32 % n) * s, (slot as u32 / n) * s);
        if rgba.len() != (s * s * 4) as usize || slot as u32 >= n * n {
            return;
        }
        self.queue.write_texture(
            wgpu::ImageCopyTexture { texture, mip_level: 0, origin: wgpu::Origin3d { x, y, z: 0 }, aspect: wgpu::TextureAspect::All },
            rgba,
            wgpu::ImageDataLayout { offset: 0, bytes_per_row: Some(s * 4), rows_per_image: Some(s) },
            wgpu::Extent3d { width: s, height: s, depth_or_array_layers: 1 },
        );
    }

    fn set_wallpaper(&mut self, bild: Option<&wallpaper::Decoded>) {
        self.wallpaper = bild.map(|b| self.upload_background("wallpaper", b, wgpu::TextureFormat::Rgba8UnormSrgb));
    }

    // Ein ganzes Bild als eigene Sprite-Textur (Hintergrundbild, letzter Weltblick).
    fn upload_background(&self, label: &str, b: &wallpaper::Decoded, format: wgpu::TextureFormat) -> (wgpu::BindGroup, (u32, u32)) {
        let extent = wgpu::Extent3d { width: b.width, height: b.height, depth_or_array_layers: 1 };
        let texture = self.device.create_texture(&wgpu::TextureDescriptor {
            label: Some(label),
            size: extent,
            mip_level_count: 1,
            sample_count: 1,
            dimension: wgpu::TextureDimension::D2,
            format,
            usage: wgpu::TextureUsages::TEXTURE_BINDING | wgpu::TextureUsages::COPY_DST,
            view_formats: &[],
        });
        self.queue.write_texture(
            wgpu::ImageCopyTexture { texture: &texture, mip_level: 0, origin: wgpu::Origin3d::ZERO, aspect: wgpu::TextureAspect::All },
            &b.rgba,
            wgpu::ImageDataLayout { offset: 0, bytes_per_row: Some(b.width * 4), rows_per_image: Some(b.height) },
            extent,
        );
        let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
        let bind_group = self.device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some(label),
            layout: &self.sprite_bind_group_layout,
            entries: &[
                wgpu::BindGroupEntry { binding: 0, resource: wgpu::BindingResource::TextureView(&view) },
                wgpu::BindGroupEntry { binding: 1, resource: wgpu::BindingResource::Sampler(&self.wallpaper_sampler) },
            ],
        });
        (bind_group, (b.width, b.height))
    }

    // Letzten Weltblick hochladen (s. last_view.rs). Die Bytes stammen roh aus offscreen_texture,
    // also dieselbe sRGB-Deutung wie dort -- sonst saehe das Bild heller oder dunkler aus als die
    // Welt hinter dem Pausemenue.
    fn set_last_view(&mut self, b: &wallpaper::Decoded) {
        let format = if self.config.format.is_srgb() { wgpu::TextureFormat::Rgba8UnormSrgb } else { wgpu::TextureFormat::Rgba8Unorm };
        self.last_view = Some(self.upload_background("last view", b, format));
    }

    // Dasselbe fuer den Verbindungsbildschirm (s. App::connect_view_shown).
    fn set_connect_view(&mut self, b: &wallpaper::Decoded) {
        let format = if self.config.format.is_srgb() { wgpu::TextureFormat::Rgba8UnormSrgb } else { wgpu::TextureFormat::Rgba8Unorm };
        self.connect_view = Some(self.upload_background("connect view", b, format));
    }

    // Das gerade in offscreen_texture stehende Weltbild in den Speicher lesen, falls es eins ohne
    // HUD ist (s. offscreen_world_only). Wartet auf die GPU -- laeuft nur beim Verlassen einer
    // Welt, nie im Frame.
    fn read_world_view(&self) -> Option<wallpaper::Decoded> {
        if !self.offscreen_world_only {
            return None;
        }
        let bgra = match self.config.format {
            wgpu::TextureFormat::Bgra8Unorm | wgpu::TextureFormat::Bgra8UnormSrgb => true,
            wgpu::TextureFormat::Rgba8Unorm | wgpu::TextureFormat::Rgba8UnormSrgb => false,
            _ => return None,
        };
        let (w, h) = (self.offscreen_texture.width(), self.offscreen_texture.height());
        let zeile = (w * 4).div_ceil(wgpu::COPY_BYTES_PER_ROW_ALIGNMENT) * wgpu::COPY_BYTES_PER_ROW_ALIGNMENT;
        let puffer = self.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("last view readback"),
            size: zeile as u64 * h as u64,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });
        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("last view readback") });
        encoder.copy_texture_to_buffer(
            self.offscreen_texture.as_image_copy(),
            wgpu::ImageCopyBuffer { buffer: &puffer, layout: wgpu::ImageDataLayout { offset: 0, bytes_per_row: Some(zeile), rows_per_image: Some(h) } },
            wgpu::Extent3d { width: w, height: h, depth_or_array_layers: 1 },
        );
        self.queue.submit(std::iter::once(encoder.finish()));
        let (tx, rx) = std::sync::mpsc::channel();
        puffer.slice(..).map_async(wgpu::MapMode::Read, move |r| {
            let _ = tx.send(r);
        });
        let _ = self.device.poll(wgpu::Maintain::Wait);
        rx.recv().ok()?.ok()?;
        let mut rgba = Vec::with_capacity(w as usize * h as usize * 4);
        {
            let daten = puffer.slice(..).get_mapped_range();
            for y in 0..h as usize {
                let z = &daten[y * zeile as usize..][..w as usize * 4];
                for p in z.chunks_exact(4) {
                    // Alpha fest auf deckend: was im Alphakanal des Weltbilds steht, ist kein
                    // Bildinhalt.
                    let px = if bgra { [p[2], p[1], p[0], 255] } else { [p[0], p[1], p[2], 255] };
                    rgba.extend_from_slice(&px);
                }
            }
        }
        puffer.unmap();
        Some(wallpaper::Decoded { rgba, width: w, height: h })
    }

    // Glint-Textur des GUI-Glints (neu nach einem Pack-Wechsel).
    fn set_gui_glint_texture(&mut self, textur: &Option<assets::DecodedTexture>) {
        let (rgba, w, h) = glint_texture_part(textur);
        let view = render::glint::upload_texture(&self.device, &self.queue, rgba, w, h);
        self.glint_gui_bind_group = create_gui_glint_bind_group(
            &self.device,
            &self.glint_gui_bind_group_layout,
            &view,
            &self.glint_gui_sampler,
            &self.glint_gui_uniform,
        );
    }

    // Einmal pro Frame, wie render::BlockRenderer::update_glint.
    fn update_gui_glint(&self, ms: u64, speed: f32, strength: f32) {
        let uniform = render::glint::GlintUniform { rows: render::glint::glint_matrix(ms, speed), params: [strength, 0.0, 0.0, 0.0] };
        self.queue.write_buffer(&self.glint_gui_uniform, 0, bytemuck::bytes_of(&uniform));
    }

    // Nach einem Resourcepack-Wechsel zeigen beide Bind-Groups auf veraltete Texturen: der
    // Blockatlas wurde neu hochgeladen (rebuild_atlas), der UI-Atlas neu gebaut.
    fn rebuild_sprite_atlases(&mut self, ui_atlas_rgba: &[u8], ui_atlas_size: u32) {
        (self.ui_atlas_bind_group, self.ui_atlas_texture) = create_ui_atlas_bind_group(
            &self.device,
            &self.queue,
            &self.sprite_bind_group_layout,
            &self.sprite_sampler,
            ui_atlas_rgba,
            ui_atlas_size,
        );
        self.block_atlas_sprite_bind_group =
            create_block_sprite_bind_group(&self.device, &self.sprite_bind_group_layout, &self.sprite_sampler, &self.block_renderer);
        self.entity_atlas_sprite_bind_group =
            create_entity_sprite_bind_group(&self.device, &self.sprite_bind_group_layout, &self.sprite_sampler, &self.block_renderer);
    }

    // Die Overlay-Ebene als Vertices, jede Gruppe um ihren Drehpunkt gedreht (s. UiOverlay).
    //
    // VOR dem Text der normalen UI aufrufen: shape_text merkt sich die Zeilen fuer die
    // Textauswahl und beginnt dabei jedes Mal von vorn -- so bleiben die Zeilen der normalen
    // UI stehen, und der (gedrehte) Overlay-Text ist nicht auswaehlbar.
    //
    // Dazu je Gruppe, wo ihre Flaechen und ihr Text liegen (relativ zum Anfang der Ebene):
    // gezeichnet wird Gruppe fuer Gruppe, erst Flaechen, dann Text. Sonst schiene der Text
    // einer Karte durch eine andere, die gerade ueber sie hinwegfaellt.
    fn overlay_vertices(&self, overlay: &UiOverlay, screen_px: (f32, f32)) -> OverlayVertices {
        let mut quads = Vec::new();
        let mut text = Vec::new();
        let mut sprites = Vec::new();
        let mut ranges = Vec::new();
        for g in &overlay.groups {
            let q0 = quads.len();
            for r in &g.rects {
                quads.extend_from_slice(&rect_verts(r, screen_px));
            }
            let s0 = sprites.len();
            let laeufe = Self::shape_sprites(&g.sprites, screen_px, &mut sprites);
            let t0 = text.len();
            let mut glyphen = Vec::new();
            self.shape_text(&g.texts, screen_px, &mut glyphen);
            text.extend(glyphen);
            if g.angle != 0.0 {
                for v in &mut quads[q0..] {
                    v.position = rotate_ndc(v.position, g.pivot, g.angle, screen_px);
                }
                for v in &mut text[t0..] {
                    v.position = rotate_ndc(v.position, g.pivot, g.angle, screen_px);
                }
                for v in &mut sprites[s0..] {
                    v.position = rotate_ndc(v.position, g.pivot, g.angle, screen_px);
                }
            }
            ranges.push(OverlayRange { quads: q0 as u32..quads.len() as u32, text: t0 as u32..text.len() as u32, sprites: laeufe });
        }
        OverlayVertices { quads, text, sprites, ranges }
    }

    // Das Oberste eines UI-Passes, in dieser Reihenfolge: der normale Text, die Overlay-Ebene
    // (ihre Flaechen, dann ihr Text) und zuletzt der Zeiger. `text`/`quads` sind je (Ende der
    // normalen UI, Ende insgesamt) in den Vertexpuffern, s. append_overlay.
    fn draw_ui_top(
        &self,
        pass: &mut wgpu::RenderPass<'_>,
        text: (u32, u32),
        quads: (u32, u32),
        overlay: &[OverlayRange],
        // (Anfang der Overlay-Sprites, Ende insgesamt) im Sprite-Puffer, s. append_overlay_sprites.
        sprites: (u32, u32),
        cursor: bool,
        schriften: &[(u32, FontKind)],
    ) {
        if text.0 > 0 {
            // Abschnitt fuer Abschnitt mit dem Atlas seiner Schrift (s. shape_text).
            pass.set_pipeline(&self.text_pipeline);
            pass.set_vertex_buffer(0, self.text_vertex_buffer.slice(..));
            let mut von = 0;
            let mut kind = self.font_atlas.kind();
            for &(ab, naechste) in schriften.iter().chain(std::iter::once(&(text.0, kind))) {
                let ab = ab.min(text.0);
                if ab > von {
                    pass.set_bind_group(0, &self.hud_font(kind).bind_group, &[]);
                    pass.draw(von..ab, 0..1);
                    von = ab;
                }
                kind = naechste;
            }
        }
        // Gruppe fuer Gruppe (s. overlay_vertices). Die Bereiche sind relativ zum Anfang der
        // Ebene und werden auf das geklemmt, was append_overlay tatsaechlich hochgeladen hat.
        let klemmen = |r: &std::ops::Range<u32>, (von, bis): (u32, u32)| (von + r.start).min(bis)..(von + r.end).min(bis);
        for g in overlay {
            let q = klemmen(&g.quads, quads);
            if !q.is_empty() {
                pass.set_pipeline(&self.quad_pipeline);
                pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
                pass.draw(q, 0..1);
            }
            let laeufe: Vec<(SpriteAtlas, u32, u32)> = g
                .sprites
                .iter()
                .map(|&(atlas, start, count)| {
                    let r = klemmen(&(start..start + count), sprites);
                    (atlas, r.start, r.end - r.start)
                })
                .filter(|&(_, _, count)| count > 0)
                .collect();
            if !laeufe.is_empty() {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                self.draw_sprite_runs(pass, &laeufe);
            }
            let t = klemmen(&g.text, text);
            if !t.is_empty() {
                pass.set_pipeline(&self.text_pipeline);
                pass.set_bind_group(0, &self.font_atlas.bind_group, &[]);
                pass.set_vertex_buffer(0, self.text_vertex_buffer.slice(..));
                pass.draw(t, 0..1);
            }
        }
        if cursor {
            pass.set_pipeline(&self.cursor_pipeline);
            pass.set_bind_group(0, &self.cursor_bind_group, &[]);
            pass.draw(0..6, 0..1);
        }
    }

    // Die weiteren Font-Atlanten bereitstellen, die Anzeigen oder Bereiche statt der
    // allgemeinen Schrift wollen; nicht mehr gewollte fallen weg. Gebaut wird nur beim ersten
    // Bedarf -- eine TTF zu rastern kostet einen Moment.
    fn ensure_fonts(&mut self, installation: &mut assets::MinecraftInstallation, wanted: &[FontKind]) {
        let allgemein = self.font_atlas.kind();
        self.extra_fonts.retain(|a| a.kind() != allgemein && wanted.contains(&a.kind()));
        for &kind in wanted {
            if kind == allgemein || self.extra_fonts.iter().any(|a| a.kind() == kind) {
                continue;
            }
            match FontAtlas::build_shared(&self.device, &self.queue, installation, kind, self.font_atlas.bind_group_layout.clone()) {
                Ok(mut atlas) => {
                    atlas.set_pack(&self.device, self.pack_glyphs.clone());
                    self.extra_fonts.push(atlas);
                }
                Err(e) => eprintln!("[font] Zweitschrift {} nicht geladen: {e}", kind.label()),
            }
        }
    }

    // Neue Resourcepack-Schriften in alle Atlanten (nach einem Pack-Wechsel).
    fn set_pack_fonts(&mut self, fonts: assets::PackFonts) {
        let cache = Some(Arc::new(font_atlas::PackGlyphCache::new(&self.device, self.queue.clone(), fonts)));
        self.font_atlas.set_pack(&self.device, cache.clone());
        for a in &mut self.extra_fonts {
            a.set_pack(&self.device, cache.clone());
        }
        self.pack_glyphs = cache;
    }

    // Der Atlas in Schrift `kind`, solange er nicht geladen ist der gewoehnliche.
    fn hud_font(&self, kind: FontKind) -> &FontAtlas {
        if kind == self.font_atlas.kind() {
            return &self.font_atlas;
        }
        self.extra_fonts.iter().find(|a| a.kind() == kind).unwrap_or(&self.font_atlas)
    }

    // Der Atlas, mit dem gerade gemessen und gesetzt wird (s. layout_font).
    fn layout_atlas(&self) -> &FontAtlas {
        self.layout_font.get().map_or(&self.font_atlas, |k| self.hud_font(k))
    }

    fn set_layout_font(&self, font: Option<FontKind>) {
        self.layout_font.set(font);
    }

    // Eine HUD-Zahl als Glyphen-Vierecke fuer den Fadenkreuz-Pass, um ihre Mitte gesetzt.
    // Weiss wird immer umrandet; in Fadenkreuz-Farbe nur, wenn das Kreuz eine Kontur hat.
    fn crosshair_glyph_vertices(&self, atlas: &FontAtlas, t: &CrosshairText, crosshair_outline: bool, screen_px: (f32, f32)) -> Vec<CrosshairVertex> {
        let scale = t.scale;
        let breite: f32 = t.text.chars().filter_map(|c| atlas.glyph(c)).map(|g| g.advance_px * scale).sum();
        let hoehe = atlas.cell_height_px() * scale;
        let x0 = (t.center_px.0 - breite / 2.0).round();
        let top = (t.center_px.1 - hoehe / 2.0).round();
        let baseline = top + atlas.ascent_px() * scale;
        // Die Glyphen einmal setzen, danach je Lage (Kontur-Versaetze, Fuellung) ausgeben.
        let mut quads = Vec::new();
        let mut pen = x0;
        for ch in t.text.chars() {
            let Some(g) = atlas.glyph(ch) else { continue };
            if let Some(p) = atlas.place(ch, scale).filter(|p| p.size[0] > 0.0 && p.size[1] > 0.0) {
                let (p, x) = atlas.snap_x(ch, scale, false, p, pen);
                let (ox, oy) = if p.snap { (x, baseline.round()) } else { (pen, baseline) };
                quads.push((ox + p.offset[0], oy + p.offset[1], p.size, p.uv_min, p.uv_max));
            }
            pen += g.advance_px * scale;
        }
        let konturiert = t.white || crosshair_outline;
        let d = (scale / 2.0).round().max(1.0);
        const RICHTUNGEN: [(f32, f32); 8] = [(-1.0, -1.0), (0.0, -1.0), (1.0, -1.0), (-1.0, 0.0), (1.0, 0.0), (-1.0, 1.0), (0.0, 1.0), (1.0, 1.0)];
        let fuellung = if t.white { CROSSHAIR_KIND_GLYPH_WHITE } else { CROSSHAIR_KIND_GLYPH };
        let lagen = RICHTUNGEN
            .iter()
            .filter(|_| konturiert)
            .map(|&(dx, dy)| (dx * d, dy * d, CROSSHAIR_KIND_GLYPH_BLACK))
            .chain(std::iter::once((0.0, 0.0, fuellung)));
        let mut out = Vec::new();
        for (dx, dy, kind) in lagen {
            for &(x, y, size, uv0, uv1) in &quads {
                let (x0, y0, x1, y1) = (x + dx, y + dy, x + dx + size[0], y + dy + size[1]);
                let v = |px: f32, py: f32, gu: f32, gv: f32| CrosshairVertex {
                    position: pixel_to_ndc(px, py, screen_px),
                    uv: [px / screen_px.0, py / screen_px.1],
                    glyph_uv: [gu, gv],
                    kind,
                    alpha: t.alpha,
                    circle: [0.0; 2],
                };
                out.extend_from_slice(&[
                    v(x0, y0, uv0[0], uv0[1]),
                    v(x1, y0, uv1[0], uv0[1]),
                    v(x1, y1, uv1[0], uv1[1]),
                    v(x0, y0, uv0[0], uv0[1]),
                    v(x1, y1, uv1[0], uv1[1]),
                    v(x0, y1, uv0[0], uv1[1]),
                ]);
            }
        }
        out
    }

    // Holt das naechste Swapchain-Bild -- der Punkt, an dem Fifo auf den VBlank wartet.
    // Liefert das Bild und die Wartezeit in ms (s. FrameTiming).
    //
    // Wird aufgerufen, BEVOR der Frame gebaut wird, nicht erst beim Zeichnen: erst nach dem
    // Warten ist der Abstand bis zur Anzeige fest (ein VBlank). Die Uhrzeit, aus der Kamera,
    // Entities und alles andere Bewegte interpoliert werden, muss DANACH gelesen werden.
    // Vorher stand das Warten am Ende -- zwischen Zeitmessung und Anzeige lagen dann Meshing,
    // Pakete und Vertex-Aufbau, die je Frame unterschiedlich lange dauern, waehrend das Bild
    // trotzdem immer am VBlank erschien. Jedes Bild zeigte so einen leicht falschen
    // Zeitpunkt: im Spiel sichtbares Ruckeln (sichtbar im Tearing-Test, im Menue ohne
    // diese Arbeit kaum zu sehen).
    fn acquire_frame(&mut self) -> Option<(wgpu::SurfaceTexture, f32)> {
        // get_current_texture() ist der Punkt, an dem Fifo tatsaechlich wartet (s.
        // render_menu). Zeitmessung VOR der Zero-Modus-Fence-Wait, sonst waere deren
        // Wartezeit im HUD unsichtbar.
        let acquire_started = Instant::now();
        self.wait_for_previous_frame_if_zero_mode();
        match self.surface.get_current_texture() {
            Ok(frame) => Some((frame, acquire_started.elapsed().as_secs_f32() * 1000.0)),
            Err(_) => {
                self.surface.configure(&self.device, &self.config);
                None
            }
        }
    }

    // Gemeinsames Ende von render_menu/render_world, mit getrennter Zeitmessung.
    fn submit_and_present(
        &mut self,
        mut encoder: wgpu::CommandEncoder,
        frame: wgpu::SurfaceTexture,
        wait_ms: f32,
        work_started: Instant,
    ) -> FrameTiming {
        if let Some(timer) = self.gpu_timer.as_mut() {
            timer.end_frame(&mut encoder);
        }
        let screenshot = std::mem::take(&mut self.screenshot_requested)
            .then(|| screenshot::copy(&self.device, &mut encoder, &frame.texture, self.config.format));
        let encode_ms = work_started.elapsed().as_secs_f32() * 1000.0;
        let t = Instant::now();
        self.last_submission = Some(self.queue.submit(Some(encoder.finish())));
        if let Some(timer) = self.gpu_timer.as_mut() {
            timer.after_submit();
        }
        let submit_ms = t.elapsed().as_secs_f32() * 1000.0;
        // Riss-Steuerung: erst die GPU fertig werden lassen, dann bis auf den berechneten
        // Zeitpunkt warten und DANN praesentieren (s. App::tear_slot). Der Bildwechsel haengt so
        // nicht mehr an der schwankenden Frame-Arbeit, nur noch an diesem einen Zeitpunkt.
        let mut ready_ns = None;
        let mut idle_ms = wait_ms;
        if let (Some(at), Some(index)) = (self.present_at_ns.take(), &self.last_submission) {
            let t = Instant::now();
            self.device.poll(wgpu::Maintain::WaitForSubmissionIndex(index.clone()));
            let ready = vblank::monotonic_ns();
            ready_ns = Some(ready);
            wait_until_ns(at);
            idle_ms += t.elapsed().as_secs_f32() * 1000.0;
        }
        let t = Instant::now();
        let present_ns = vblank::monotonic_ns();
        frame.present();
        #[cfg(windows)]
        vblank::note_present();
        let present_ms = t.elapsed().as_secs_f32() * 1000.0;
        if let Some(pending) = screenshot {
            screenshot::finish(&self.device, pending);
        }
        // Present ist Warten auf Treiber und Compositor, keine eigene Arbeit -- wie das Warten
        // in get_current_texture(). Haelt das System den Bildschirm an (Screenshot-Werkzeug),
        // stand das sonst als Arbeitsspitze in der Leistungsanzeige (25 statt 2,5 ms).
        idle_ms += present_ms;
        let gpu_done_ns = match (ready_ns, &self.last_submission, self.measure_gpu_done) {
            // GPU war schon vor dem Present fertig: der Wechsel folgt dem Present-Aufruf.
            (Some(_), _, _) => Some(present_ns),
            (None, Some(index), true) => {
                let t = Instant::now();
                self.device.poll(wgpu::Maintain::WaitForSubmissionIndex(index.clone()));
                idle_ms += t.elapsed().as_secs_f32() * 1000.0;
                Some(vblank::monotonic_ns())
            }
            _ => None,
        };
        FrameTiming { idle_ms, encode_ms, submit_ms, present_ms, present_ns, gpu_done_ns, ready_ns }
    }

    fn render_menu(
        &mut self,
        rects: &[UiRect],
        texts: &[UiText],
        sprites: &[UiSprite],
        overlay: &UiOverlay,
        cursor: Option<(f32, f32)>,
        cursor_fx: CursorFxFrame,
        // Hintergrundbild zeichnen (nur auf dem Startbildschirm, s. App::wallpaper_visible).
        show_wallpaper: bool,
        // Das Weltbild dahinter mit dieser Helligkeit (verbunden, s. App::world_backdrop_visible),
        // None = keins.
        show_world: Option<f32>,
        // Den letzten Weltblick zeichnen (HUD-Editor ohne Verbindung, s. App::last_view_visible).
        show_last_view: bool,
        // Den letzten Blick des Servereintrags mit dieser Helligkeit (Verbindungsbildschirm, s.
        // App::connect_view_shown), None = keinen.
        show_connect_view: Option<f32>,
        // Aus acquire_frame -- das Bild wird VOR dem Aufbau des Frames geholt, s. dort.
        acquired: (wgpu::SurfaceTexture, f32),
    ) -> Option<FrameTiming> {
        // get_current_texture() ist der Punkt, an dem Fifo tatsaechlich wartet: die
        // Funktion blockiert, bis ein Swapchain-Bild frei wird -- bei Fifo also bis zum
        // naechsten VBlank. Getrennt gemessen, sonst zeigt das HUD bei Fifo fast nur
        // Wartezeit als vermeintliche "Arbeit" an (vgl. osu!lazer:
        // exakt die Zeit, die osu.Framework per WaitUntilIdle() erzwingt).
        // Zeitmessung faengt VOR der Zero-Modus-Fence-Wait an (s. Feldkommentar), nicht erst
        // danach -- sonst waere die (bei aktivem Zero-Modus oft dominante) Wartezeit auf das
        // vorherige Frame im HUD unsichtbar und man koennte nicht nachpruefen, dass da
        // ueberhaupt echt gewartet wird.
        let (frame, wait_ms) = acquired;
        let work_started = Instant::now();
        let view = frame.texture.create_view(&wgpu::TextureViewDescriptor::default());
        let screen_px = self.size();

        let mut quad_data: Vec<Vertex> = Vec::with_capacity(rects.len() * VERTS_PER_QUAD);
        for r in rects.iter().take(MAX_UI_RECTS) {
            quad_data.extend_from_slice(&rect_verts(r, screen_px));
        }
        let ov = self.overlay_vertices(overlay, screen_px);
        let quad_split = append_overlay(&mut quad_data, &ov.quads, MAX_UI_RECTS * VERTS_PER_QUAD);
        if !quad_data.is_empty() {
            self.queue.write_buffer(&self.quad_vertex_buffer, 0, bytemuck::cast_slice(&quad_data));
        }

        let mut text_data: Vec<TextVertex> = Vec::new();
        let schriften = self.shape_text(texts, screen_px, &mut text_data);
        let text_split = append_overlay(&mut text_data, &ov.text, MAX_UI_GLYPHS * VERTS_PER_QUAD);
        if !text_data.is_empty() {
            self.queue.write_buffer(&self.text_vertex_buffer, 0, bytemuck::cast_slice(&text_data));
        }

        // Texturierte Quads -- im Menue bisher nur die Hotbar-Vorschau des HUD-Editors.
        let mut sprite_data: Vec<TextVertex> = Vec::new();
        // Das Hintergrundbild als erstes Quad im selben Puffer: es wird VOR den Flaechen
        // gezeichnet (s. unten), der Rest des Puffers wie gehabt danach.
        // Verbunden: stattdessen das letzte Weltbild, abgedunkelt wie Vanillas Pausemenue.
        let hintergrund: Option<(&wgpu::BindGroup, [f32; 4], [f32; 4])> = match (self.wallpaper.as_ref().filter(|_| show_wallpaper), self.world_backdrop.as_ref().zip(show_world)) {
            (Some((bind_group, groesse)), _) => Some((bind_group, wallpaper::cover_uv(*groesse, screen_px), [1.0; 4])),
            (None, Some((bind_group, hell))) => Some((bind_group, [0.0, 0.0, 1.0, 1.0], [hell, hell, hell, 1.0])),
            _ if show_connect_view.is_some() && self.connect_view.is_some() => {
                let hell = show_connect_view.unwrap_or(1.0);
                self.connect_view.as_ref().map(|(bind_group, groesse)| (bind_group, wallpaper::cover_uv(*groesse, screen_px), [hell, hell, hell, 1.0]))
            }
            // Unabgedunkelt: im HUD-Editor soll man sehen, wie das HUD im Spiel wirkt.
            _ => self
                .last_view
                .as_ref()
                .filter(|_| show_last_view)
                .map(|(bind_group, groesse)| (bind_group, wallpaper::cover_uv(*groesse, screen_px), [1.0; 4])),
        };
        if let Some((_, [u0, v0, u1, v1], farbe)) = hintergrund {
            let (w, h) = screen_px;
            let ecken = [([0.0, 0.0], [u0, v0]), ([w, 0.0], [u1, v0]), ([w, h], [u1, v1]), ([0.0, h], [u0, v1])];
            let vertex = |i: usize| TextVertex {
                position: pixel_to_ndc(ecken[i].0[0], ecken[i].0[1], screen_px),
                uv: ecken[i].1,
                color: farbe,
                bounds: [0.0; 4],
                mode: [0.0; 4],
            };
            sprite_data.extend_from_slice(&[vertex(0), vertex(1), vertex(2), vertex(0), vertex(2), vertex(3)]);
        }
        let sprite_runs = Self::shape_sprites(sprites, screen_px, &mut sprite_data);
        let sprite_split = append_overlay_sprites(&mut sprite_data, &ov.sprites);
        if !sprite_data.is_empty() {
            self.queue.write_buffer(&self.sprite_vertex_buffer, 0, bytemuck::cast_slice(&sprite_data));
        }

        // Eigenes Uniform statt Dreiecke im quad_vertex_buffer: der Zeiger wird im Shader
        // kantengeglaettet (s. cursor.wgsl) und muss ausserdem NACH dem Text gezeichnet
        // werden (dritter Durchgang unten) -- der quad_vertex_buffer ist zu dem Zeitpunkt
        // schon an den ersten Draw-Call gebunden, ein zweites Beschreiben wuerde dessen
        // Inhalt fuer den GANZEN Frame veraendern, nicht nur ab hier.
        if let Some(pos) = cursor {
            self.queue.write_buffer(&self.cursor_uniform_buffer, 0, bytemuck::bytes_of(&cursor_polygons(pos, screen_px, cursor_fx)));
        }

        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("menu encoder") });
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("menu pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &view,
                    resolve_target: None,
                    ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::BLACK), store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: None,
                timestamp_writes: None,
                occlusion_query_set: None,
            });

            if let Some((bind_group, _, _)) = hintergrund {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                pass.set_bind_group(0, bind_group, &[]);
                pass.draw(0..VERTS_PER_QUAD as u32, 0..1);
            }
            if quad_split > 0 {
                pass.set_pipeline(&self.quad_pipeline);
                pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
                pass.draw(0..quad_split, 0..1);
            }
            if !sprite_runs.is_empty() {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                self.draw_sprite_runs(&mut pass, &sprite_runs);
            }
            // Text, Overlay-Ebene und -- als dritter, letzter Durchgang -- der Cursor: er
            // gehoert IMMER nach vorn, unabhaengig davon, ob eine Flaeche oder Text darunter
            // liegt. Ohne Tiefentest in diesem Pass entscheidet allein die Zeichenreihenfolge.
            self.draw_ui_top(
                &mut pass,
                (text_split, text_data.len() as u32),
                (quad_split, quad_data.len() as u32),
                &ov.ranges,
                (sprite_split, sprite_data.len() as u32),
                cursor.is_some(),
                &schriften,
            );
        }
        Some(self.submit_and_present(encoder, frame, wait_ms, work_started))
    }

    // `crosshair_center` = normierte Position (0..1, Bildmitte samt Wackeln),
    // `crosshair_mode` = Index in CROSSHAIR_COLOR_MODES.

    // Welt im Shader-Pfad (s. render::shader_path): G-Buffer, Licht, Tonemap, dann der
    // Forward-Rest ins fertige Bild. Am Ende steht die Welt wie im PvP-Pfad in offscreen_view
    // und der Tiefenpuffer ist verbraucht -- Hand, HUD und Ausgabe laufen danach unveraendert.
    // Der Shader-Pfad samt Voxel-Abbild entsteht vorher in App::update_voxel_volume.
    fn render_world_shader_path(&mut self, encoder: &mut wgpu::CommandEncoder, sky: wgpu::Color, camera: &render::Camera) {
        let (width, height) = (self.config.width, self.config.height);
        let Some(sp) = self.shader_path.as_mut() else { return };
        sp.ensure_size(&self.device, width, height);
        {
            let color = sp.gbuffer_attachments();
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("gbuffer pass"),
                color_attachments: &color,
                depth_stencil_attachment: Some(sp.depth_attachment_keep()),
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("G-Buffer")),
                occlusion_query_set: None,
            });
            let timer = &mut self.gpu_timer;
            self.block_renderer.render_gbuffer(&mut pass, &mut |pass, label| {
                if let Some(t) = timer.as_mut() {
                    t.mark(pass, label);
                }
            });
        }
        let frame = render::shader_path::LightFrame {
            sky,
            daylight: self.block_renderer.daylight,
            view: camera.view_matrix(),
            proj: camera.proj_matrix(width as f32 / height.max(1) as f32),
            eye: camera.position,
            celestial: render::shader_path::celestial_light(self.sky_angle),
            shadows: true,
            atmosphere: self.atmosphere,
            scattering: self.scattering,
            sun_size_deg: self.sun_size_deg,
            block_shadows: self.block_shadows,
            block_softness_deg: self.block_softness_deg,
            lightmap_debug: self.lightmap_debug,
            sun_factor: world::light::stored_light_factor(world::light::SUNLIGHT),
        };
        sp.prepare(&self.queue, &frame);
        let set = self.gpu_timer.as_ref().map(|t| t.query_set());
        let timer = &mut self.gpu_timer;
        sp.shadows(encoder, &mut |label| {
            let (begin, end) = timer.as_mut()?.reserve(label)?;
            Some((set.as_deref()?, begin, end))
        });
        sp.light(encoder, self.gpu_timer.as_mut().and_then(|t| t.pass("Licht")));
        sp.tonemap(&self.queue, encoder, &self.offscreen_view, 1.0, self.gpu_timer.as_mut().and_then(|t| t.pass("Tonemap")));
        let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("forward rest pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: &self.offscreen_view,
                resolve_target: None,
                ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
            })],
            depth_stencil_attachment: Some(sp.depth_attachment_load()),
            timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Welt")),
            occlusion_query_set: None,
        });
        let timer = &mut self.gpu_timer;
        self.block_renderer.render_forward_rest(&mut pass, &mut |pass, label| {
            if let Some(t) = timer.as_mut() {
                t.mark(pass, label);
            }
        });
    }

    fn render_world(
        &mut self,
        camera: &render::Camera,
        // Die Himmelsfarbe dieses Frames, LINEAR (s. App::sky_clear_color). Frueher stand hier
        // eine Konstante -- damit war der Himmel Tag und Nacht derselbe.
        sky: wgpu::Color,
        rects: &[UiRect],
        hud_lines: &[UiLine],
        texts: &[UiText],
        // Texturierte Quads (Hotbar-/Inventar-Sheets, Item-Icons) -- gezeichnet nach den
        // farbigen Flaechen und vor dem Text, damit Stackgroessen darueber liegen.
        sprites: &[UiSprite],
        // Die oberste Ebene (Benachrichtigungen), s. UiOverlay.
        overlay: &UiOverlay,
        // Selbstgezeichneter Mauszeiger -- im Spiel nur bei offenem Inventar (sonst steuert
        // die Maus die Blickrichtung und es gibt keinen Zeiger).
        cursor: Option<(f32, f32)>,
        // Die Zeiger-Effekte dieses Frames (s. cursor_fx).
        cursor_fx: CursorFxFrame,
        // None = kein Fadenkreuz zeichnen (3.-Person-Perspektiven, s. Perspective) -- dort
        // zeigt es nicht mehr dorthin, wo man tatsaechlich hinzielt, weil die Kamera neben
        // dem Auge sitzt. Ein Fadenkreuz, das die falsche Stelle markiert, ist schlechter
        // als gar keines.
        crosshair_center: Option<(f32, f32)>,
        crosshair_mode: u32,
        // Feste Farbe im Modus Einfarbig (s. Settings::crosshair_rgb).
        crosshair_rgb: [f32; 3],
        // 0..1 -- Beimischung von Weiss, nur im Komplementaer-Modus wirksam (s. Shader).
        crosshair_boost: f32,
        crosshair_outline: bool,
        // Was der Fadenkreuz-Pass sonst noch zeichnet: HUD-Zahlen (Schild-Countdown, Pfeile)
        // und den Schild-Kreis, s. App::crosshair_extras. Wird auch ohne Fadenkreuz gezeichnet.
        crosshair_extras: CrosshairExtras,
        // CMAA2 (s. cmaa2.wgsl-Kommentar). Bei false laeuft der alte, direkte Kopierweg
        // unveraendert weiter.
        cmaa2_enabled: bool,
        // Modul "Farbe": Saettigung (1.0 = unveraendert), None = Modul aus bzw. 100 % -- dann
        // bleibt es bei der blossen Kopie.
        saturation: Option<f32>,
        // Vor welchem Sprite die Spielerfigur im Inventar gezeichnet wird (s.
        // App::build_inventory_screen). None = keine Figur in diesem Frame.
        doll_split: Option<usize>,
        // None = nur ins offscreen_view zeichnen, nichts praesentieren: das laufende Weltbild
        // hinter einem Menue (s. App::world_backdrop_visible), das render_menu danach zeigt.
        acquired: Option<(wgpu::SurfaceTexture, f32)>,
    ) -> Option<FrameTiming> {
        // Zeitmessung faengt VOR der Zero-Modus-Fence-Wait an (s. render_menu-Kommentar) --
        // sonst waere die Wartezeit auf das vorherige Frame im HUD unsichtbar.
        let work_started = Instant::now();

        let aspect = self.config.width as f32 / self.config.height.max(1) as f32;
        self.block_renderer.update_camera(&self.queue, camera, aspect);
        if self.block_renderer.vanilla.has_item_program() || self.block_renderer.vanilla.has_border_program() {
            let (zeit, licht) = (self.block_renderer.vanilla_game_time, self.block_renderer.daylight);
            self.block_renderer.vanilla.update_from_camera(&self.queue, camera, (self.config.width, self.config.height), zeit, licht);
        }
        // Zeichenreihenfolge (Wasser hinten->vorn, opak vorn->hinten) VOR dem Render-Pass
        // festlegen -- danach haelt render() nur noch geteilte Verweise, s. update_draw_order.
        // Sortiert wird darin nur bei Spaltenwechsel/Mesh-Aenderung, nicht jeden Frame.
        let camera_chunk = (
            (camera.position.x / world::SECTION_SIZE as f64).floor() as i32,
            (camera.position.z / world::SECTION_SIZE as f64).floor() as i32,
        );
        self.block_renderer.update_draw_order(camera_chunk);
        // Durchsichtige Quads nach Abstand umsortieren. Ohne das entscheidet die feste
        // Rasterreihenfolge des Meshers, welche Flaeche oben blendet -- aus einer
        // Blickrichtung zufaellig richtig, aus der Gegenrichtung zwangslaeufig falsch
        // (s. sort_translucent). Ein Block Schwelle -- derselbe Wert, den Vanilla fuer seine
        // Neusortierung der Translucent-Sections nimmt; darunter bemerkt man die Aenderung
        // beim Gehen ohnehin nicht, und jede Neusortierung kostet Buffer-Uploads.
        self.block_renderer.sort_translucent(&self.queue, camera.position, 1.0);
        // Augenrelative Spalten-Versaetze fuer DIESEN Frame (s. update_column_offsets).
        // Muss vor den Render-Pass: dort haelt render() nur noch geteilte Verweise.
        //
        // Bezugspunkt ist das AUGE (camera.position), NICHT die Kameraposition
        // (view_position()): view_matrix() blickt aus render_view_position() == view_offset,
        // im hochgeladenen Raum sitzt die Kamera also bei view_offset und der Ursprung ist
        // das Auge. Genau so laden Entities und Geisterbloecke ihre Geometrie hoch
        // (s. build_entity_vertices/ghost_vertices).
        //
        // ECHTER BUG gewesen: hier stand view_position(). In der Ego-Ansicht ist der
        // Unterschied null (view_offset == 0), in der 3. PERSON aber genau der Kameraversatz
        // -- die ganze Welt war dort gegen alle Entities verschoben. Sichtbar wurde das als
        // Beine, die durch den Boden gingen, weil der Versatz auch eine
        // Hoehenkomponente hat (camera_y_offset). s. camera::bezugspunkt_tests.
        let eye = camera.position;
        self.block_renderer.update_column_offsets(&self.device, &self.queue, eye);
        self.last_sort_ms = work_started.elapsed().as_secs_f32() * 1000.0;
        let frustum = render::Frustum::from_view_proj(camera.cull_view_proj_matrix(aspect));
        self.block_renderer.prepare_terrain_draws(&self.device, &self.queue, &frustum, eye, camera.view_position());

        let screen_px = self.size();
        // Projizierte Text-Displays zuerst (unter dem HUD-Text), hoechstens die Haelfte des
        // Puffers -- der HUD-Text darf nie wegen Hologrammen fehlen.
        // Die Overlay-Ebene zuerst (s. overlay_vertices).
        let ov = self.overlay_vertices(overlay, screen_px);
        let mut text_data: Vec<TextVertex> = std::mem::take(&mut *self.world_label_glyphs.borrow_mut());
        text_data.truncate(MAX_UI_GLYPHS / 2 * VERTS_PER_QUAD);
        let label_len = text_data.len() as u32;
        let mut schriften = self.shape_text(texts, screen_px, &mut text_data);
        // Die Text-Displays vorn in der Schrift des Bereichs Nametags, ab dem HUD-Text wieder
        // in der allgemeinen (die Laeufe von shape_text setzen dort an).
        if let Some(kind) = self.label_font.get().filter(|_| label_len > 0) {
            schriften.splice(0..0, [(0, kind), (label_len, self.font_atlas.kind())]);
        }
        // Schildtext fuer den Welt-Durchgang (s. App::build_sign_texts).
        let sign_len = {
            let glyphen = self.sign_glyphs.borrow();
            if !glyphen.is_empty() {
                self.queue.write_buffer(&self.sign_text_buffer, 0, bytemuck::cast_slice(&glyphen));
            }
            glyphen.len() as u32
        };
        let sign_kind = self.sign_font.get().unwrap_or(self.font_atlas.kind());
        let text_split = append_overlay(&mut text_data, &ov.text, MAX_UI_GLYPHS * VERTS_PER_QUAD);
        if !text_data.is_empty() {
            self.queue.write_buffer(&self.text_vertex_buffer, 0, bytemuck::cast_slice(&text_data));
        }
        // Leer zurueck: so behaelt die Liste ihre Groesse und waechst im naechsten Frame nicht
        // wieder Stueck fuer Stueck (Profiler: realloc beim Bau der Namensschilder).
        let text_len = text_data.len() as u32;
        text_data.clear();
        *self.world_label_glyphs.borrow_mut() = text_data;

        // Fuers F3-Debug-Overlay (Graph-Hintergrund, s. main.rs::build_debug_overlay) --
        // derselbe quad_pipeline/quad_vertex_buffer wie im Menu (render_menu), hier aber
        // NICHT ins Menu, sondern in den Welt-HUD-Durchgang unten gezeichnet.
        //
        // Hintergruende der Text-Displays zuerst (unter allen HUD-Flaechen), gedeckelt auf ein
        // Viertel des Puffers.
        let mut quad_data: Vec<Vertex> = std::mem::take(&mut *self.world_label_quads.borrow_mut());
        quad_data.truncate(MAX_UI_RECTS / 4 * VERTS_PER_QUAD);
        let welt_quads = quad_data.len() / VERTS_PER_QUAD;
        quad_data.reserve(rects.len() * VERTS_PER_QUAD);
        for r in rects.iter().take(MAX_UI_RECTS.saturating_sub(welt_quads)) {
            quad_data.extend_from_slice(&rect_verts(r, screen_px));
        }
        let quad_split = append_overlay(&mut quad_data, &ov.quads, MAX_UI_RECTS * VERTS_PER_QUAD);
        if !quad_data.is_empty() {
            self.queue.write_buffer(&self.quad_vertex_buffer, 0, bytemuck::cast_slice(&quad_data));
        }
        let quad_len = quad_data.len() as u32;
        quad_data.clear();
        *self.world_label_quads.borrow_mut() = quad_data;

        // Liniensegmente der Graphen (UiLine) in einem EIGENEN Puffer -- bei z.B. 16 Kernen *
        // 89 Segmenten sind das leicht ueber 1000 Quads, weit mehr als MAX_UI_RECTS fuer
        // normale UI-Rechtecke vorsieht. Ein gemeinsamer Puffer haette entweder den Menu-
        // Rechteck-Puffer unnoetig aufblasen muessen oder waere bei vielen Kernen ueber die
        // Kapazitaet hinaus beschrieben worden (wgpu-Validierungsfehler).
        // Erst die normalen Linien, dahinter die obersten (top, nach dem Text gezeichnet).
        let mut line_data: Vec<Vertex> = Vec::with_capacity(hud_lines.len() * VERTS_PER_QUAD);
        let mut top_start = None;
        for line in hud_lines.iter().filter(|l| !l.top).chain(hud_lines.iter().filter(|l| l.top)) {
            if line.top && top_start.is_none() {
                top_start = Some(line_data.len() as u32);
            }
            let verts: &[Vertex] = if let Some(q) = line.quad {
                &free_quad_verts_colored(q, line.quad_colors.unwrap_or([line.color; 4]), screen_px)
            } else if line.feather > 0.0 {
                &soft_line_verts(line, screen_px)
            } else {
                &line_quad_verts(line, line.width, screen_px)
            };
            if line_data.len() + verts.len() > MAX_UI_LINE_SEGMENTS * VERTS_PER_QUAD {
                break; // Puffer voll -- Rest weglassen statt ueberlaufen
            }
            line_data.extend_from_slice(verts);
        }
        if !line_data.is_empty() {
            self.queue.write_buffer(&self.line_vertex_buffer, 0, bytemuck::cast_slice(&line_data));
        }
        let line_len = line_data.len() as u32;
        let top_start = top_start.unwrap_or(line_len).min(line_len);
        let draw_top_lines = |pass: &mut wgpu::RenderPass<'_>, pipeline: &wgpu::RenderPipeline, buffer: &wgpu::Buffer| {
            if top_start < line_len {
                pass.set_pipeline(pipeline);
                pass.set_vertex_buffer(0, buffer.slice(..));
                pass.draw(top_start..line_len, 0..1);
            }
        };

        let mut sprite_data: Vec<TextVertex> = Vec::new();
        // Mit Spielerfigur wird die Sprite-Liste GETEILT: alles vor dem Einfuegepunkt (der
        // Fensterhintergrund) kommt in den ersten Durchgang, die Figur dazwischen, der Rest
        // (Item-Symbole, der Stapel an der Maus) danach. shape_sprites haengt beide Male an
        // denselben Vertexpuffer an und rechnet mit absoluten Offsets, die Laeufe passen also
        // ohne Umrechnung zusammen.
        let unter = self.under_sprites.replace(0).min(sprites.len());
        let unter_runs = Self::shape_sprites(&sprites[..unter], screen_px, &mut sprite_data);
        let sprites = &sprites[unter..];
        let doll_split = doll_split.filter(|_| self.block_renderer.has_doll()).map(|k| k.saturating_sub(unter).min(sprites.len()));
        let (sprite_runs, sprite_runs_after) = match doll_split {
            Some(k) => {
                let vorher = Self::shape_sprites(&sprites[..k], screen_px, &mut sprite_data);
                let nachher = Self::shape_sprites(&sprites[k..], screen_px, &mut sprite_data);
                (vorher, Some(nachher))
            }
            None => (Self::shape_sprites(sprites, screen_px, &mut sprite_data), None),
        };
        let sprite_split = append_overlay_sprites(&mut sprite_data, &ov.sprites);
        if !sprite_data.is_empty() {
            self.queue.write_buffer(&self.sprite_vertex_buffer, 0, bytemuck::cast_slice(&sprite_data));
        }
        let sprite_len = sprite_data.len() as u32;

        // Zeigerform als Uniform, kantengeglaettet im Shader (s. cursor.wgsl und render_menu).
        if let Some(pos) = cursor {
            self.queue.write_buffer(&self.cursor_uniform_buffer, 0, bytemuck::bytes_of(&cursor_polygons(pos, screen_px, cursor_fx)));
        }

        let mut encoder = self.device.create_command_encoder(&wgpu::CommandEncoderDescriptor { label: Some("world encoder") });
        if let Some(timer) = self.gpu_timer.as_mut() {
            timer.begin_frame();
        }
        if self.use_shader_path {
            self.render_world_shader_path(&mut encoder, sky, camera);
        } else {
            // Himmel aus Resourcepacks: in die Ansicht ohne sRGB (Mischung im Gamma-Raum, s.
            // render::custom_sky), geloescht mit der Himmelsfarbe in denselben Werten. Alles
            // danach laedt das Bild, statt es zu loeschen.
            let himmel = !self.sky_layers.is_empty();
            if himmel {
                let raw = self.config.format.remove_srgb_suffix();
                let view = self.offscreen_texture.create_view(&wgpu::TextureViewDescriptor { format: Some(raw), ..Default::default() });
                let gamma = |c: f64| if c <= 0.0031308 { c * 12.92 } else { 1.055 * c.powf(1.0 / 2.4) - 0.055 };
                let clear = if raw != self.config.format { wgpu::Color { r: gamma(sky.r), g: gamma(sky.g), b: gamma(sky.b), a: sky.a } } else { sky };
                let rotation = camera.view_rotation();
                let view_proj = camera.proj_matrix(aspect) * rotation;
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("custom sky pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Clear(clear), store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Himmel")),
                    occlusion_query_set: None,
                });
                self.custom_sky.draw(&self.queue, &mut pass, view_proj, &self.sky_layers);
            }
            // Verlaufshimmel (Modul Himmel): statt der Loeschfarbe, ebenfalls vor allem anderen.
            let verlauf = self.sky_gradient.filter(|_| !himmel);
            if let Some(frame) = &verlauf {
                let rotation = camera.view_rotation();
                let view_proj = camera.proj_matrix(aspect) * rotation;
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("gradient sky pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &self.offscreen_view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Clear(sky), store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Himmel")),
                    occlusion_query_set: None,
                });
                self.gradient_sky.draw(&self.queue, &mut pass, view_proj, frame);
            }
            // Fernsicht (Modul Chunk-Saver) zuerst, mit eigener Tiefe; das Gelaende laedt danach
            // das Bild, statt es zu loeschen (s. render::lod_renderer).
            let lod = self.lod.as_ref().filter(|l| self.lod_active && l.has_draws());
            let sky_load = if himmel || verlauf.is_some() { wgpu::LoadOp::Load } else { wgpu::LoadOp::Clear(sky) };
            if let Some(lod) = lod {
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("lod pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &self.offscreen_view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: sky_load, store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: Some(lod.depth_attachment()),
                    timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Fernsicht")),
                    occlusion_query_set: None,
                });
                lod.render(&mut pass);
            }
            let load = if lod.is_some() { wgpu::LoadOp::Load } else { sky_load };
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("world pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &self.offscreen_view,
                    resolve_target: None,
                    ops: wgpu::Operations { load, store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: Some(self.block_renderer.depth_attachment()),
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Welt")),
                occlusion_query_set: None,
            });
            let timer = &mut self.gpu_timer;
            self.block_renderer.render(&mut pass, &mut |pass, label| {
                if let Some(t) = timer.as_mut() {
                    t.mark(pass, label);
                }
            });
            // Schildtext gegen die Tiefe der Welt -- danach, damit davor stehende Entities ihn
            // verdecken (s. world_text_pipeline).
            if sign_len > 0 {
                pass.set_pipeline(&self.world_text_pipeline);
                pass.set_vertex_buffer(0, self.sign_text_buffer.slice(..));
                pass.set_bind_group(0, &self.hud_font(sign_kind).bind_group, &[]);
                pass.draw(0..sign_len, 0..1);
            }
        }

        // Blockumriss in der Gegenfarbe (Modul Blockumriss, Komplementaer): nach der Welt, vor
        // der Hand, gegen die Tiefe der Welt.
        if !self.use_shader_path {
            self.block_renderer.encode_outline_complement(&self.device, &mut encoder, &self.offscreen_texture, &self.offscreen_view);
        }

        // Leucht-Umriss: nach der Welt, vor der Hand -- wie in Vanilla liegt die Hand darueber.
        if self.block_renderer.has_outlines() {
            let raw = self.config.format.remove_srgb_suffix();
            let view = self.offscreen_texture.create_view(&wgpu::TextureViewDescriptor { format: Some(raw), ..Default::default() });
            let size = (self.config.width, self.config.height);
            self.entity_outline.encode(&self.device, &self.queue, &mut encoder, &self.block_renderer, &view, size);
        }

        // Ego-Hand: EIGENER Durchgang mit geleertem Tiefenpuffer und eigener Projektion --
        // genauso wie in Vanilla (GameRenderer: clearDepthTexture, dann renderHand mit
        // getFov(..., false)). Das Leeren ist kein Trick, sondern der Grund, warum die Hand nie
        // in einer Wand verschwindet.
        //
        // Das Sichtfeld ist bewusst NICHT `camera.fov_degrees`: Vanillas Hand haengt am festen
        // Wert 70 und ist von der Einstellung voellig unabhaengig (s. update_hand_camera).
        {
            self.block_renderer.update_hand_camera(&self.queue, aspect);
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("hand pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &self.offscreen_view,
                    resolve_target: None,
                    ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: Some(self.block_renderer.depth_attachment()),
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Hand")),
                occlusion_query_set: None,
            });
            self.block_renderer.render_hand(&mut pass);
        }

        // Overlay in einem zweiten Durchgang: laedt das Bild statt es zu loeschen, und
        // ohne Tiefentest -- der HUD gehoert immer nach vorn, egal was dahinter steht.
        // Quads (Graph-Hintergruende) und Linien (Graph-Kurven) VOR dem Text, damit Text bei
        // Bedarf darueber liegen kann -- exakt dieselbe Grund-Reihenfolge wie im Menu-Pass
        // (render_menu).
        // Der Shader-Pfad hat keinen Welt-Durchgang mit dieser Tiefe: dort liegt der Schildtext
        // ohne Tiefentest unter dem HUD.
        let schilder_im_hud = self.use_shader_path && sign_len > 0;
        if quad_len > 0 || !line_data.is_empty() || text_len > 0 || !sprite_data.is_empty() || cursor.is_some() || schilder_im_hud {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("world hud pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &self.offscreen_view,
                    resolve_target: None,
                    ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: None,
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("HUD")),
                occlusion_query_set: None,
            });
            if schilder_im_hud {
                pass.set_pipeline(&self.text_pipeline);
                pass.set_vertex_buffer(0, self.sign_text_buffer.slice(..));
                pass.set_bind_group(0, &self.hud_font(sign_kind).bind_group, &[]);
                pass.draw(0..sign_len, 0..1);
            }
            if !unter_runs.is_empty() {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                self.draw_sprite_runs(&mut pass, &unter_runs);
            }
            if quad_split > 0 {
                pass.set_pipeline(&self.quad_pipeline);
                pass.set_vertex_buffer(0, self.quad_vertex_buffer.slice(..));
                pass.draw(0..quad_split, 0..1);
            }
            if top_start > 0 {
                pass.set_pipeline(&self.quad_pipeline);
                pass.set_vertex_buffer(0, self.line_vertex_buffer.slice(..));
                pass.draw(0..top_start, 0..1);
            }
            if !sprite_data.is_empty() {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                self.draw_sprite_runs(&mut pass, &sprite_runs);
            }
            // Text und Zeiger nur hier, wenn KEINE Figur dazwischenkommt -- sonst laegen sie
            // hinter ihr (s. den zweiten Durchgang unten).
            if sprite_runs_after.is_none() {
                // Zeiger ganz zuletzt -- er gehoert immer nach vorn (s. render_menu).
                self.draw_ui_top(&mut pass, (text_split, text_len), (quad_split, quad_len), &ov.ranges, (sprite_split, sprite_len), cursor.is_some(), &schriften);
                draw_top_lines(&mut pass, &self.quad_pipeline, &self.line_vertex_buffer);
            }
        }

        // Spielerfigur im Inventar: eigener Durchgang MITTEN im HUD -- vor dem
        // Fensterhintergrund, hinter den Item-Symbolen. Sie ist echte 3D-Geometrie und
        // braucht deshalb einen geleerten Tiefenpuffer (ein Arm vor dem Rumpf muss ihn
        // verdecken), genau wie die Ego-Hand weiter oben.
        if let Some(sprite_runs_after) = sprite_runs_after {
            {
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("inventory doll pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &self.offscreen_view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: Some(self.block_renderer.depth_attachment()),
                    timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Figur")),
                    occlusion_query_set: None,
                });
                self.block_renderer.render_doll(&mut pass);
            }
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("world hud pass (nach der Figur)"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &self.offscreen_view,
                    resolve_target: None,
                    ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: None,
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("HUD")),
                occlusion_query_set: None,
            });
            if !sprite_data.is_empty() {
                pass.set_pipeline(&self.sprite_pipeline);
                pass.set_vertex_buffer(0, self.sprite_vertex_buffer.slice(..));
                self.draw_sprite_runs(&mut pass, &sprite_runs_after);
            }
            self.draw_ui_top(&mut pass, (text_split, text_len), (quad_split, quad_len), &ov.ranges, (sprite_split, sprite_len), cursor.is_some(), &schriften);
            draw_top_lines(&mut pass, &self.quad_pipeline, &self.line_vertex_buffer);
        }

        // offscreen_texture (Welt + HUD-Text, vollstaendig fertig) in die praesentierbare
        // Swapchain-Textur uebertragen -- entweder direkt kopiert (aus, wie bisher) oder erst
        // durch CMAA2 geschickt (an, s. cmaa2.wgsl: Compute-Durchgang schreibt nach
        // cmaa2_output_texture, ein Blit-Durchgang traegt das Ergebnis in die Swapchain ein,
        // weil eine sRGB-Swapchain-Textur nicht direkt per Compute beschreibbar ist).
        let Some((frame, wait_ms)) = acquired else {
            // Hintergrund fuers Menue: abschicken, das Bild holt render_menu gleich selbst.
            self.queue.submit(std::iter::once(encoder.finish()));
            self.keep_world_backdrop();
            self.offscreen_world_only = true;
            return None;
        };
        let view = frame.texture.create_view(&wgpu::TextureViewDescriptor::default());
        if cmaa2_enabled {
            {
                let mut cpass =
                    encoder.begin_compute_pass(&wgpu::ComputePassDescriptor { label: Some("cmaa2 compute"), timestamp_writes: None });
                cpass.set_pipeline(&self.cmaa2_compute_pipeline);
                cpass.set_bind_group(0, &self.cmaa2_compute_bind_group, &[]);
                let wg_x = self.config.width.div_ceil(8);
                let wg_y = self.config.height.div_ceil(8);
                cpass.dispatch_workgroups(wg_x, wg_y, 1);
            }
            {
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("cmaa2 blit pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::BLACK), store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Ausgabe")),
                    occlusion_query_set: None,
                });
                pass.set_pipeline(&self.cmaa2_blit_pipeline);
                pass.set_bind_group(0, &self.cmaa2_blit_bind_group, &[]);
                pass.draw(0..3, 0..1);
            }
        } else if let Some(saturation) = saturation {
            // Statt der Kopie: derselbe Weg durch den Farb-Shader (s. color.wgsl).
            self.queue.write_buffer(&self.color_settings_buffer, 0, bytemuck::cast_slice(&[saturation, 0.0, 0.0, 0.0]));
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("color pass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &view,
                    resolve_target: None,
                    ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::BLACK), store: wgpu::StoreOp::Store },
                })],
                depth_stencil_attachment: None,
                timestamp_writes: self.gpu_timer.as_mut().and_then(|t| t.pass("Ausgabe")),
                occlusion_query_set: None,
            });
            pass.set_pipeline(&self.color_pipeline);
            pass.set_bind_group(0, &self.color_bind_group, &[]);
            pass.draw(0..3, 0..1);
        } else {
            encoder.copy_texture_to_texture(
                wgpu::ImageCopyTexture {
                    texture: &self.offscreen_texture,
                    mip_level: 0,
                    origin: wgpu::Origin3d::ZERO,
                    aspect: wgpu::TextureAspect::All,
                },
                wgpu::ImageCopyTexture {
                    texture: &frame.texture,
                    mip_level: 0,
                    origin: wgpu::Origin3d::ZERO,
                    aspect: wgpu::TextureAspect::All,
                },
                wgpu::Extent3d { width: self.config.width, height: self.config.height, depth_or_array_layers: 1 },
            );
        }

        // Crosshair als LETZTER Schritt, gezeichnet in die Swapchain-Textur (Load, nach dem
        // Blit oben) -- sampelt dabei offscreen_view (eine ANDERE Ressource als das
        // Render-Target dieser Pass, s. crosshair_vertices-Kommentar: dieselbe Textur
        // gleichzeitig lesen und beschreiben ist nicht erlaubt).
        let mut crosshair_data = Vec::new();
        if let Some(center) = crosshair_center {
            // Auf ganze Pixel gerundet -- s. crosshair_outline_rects: Kreuz und Kontur
            // muessen exakt dasselbe Raster treffen, sonst sieht der Rand einseitig aus.
            let crosshair_px = ((center.0 * screen_px.0).round(), (center.1 * screen_px.1).round());
            crosshair_data = match &crosshair_extras.custom {
                Some(c) => custom_crosshair_vertices(c, crosshair_px, screen_px),
                None => {
                    let size = if crosshair_extras.size == 0 { CROSSHAIR_SHAPES[0].3 } else { crosshair_extras.size };
                    crosshair_vertices(crosshair_extras.shape, size, crosshair_px, screen_px, crosshair_outline)
                }
            };
        }
        if let Some((mitte, anteil)) = crosshair_extras.ring {
            // Um die Mitte des Kreuzes, wie es gerade steht (auch beim Wackeln der Pfeil-Anzeige).
            let mitte = crosshair_center.unwrap_or(mitte);
            let versatz = if crosshair_extras.custom.is_some() {
                0.0
            } else {
                let size = if crosshair_extras.size == 0 { CROSSHAIR_SHAPES[0].3 } else { crosshair_extras.size };
                crosshair_center_offset(crosshair_extras.shape, size)
            };
            let mitte_px = ((mitte.0 * screen_px.0).round() + versatz, (mitte.1 * screen_px.1).round() + versatz);
            crosshair_data.extend(crosshair_ring_vertices(mitte_px, anteil, screen_px, crosshair_extras.ring_outline));
        }
        // Die Texte nach Schrift gruppiert: je Schrift ein Zeichenaufruf mit ihrer
        // Glyphen-Bindung (Gruppe 1). Kreuz und Kreis davor brauchen keine.
        let main_count = crosshair_data.len() as u32;
        let mut schrift_laeufe: Vec<(FontKind, std::ops::Range<u32>)> = Vec::new();
        for kind in FontKind::ALL {
            let von = crosshair_data.len();
            for text in crosshair_extras.texts.iter().filter(|t| t.font == kind) {
                crosshair_data.extend(self.crosshair_glyph_vertices(self.hud_font(kind), text, crosshair_outline, screen_px));
            }
            crosshair_data.truncate(CROSSHAIR_MAX_VERTICES);
            if crosshair_data.len() > von {
                schrift_laeufe.push((kind, von as u32..crosshair_data.len() as u32));
            }
        }
        if !crosshair_data.is_empty() {
            self.queue.write_buffer(&self.crosshair_vertex_buffer, 0, bytemuck::cast_slice(&crosshair_data));
            // Reihenfolge/Groesse exakt wie crosshair.wgsl::CrosshairSettings.
            let byte = |c: f32| (c.clamp(0.0, 1.0) * 255.0).round() as u32;
            let farbe = byte(crosshair_rgb[0]) | byte(crosshair_rgb[1]) << 8 | byte(crosshair_rgb[2]) << 16 | 0xff << 24;
            // Viertes Feld: Brenn-Farbe fuer Kreuz und Ring, Alpha 0 = brennt nicht.
            let feuer = crosshair_extras.fire_rgb.map_or(0, |c| byte(c[0]) | byte(c[1]) << 8 | byte(c[2]) << 16 | 0xff << 24);
            let crosshair_settings: [u32; 4] = [crosshair_mode, crosshair_boost.to_bits(), farbe, feuer];
            self.queue.write_buffer(&self.crosshair_mode_buffer, 0, bytemuck::bytes_of(&crosshair_settings));
            {
                let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                    label: Some("crosshair pass"),
                    color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                        view: &view,
                        resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store },
                    })],
                    depth_stencil_attachment: None,
                    timestamp_writes: None,
                    occlusion_query_set: None,
                });
                pass.set_pipeline(&self.crosshair_pipeline);
                pass.set_bind_group(0, &self.crosshair_bind_group, &[]);
                pass.set_bind_group(1, &self.font_atlas.bind_group, &[]);
                pass.set_vertex_buffer(0, self.crosshair_vertex_buffer.slice(..));
                pass.draw(0..main_count, 0..1);
                for (kind, laeufe) in schrift_laeufe {
                    pass.set_bind_group(1, &self.hud_font(kind).bind_group, &[]);
                    pass.draw(laeufe, 0..1);
                }
            }
        }

        // Das fertige Weltbild bleibt in offscreen_view stehen -- es dient den Menues als
        // Hintergrund, sobald man Esc drueckt (s. world_backdrop).
        self.keep_world_backdrop();
        self.offscreen_world_only = false;
        Some(self.submit_and_present(encoder, frame, wait_ms, work_started))
    }
}

// Aufschluesselung eines Frames in Wartezeit (get_current_texture(), bei Fifo bis zum
// VBlank) und tatsaechliche Arbeit (Vertex-Aufbau, Encoding, Submit). Ohne diese Trennung
// waere die Wartezeit als "Arbeit" ausgewiesen -- irrefuehrend gerade bei Fifo, wo sie den
// groessten Teil der gemessenen Zeit ausmacht.
struct FrameTiming {
    // Gewartet statt gearbeitet: auf das vorige Frame der GPU (Zero-Modus), aufs Swapchain-Bild,
    // auf den Termin der Riss-Steuerung, auf das Present (s. FrameStats).
    idle_ms: f32,
    // Aufschluesselung fuer den Frame-Profiler: Aufbau/Encoding bis vor dem Submit, das
    // Submit selbst und das Present (s. GpuState::submit_and_present).
    encode_ms: f32,
    submit_ms: f32,
    present_ms: f32,
    // Zeitpunkte (CLOCK_MONOTONIC, ns, s. vblank::monotonic_ns) fuer die Phasenmessung des
    // Profilers: Present-Aufruf und -- nur mit GpuState::measure_gpu_done -- GPU fertig.
    present_ns: i64,
    gpu_done_ns: Option<i64>,
    // Nur mit Riss-Steuerung: wann Frame und GPU fertig waren, bevor auf den Termin gewartet
    // wurde (fuer den Vorlauf, s. App::tear_lead_ns).
    ready_ns: Option<i64>,
}

// Die TAGFARBE des Himmels im ANZEIGE-Raum (sRGB). Frueher stand hier die fertige lineare
// Clear-Farbe; seit der Himmel der Tageszeit folgt (s. world::sky), wird im Anzeige-Raum
// gerechnet und erst am Ende umgerechnet -- ein Faktor auf lineare Werte wuerde die
// Daemmerung falsch abdunkeln, weil die Helligkeitskurve fuer das Auge gilt, nicht fuer die
// Leistung.
const SKY_DAY_SRGB: [f32; 3] = [0.45, 0.65, 0.95];

// Gleichmaessige Helligkeit fuer Entity-Modelle. Dieser Client fuehrt (noch) kein
// Entity-Licht -- Vanilla nimmt den Lichtwert am Entity-Block plus die Zwei-Licht-Diffusion
// der Flaechennormalen. Ein fester, leicht abgedunkelter Wert sieht neben den (per Richtung
// schattierten) Bloecken plausibel aus, ohne Licht zu erfinden, das wir nicht kennen.
// Grundfarbe der Entity-Modelle, BEVOR das Richtungslicht draufkommt (s.
// world::diffuse_shade). Vanilla startet dort bei Weiss und multipliziert mit dem Licht, die
// Flaechen liegen damit zwischen 0.4 und 1.0.
//
// Vorher stand hier 0.9 als flache Ersatzhelligkeit fuer "wir haben kein Licht" -- mit echter
// Schattierung wuerde das alles um 10 % zu dunkel machen.
//
// Eine Lichtkarte gibt es hier bewusst NICHT. Vanilla multipliziert zusaetzlich mit dem
// Block-/Himmelslicht am Standort des Entities; dieser Client wertet Lichtdaten ueberhaupt
// nicht aus -- weder fuer Bloecke noch fuer Entities -- und rendert damit durchgaengig
// fullbright. Das ist eine Entscheidung, keine Luecke: fuer PvP ist
// dauerhaftes Fullbright gewollt, und Entities passen so zum Rest der Welt statt in einer
// dunklen Hoehle als einzige Objekte abzudunkeln.
// Vanillas Schwungdauer fuer Spieler (LivingEntity.getHandSwingDuration ueber die
// Swing-Animation des Items -- 6 Ticks fuer die Standardwaffe).
// Entscheidet fuer EINEN Tick, wie viele Benutzungen ausgeloest werden und wie der Cooldown
// danach steht. Als freie Funktion, damit die Regel ohne laufendes Fenster pruefbar ist --
// sie ist der ganze Unterschied zwischen "Klicks gehen verloren" und nicht.
//
// Rueckgabe: (Anzahl Benutzungen in diesem Tick, neuer Cooldown).
//
// Das bildet Vanillas handleKeybinds 1:1 ab:
//
//     while (useKey.wasPressed()) doItemUse();                       // ALLE gemerkten Klicks
//     if (useKey.isPressed() && itemUseCooldown == 0 && !isUsingItem()) doItemUse();
//
// ALLE gemerkten Klicks feuern also im SELBEN Tick, nicht einer pro Tick. Frueher stand hier
// genau das (einer pro Tick), und das kostete den Anchor-Airplace: der braucht zwei Klicks in
// einem Tick, damit beide dieselbe Zielposition tragen (s. tick_item_use).
//
// Reihenfolge wie in Vanilla: erst laeuft der Cooldown herunter, dann wird entschieden.
//
// `repeat` ist der Schalter aus den Einstellungen (s. Settings::hold_use_repeat). Er wirkt NUR
// auf das Halten, nie auf gemerkte Klicks: wer viermal klickt, will auch viermal setzen --
// abgeschaltet wird das WIEDERHOLEN, nicht das Puffern.
fn item_uses_this_tick(queue: u32, cooldown: u32, held: bool, repeat: bool) -> (u32, u32) {
    let cooldown = cooldown.saturating_sub(1);
    if queue > 0 {
        // Gemerkte Klicks zaehlen IMMER, auch waehrend des Cooldowns -- Vanillas doItemUse
        // prueft ihn ebenfalls nicht, es setzt ihn nur.
        return (queue, ITEM_USE_COOLDOWN_TICKS);
    }
    if held && repeat && cooldown == 0 {
        return (1, ITEM_USE_COOLDOWN_TICKS);
    }
    (0, cooldown)
}

// Items, deren `use` schon im Client ein Stueck verbraucht (s. App::consume_hand_item).
const THROWN_ITEMS: [&str; 9] =
    ["splash_potion", "lingering_potion", "snowball", "egg", "blue_egg", "brown_egg", "ender_pearl", "experience_bottle", "wind_charge"];

// MinecraftClient.itemUseCooldown: 4 Ticks zwischen zwei Benutzungen bei GEHALTENER Taste.
const ITEM_USE_COOLDOWN_TICKS: u32 = 4;
// Grundwerte der Attribute block_interaction_range (4.5) und entity_interaction_range (3.0),
// bis der Server andere schickt (s. App::attr_block_range). Zwei verschiedene Zahlen, das ist
// kein Versehen.
const BLOCK_INTERACTION_REACH: f64 = 4.5;
const ENTITY_INTERACTION_REACH: f64 = 3.0;
const PLAYER_SWING_TICKS: u32 = 6;

// Schwungfortschritt aus dem rueckwaerts laufenden Zaehler (s. App::own_swing_ticks).
// PLAYER_SWING_TICKS + 1 heisst "angestossen, noch nicht getickt" (Vanillas handSwingTicks =
// -1): noch kein Ausschlag. Wird der Schwung im Tick VOR dem Herunterzaehlen gesetzt, steht der
// Zaehler danach auf PLAYER_SWING_TICKS und der erste Frame beginnt bei 0 -- ohne diese
// Stufe sprang das Item beim Schlag gleich ein bis zwei Sechstel weit.
// Deckel bei 1: dort steht das Item wieder in Ruhelage (alle Sinusanteile sind 0); dahinter
// kippen die Formeln und das Item stand fuer einige Frames weit hinten.
// `dauer`: Schwungdauer des Haupthand-Items (Speere laenger, s. App::own_swing_duration).
fn swing_progress_from_ticks(ticks: u32, tick_progress: f32, dauer: u32) -> f32 {
    if ticks == 0 || ticks > dauer {
        return 0.0;
    }
    ((dauer - ticks) as f32 + tick_progress).min(dauer as f32) / dauer as f32
}

// Neuer Schwung -- aber wie Vanillas LivingEntity.swingHand nur, wenn gerade keiner laeuft,
// der laufende schon mindestens die halbe Dauer hinter sich hat oder eben erst angestossen
// ist (handSwingTicks < 0). Beim Abbauen schwingt der Arm JEDEN Tick; ohne diese Regel fing
// der Schwung jeden Tick von vorn an und die Spitzhacke sprang staendig zurueck.
fn restart_swing(ticks: u32, dauer: u32) -> u32 {
    let vergangen = dauer as i32 - ticks as i32;
    if ticks == 0 || vergangen >= dauer as i32 / 2 || vergangen < 0 {
        dauer + 1
    } else {
        ticks
    }
}

const ENTITY_BRIGHTNESS: f32 = 1.0;

// Fallback-Cap, falls die Refresh-Rate des Monitors nicht ermittelt werden kann.
const FALLBACK_FRAME_INTERVAL: Duration = Duration::from_millis(16);

// Radiant pro Pixel Maus-Delta -- willkuerlich gewaehlt, bei Bedarf anpassen.
// Consumable-Optimizer, Durchdruecken: Obergrenze und Schritt in Millisekunden (ein Tick).
const EAT_HOLD_THROUGH_MAX: u32 = 500;
const EAT_HOLD_THROUGH_STEP: u32 = 50;
// Zoom-Modul (s. ModuleId::Zoom): Staerke in Zehnteln (Sichtfeld geteilt durch), Faktor auf
// die Maus-Empfindlichkeit in Prozent, und wie schnell der Zoom ein- und ausfaehrt
// (Zeitkonstante der Annaeherung).
const ZOOM_FACTOR_MIN: u32 = 15;
const ZOOM_FACTOR_MAX: u32 = 150;
const ZOOM_FACTOR_STEP: u32 = 5;
// Modul "Farbe": Saettigung in Prozent, in Zehnerschritten bis zur doppelten.
const COLOR_SATURATION_MAX: u32 = 200;
const COLOR_SATURATION_STEP: u32 = 10;
const ZOOM_SENS_MIN: u32 = 5;
const ZOOM_SENS_MAX: u32 = 200;
const ZOOM_SENS_STEP: u32 = 5;
const ZOOM_SMOOTH_SECS: f32 = 0.04;

// Sichtfeld und Maus-Faktor bei Zoom-Anteil `amount` (0 = aus, 1 = voll). Das Sichtfeld
// schrumpft geometrisch (fov / Staerke^amount), damit das Einfahren gleichmaessig wirkt
// statt am Ende zu springen.
fn zoomed_fov(fov: f32, factor_tenths: u32, amount: f32) -> f32 {
    fov / (factor_tenths as f32 / 10.0).powf(amount)
}

fn zoom_sens_factor(sens_percent: u32, amount: f32) -> f32 {
    1.0 + (sens_percent as f32 / 100.0 - 1.0) * amount
}

// Sens-Rechner (s. MenuScreen::SettingsSensCalc): Zeilen und DPI-Grenzen.
const SENS_CALC_MC_ROW: usize = 0;
const SENS_CALC_RESULT_ROW: usize = 1;
const SENS_CALC_DPI_ROW: usize = 3;
const SENS_CALC_CM_MC_ROW: usize = 4;
const SENS_CALC_CM_OWN_ROW: usize = 5;
const SENS_CALC_DPI_MIN: u32 = 50;
const SENS_CALC_DPI_MAX: u32 = 64_000;

// Minecraft-Empfindlichkeit (Optionen-Regler in Prozent, 0..200, 100 % = 0,5) in unsere
// Einheit (Radiant je Maus-Zaehler). Vanilla (Mouse.updateMouse):
//     d = sens * 0.6 + 0.2;  e = d^3 * 8;  yaw += dx * e * 0.15  (Grad)
fn minecraft_sens_to_client(percent: f32) -> f32 {
    let d = (percent / 200.0) * 0.6 + 0.2;
    (d * d * d * 8.0 * 0.15).to_radians()
}

// Mauswege fuer eine volle Drehung, in cm: 360 Grad geteilt durch Grad je Zaehler ergibt die
// Zaehler, geteilt durch DPI die Zoll.
fn cm_per_360(sens_rad: f32, dpi: u32) -> f32 {
    360.0 / sens_rad.to_degrees() / dpi as f32 * 2.54
}

const DEFAULT_MOUSE_SENSITIVITY: f32 = 0.0025;
const SENSITIVITY_MIN: f32 = 0.0005;
const SENSITIVITY_MAX: f32 = 0.0100;
const SENSITIVITY_STEP: f32 = 0.0005;

// Empfindlichkeit des MAUSZEIGERS in den Menues/Overlays -- ein reiner Faktor auf das rohe
// Pixel-Delta (1.0 = der Zeiger legt genau so viele Bildschirmpixel zurueck wie die Maus
// meldet). Bewusst eine eigene Einstellung und nicht dieselbe wie fuer die Kamera: die eine
// ist Radiant pro Pixel und haengt am Sichtfeld, die andere ist ein Pixel-zu-Pixel-Verhaeltnis
// und haengt an der Bildschirmgroesse. Ein gemeinsamer Regler zwingt einen, den einen Wert
// schlecht einzustellen, damit der andere passt.
const DEFAULT_CURSOR_SENSITIVITY: f32 = 1.0;
const CURSOR_SENSITIVITY_MIN: f32 = 0.05;
const CURSOR_SENSITIVITY_MAX: f32 = 5.0;
const CURSOR_SENSITIVITY_STEP: f32 = 0.05;

// Anzeigewert der Kamera-Empfindlichkeit (das Tausendfache des internen Radiant/Pixel-Werts).
// VIER Nachkommastellen: der Stepper springt in 0.5er-Schritten, wer feiner zielen will, tippt
// die Zahl direkt ein -- und dabei soll auch die vierte Stelle stehen bleiben statt gerundet
// zu werden. Mit nur zweien wurde eine eingegebene 1.2345 als "1.23" angezeigt: der Wert war
// korrekt uebernommen, sah aber aus, als haette das Feld die Eingabe verworfen (genau dieselbe
// Verwirrung gab es vorher schon mit einer einzigen Stelle). Nachlaufende Nullen fallen weg,
// damit die Stepper-Werte weiter als "2.5" und nicht als "2.5000" dastehen.
fn format_sensitivity(sensitivity: f32) -> String {
    trimme_nullen(format!("{:.4}", sensitivity * 1000.0))
}

// Anzeigewert der Zeiger-Empfindlichkeit -- derselbe Zuschnitt, aber ohne den 1000er-Faktor:
// der Wert IST schon der Faktor, den man einstellt.
// Ein Stepper-Schritt der jeweiligen Empfindlichkeit, inklusive Klemmen. Als eigene
// Funktionen, damit Schrittweite und Grenzen pruefbar sind, ohne eine ganze App aufzubauen --
// und damit die beiden Regler nachweislich getrennt bleiben.
fn step_sensitivity(aktuell: f32, hoch: bool) -> f32 {
    let schritt = if hoch { SENSITIVITY_STEP } else { -SENSITIVITY_STEP };
    (aktuell + schritt).clamp(SENSITIVITY_MIN, SENSITIVITY_MAX)
}

fn step_cursor_sensitivity(aktuell: f32, hoch: bool) -> f32 {
    let schritt = if hoch { CURSOR_SENSITIVITY_STEP } else { -CURSOR_SENSITIVITY_STEP };
    (aktuell + schritt).clamp(CURSOR_SENSITIVITY_MIN, CURSOR_SENSITIVITY_MAX)
}

fn format_cursor_sensitivity(faktor: f32) -> String {
    trimme_nullen(format!("{faktor:.4}"))
}

fn trimme_nullen(text: String) -> String {
    if text.contains('.') {
        text.trim_end_matches('0').trim_end_matches('.').to_string()
    } else {
        text
    }
}

