// Master-Tonhoehe fuer UI-Klaenge aus Aufnahmen (s. Settings::ui_pitch_semitones). Bewusst
// OHNE Ober-/Untergrenze -- audio::CueSink::play_sample klemmt den Faktor selbst auf ein
// numerisches Minimum (1e-3, gegen Division durch null), eine kreative Obergrenze darueber
// waere nur eine erfundene Einschraenkung ohne technischen Grund.
const UI_PITCH_TOOLTIP: &str =
    "Verschiebt die Tonhöhe der UI-Klänge, die aus Aufnahmen abgespielt werden (s. UiSound::sample). In Halbtönen, nach oben und unten offen; Tonhöhe und Länge hängen dabei zusammen, wie bei einer schneller/langsamer abgespielten Aufnahme -- genau wie in scripts/klaenge-anhoeren.sh. Wirkt NICHT auf Signaltöne wie den Totem-Pop.";

// "+3", "-5", "0" -- ein Vorzeichen nur bei einer Abweichung von null, damit nicht jeder
// Wert ein "+0" oder redundantes "-0" zeigt.
fn format_ui_pitch(halbtoene: i32) -> String {
    match halbtoene.cmp(&0) {
        std::cmp::Ordering::Greater => format!("+{halbtoene}"),
        _ => halbtoene.to_string(),
    }
}

// Erklaert, was man hoeren soll -- und was nicht. Ohne den letzten Satz wuerde die fehlende
// Vorne/Hinten-Unterscheidung fuer einen Fehler gehalten, obwohl sie eine bewusste Grenze des
// Modells ist (s. audio::spatial-Modulkommentar).
// Fest verdrahtet und NICHT der eingestellte Tippton: der Hoertest soll immer dasselbe
// Messsignal spielen, sonst misst man beim Vergleichen zweier Geraete zwei verschiedene Dinge.
const ORBIT_TEST_SOUND: &str = "kenney-interface/click_001";

const MASTER_VOLUME_TOOLTIP: &str =
    "Lautstärke aller Weltgeräusche (Schritte, Blöcke, Kreaturen, Explosionen), die der Server schickt. Wirkt bewusst NICHT auf die Klänge der Oberfläche -- die haben ihren eigenen, aufeinander abgestimmten Pegel.";

const SPATIAL_TEST_TOOLTIP: &str =
    "Lässt einen Klick in drei Sekunden einmal um den Kopf wandern: vorne, rechts, hinten, links. Damit lässt sich prüfen, ob die Ortung ankommt -- der Klick erreicht das nahe Ohr bis zu 0,66 ms früher und das ferne leiser und dumpfer. Am deutlichsten mit KOPFHÖRERN; über Lautsprecher hört man vor allem die Lautstärke. Vorne und hinten klingen gleich, das ist so gewollt (dafür bräuchte es gemessene Ohrmuschel-Daten).";

// Slider-Tick (UiSound::Slider): so viele Halbtoene steigt er von links nach rechts ueber die
// ganze Bahn -- wie im Sound-Baukasten eingestellt.
const SLIDER_TICK_RISE_SEMITONES: f32 = 5.5;

// Deterministischer Pseudozufallswert in -1..1 aus einem fortlaufenden Seed -- derselbe
// xorshift-Multiply-Ansatz wie audio::Cue::varied, damit zwei aufeinanderfolgende Tipptoene
// nicht denselben "zufaelligen" Wert bekommen.
fn zufallswert(seed: u32) -> f32 {
    let mut x = seed.wrapping_mul(2_654_435_761);
    x ^= x >> 13;
    x = x.wrapping_mul(1_274_126_177);
    ((x >> 8) as f32 / 8_388_608.0) - 1.0
}

// FPS-Limit: intern der Wert in Hz, NICHT (mehr) ein Index in eine feste Liste -- seit man
// die Zahl anklicken und frei eintippen kann, muss jeder Wert darstellbar sein (90, 165, 165
// standen nie in der Liste). Werte UEBER der Monitor-Refreshrate sind nicht sinnlos: wir
// praesentieren mit PresentMode::Immediate, also ohne auf den VBlank zu warten. Oefter zu
// rendern heisst dann, dass der Monitor beim Auslesen frischere Daten vorfindet -- weniger
// Latenz, dafuer Tearing und mehr Stromverbrauch.
//
// Zwei Sonderwerte, bewusst an den numerischen Enden, damit die Pfeiltasten ohne Sonderfall
// einfach auf-/absteigend durch FPS_LIMIT_STEPS laufen koennen:
const FPS_LIMIT_MONITOR: u32 = 0; // dem Monitor folgen (Standard)
const FPS_LIMIT_UNLIMITED: u32 = u32::MAX; // gar kein Deckel -- per "-1" eingebbar
                                           // Voreinstellungen, durch die die Pfeile schrittweise laufen. Ein frei getippter
                                           // Zwischenwert (z.B. 90) ist voellig erlaubt; der naechste Pfeilklick springt dann auf die
                                           // naechste Stufe darueber bzw. darunter.
const FPS_LIMIT_STEPS: [u32; 8] = [FPS_LIMIT_MONITOR, 30, 60, 75, 120, 144, 240, FPS_LIMIT_UNLIMITED];
// Rechtes Ende des Reglers (getippte Werte bleiben, wie sie sind).
const FPS_LIMIT_TYPED_MAX: u32 = 10_000;
// Die frueher hier stehende Liste, in der settings.conf nur der INDEX gespeichert wurde --
// wird beim Laden einer alten Datei noch gebraucht, um daraus den echten Hz-Wert zu machen
// (s. Settings::parse, Schluessel "fps_limit"). Neue Dateien schreiben "fps_limit_hz".
const LEGACY_FPS_LIMIT_OPTIONS: [Option<u32>; 7] = [None, Some(30), Some(60), Some(75), Some(120), Some(144), Some(240)];

fn fps_limit_label(value: u32) -> String {
    match value {
        FPS_LIMIT_MONITOR => "Monitor".to_string(),
        FPS_LIMIT_UNLIMITED => "unbegrenzt".to_string(),
        v => format!("{v}"),
    }
}

// Die naechste Stufe ueber bzw. unter `value` -- None, wenn es in die Richtung keine mehr
// gibt (dann blendet der jeweilige Pfeil ab). Weil die beiden Sonderwerte numerisch die
// Enden bilden, reicht ein schlichter Groessenvergleich.
fn fps_limit_step(value: u32, up: bool) -> Option<u32> {
    if up {
        FPS_LIMIT_STEPS.iter().copied().find(|&s| s > value)
    } else {
        FPS_LIMIT_STEPS.iter().copied().rev().find(|&s| s < value)
    }
}

// CPU-Render-Ahead-Limit. 1..4 setzen wgpu::SurfaceConfiguration::desired_maximum_frame_
// latency direkt (die Swapchain entscheidet, clamped bei Bedarf selbst). 0 ist ein Sonderfall
// (Sodiums "CPU Render-Ahead Limit: 0 frame(s)"-Nachbau, s. GpuState::fence_wait_zero): laut
// wgpu-Doku wird eine 0 im Swapchain-Parameter selbst "generally not supported and always
// clamped to a higher value" -- deshalb bekommt die Swapchain dabei weiterhin 1, und die
// eigentliche Drosselung passiert per expliziter Fence-Wait (device.poll(WaitForSubmission
// Index)) am Anfang jedes Frames, bevor das naechste ueberhaupt anfaengt. Obergrenze 4
// grosszuegig ueber den ueblichen Treiber-Standardwerten (meist 2-3) fuer den seltenen Fall,
// dass ein hoeherer Wert Ruckler unter Last glaettet -- Latenz-Kosten sind dem Nutzer per
// Tooltip klar gemacht.
const FRAME_LATENCY_MIN: u32 = 0;
const FRAME_LATENCY_MAX: u32 = 4;
// Knapp unter 90 Grad, um Gimbal-Flip beim senkrechten Blick zu vermeiden.
const MAX_PITCH: f32 = 89.0; // Grad -- s. camera.rs, Kamera speichert jetzt in Grad statt Radiant

// Historisch die Job-Vergabe pro Frame gedeckelt (s. Settings::mesh_columns_per_frame) --
// bewusst NICHT mehr fuer diesen Zweck genutzt (s. App::mesh_pending_columns-Kommentar):
// Konstanten bleiben nur noch fuer den Wertebereich der (weiterhin sichtbaren, aber
// wirkungslosen) Settings-Zeile stehen.
const DEFAULT_MESH_COLUMNS_PER_FRAME: usize = 6;
const MESH_COLUMNS_MAX: usize = 32;

// Client-seitige Render-Limiter (s. App::enforce_render_limits) -- zusaetzlich zu, nicht
// statt protocol::REQUESTED_VIEW_DISTANCE: der Server schickt weiterhin bis zu 32 Chunks
// Sichtweite, diese beiden Regler entscheiden nur, wie viele davon TATSAECHLICH GEMESHT UND
// GEZEICHNET werden (Block-Daten bleiben trotzdem geladen, kein Loch in der Welt, wenn man
// sich wieder naehert).
// Obergrenze der Distanz = REQUESTED_VIEW_DISTANCE: mehr zu erlauben waere wirkungslos, der
// Server liefert ohnehin nicht mehr.
const MAX_RENDER_DISTANCE_MIN: u32 = 1;
const MAX_RENDER_DISTANCE_MAX: u32 = protocol::packets::REQUESTED_VIEW_DISTANCE as u32;

// Worker-Anzahl fuer den dedizierten Mesh-Pool (s. mesh_pool::MeshPool) -- Obergrenze
// grosszuegig ueber ueblichen Kernzahlen, Standard an die tatsaechliche CPU angelehnt statt
// eine feste Zahl zu raten.
const CHUNK_UPDATE_THREADS_MIN: usize = 1;
const CHUNK_UPDATE_THREADS_MAX: usize = 32;
fn default_chunk_update_threads() -> usize {
    std::thread::available_parallelism().map(|n| n.get()).unwrap_or(4).clamp(CHUNK_UPDATE_THREADS_MIN, CHUNK_UPDATE_THREADS_MAX)
}

// Frame-Metrik ueber ein gleitendes Ein-Sekunden-Fenster.
//
// Die Bildrate allein sagt bei diesem Client wenig: die Frames sind gedeckelt (s.
// next_frame_time), sie klebt also im Normalfall am Limit und verraet nichts ueber die Reserve.
// Aussagekraeftig ist die ARBEITSZEIT pro Frame -- und davon das Maximum, weil einzelne
// Ausreisser (z.B. Meshing, ein Back-Schritt) im Mittelwert untergehen, auf dem Bildschirm
// aber als Ruckler ankommen.
//
// Arbeit ist das Laengere von CPU und GPU, denn beide laufen nebeneinander und die langsamere
// gibt den Takt vor:
// - CPU: die ganze Zeit seit dem vorigen Frame -- Schleife (Pakete, Meshing, Ticks),
//   Frame-Aufbau, Encoding -- ohne Schlafen bis zum naechsten Termin und ohne Warten auf
//   GPU, Swapchain oder Riss-Termin. Frueher zaehlte nur das Encoding: Meshing im selben
//   Frame liess das Bild ausfallen, ohne dass die Anzeige ausschlug.
// - GPU: Zeitstempel vom ersten bis zum letzten Pass, das Backen der Lichtkarten
//   eingeschlossen (s. gpu_timer). Die CPU sieht davon im Zero-Modus nur, was ueber ihren
//   Schlaf hinausgeht -- 10 ms GPU bei 3 ms CPU erschienen dort als 7,7 ms.
#[derive(Default)]
struct FrameStats {
    samples: VecDeque<(Instant, f32)>,
    // GPU-Zeiten, ein, zwei Frames spaeter eingetroffen (s. record_gpu).
    gpu: VecDeque<(Instant, f32)>,
    last_frame: Option<Instant>,
    // Seit dem letzten Frame verschlafen (s. App::loop_idle_since).
    slept_ms: f32,
}

impl FrameStats {
    fn sleep(&mut self, ms: f32) {
        self.slept_ms += ms;
    }

    // Am Ende eines gezeigten Frames, mit der Wartezeit darin (s. FrameTiming::idle_ms).
    fn record(&mut self, now: Instant, idle_ms: f32) {
        let cpu_ms = match self.last_frame {
            Some(last) => (now.duration_since(last).as_secs_f32() * 1000.0 - self.slept_ms - idle_ms).max(0.0),
            None => 0.0,
        };
        self.last_frame = Some(now);
        self.slept_ms = 0.0;
        self.samples.push_back((now, cpu_ms));
        Self::trim(&mut self.samples, now);
    }

    fn record_gpu(&mut self, now: Instant, ms: f32) {
        self.gpu.push_back((now, ms));
        Self::trim(&mut self.gpu, now);
    }

    fn trim(samples: &mut VecDeque<(Instant, f32)>, now: Instant) {
        while samples.front().is_some_and(|&(t, _)| now.duration_since(t) > HUD_PERF_WINDOW) {
            samples.pop_front();
        }
    }

    // Frames je Sekunde, aus dem halben Sekunde langen Fenster hochgerechnet.
    fn fps(&self) -> usize {
        (self.samples.len() as f32 / HUD_PERF_WINDOW.as_secs_f32()).round() as usize
    }

    fn max_ms(&self) -> f32 {
        self.samples.iter().chain(&self.gpu).map(|&(_, ms)| ms).fold(0.0, f32::max)
    }
}

// Wie FrameStats, aber ohne Wert pro Sample -- zaehlt nur, wie viele Entity-Positions-
// Pakete (Move Entity Pos[/Rot], Entity Position Sync, Teleport Entity) im letzten
// HUD_WINDOW (1s) angekommen sind. Fuer die F3-Frage "kommen die wirklich mit 20 Hz an,
// oder wirkt das nur durch die (inzwischen entfernte) Interpolation glatter als es ist".
#[derive(Default)]
struct EntityUpdateStats {
    samples: VecDeque<Instant>,
}

impl EntityUpdateStats {
    fn record(&mut self, now: Instant) {
        self.samples.push_back(now);
        while self.samples.front().is_some_and(|&t| now.duration_since(t) > HUD_WINDOW) {
            self.samples.pop_front();
        }
    }

    fn per_second(&self) -> usize {
        self.samples.len()
    }
}

// Ergebnis des letzten automatischen Speicherns. Wird dauerhaft angezeigt: ein
// fehlgeschlagenes Speichern darf nicht unbemerkt bleiben, sonst sind die Einstellungen
// beim naechsten Start still wieder weg.
enum SaveStatus {
    Saved,
    Failed(String),
}

// Welcher Menue-Screen gerade sichtbar ist. Main ist zweigeteilt (s. build_menu_ui):
// getrennt -> Startbildschirm (Verbinden/Einstellungen), verbunden -> Esc-Pausemenue
// (HUD-Editor/Disconnect/Einstellungen). Settings/HudEditor sind Unterscreens mit
// Zurueck-Navigation.
#[derive(Clone, Copy, PartialEq, Eq)]
enum MenuScreen {
    Main,
    // Verbindungs-Screen: erst hier erscheint die Adress-Eingabe. Vom Startbildschirm
    // ueber "Verbinden" erreichbar; "Los" startet die Verbindung und springt sofort in
    // die 3D-Ansicht (das Overlay dort zeigt die Connect-Phase, s. build_connecting_overlay).
    Connect,
    // Konto-Verwaltung (eigener Screen statt eingequetscht auf dem Connect-Screen): Microsoft-
    // Login, Refresh-Token, manuelles Token, Abmelden.
    Account,
    // Settings ist die Kategorie-Auswahl (nur Kacheln, s. build_settings_hub) -- die
    // eigentlichen Zeilen stecken in den Unterscreens darunter. SettingsGeneral traegt die
    // technischen/Performance-Einstellungen
    // (bisher direkt in Settings), die uebrigen sind Kategorie-Platzhalter fuer alles, was
    // ein vollstaendiger Client noch braucht, aber hier noch nicht (oder nur teilweise)
    // implementiert ist.
    Settings,
    SettingsGeneral,
    // Steuerung: linke Spalte = Tastenbelegung-Tabelle (Aktion/Taste/Halten-Umschalten,
    // scrollbar, s. build_settings_controls_tab), rechte Spalte = uebrige
    // Steuerungs-Einstellungen (Maus-Empfindlichkeit, Verhaltens-Platzhalter). War vorher
    // zwei Screens (Steuerung + eigener Keybinds-Screen) -- jetzt ein gemeinsamer Screen.
    SettingsControls,
    SettingsVideo,
    SettingsAudio,
    // Resourcepack-Auswahl (s. build_settings_skin_tab) -- eigener Tab statt einer Zeile im
    // General-Tab, damit "Skin"/"Texturepack" als eigenstaendiger Bereich auffindbar ist.
    SettingsSkin,
    // Inventar: bisher nur die Abdunklung hinter dem offenen Inventar (s.
    // Settings::inventory_transparency).
    SettingsInventory,
    // Schrift: Minecraft-Bitmapschrift oder DM Sans fuer ALLEN Text des Clients.
    SettingsFont,
    // Design: wie der Client aussieht -- bisher das Hintergrundbild des Startbildschirms
    // (s. wallpaper.rs).
    SettingsDesign,
    // Welche Sprache wo gilt (s. i18n, LANGUAGE_ROWS).
    SettingsLanguage,
    // Module: dieselbe Tafel wie das Modul-Menue im Spiel (s. build_module_menu), nur aus den
    // Einstellungen heraus erreichbar -- auch ohne Verbindung.
    SettingsModules,
    // Sens-Rechner (Knopf "Rechner" neben der Kamera-Empfindlichkeit): Minecraft-Sens in
    // unsere umrechnen, und cm/360 aus DPI und Sens. Unterscreen von SettingsControls.
    SettingsSensCalc,
    // Shadereinstellungen (Knopf neben dem Renderpfad im Render-Tab): Werte, die nur den
    // Shader-Pfad betreffen. Unterscreen von SettingsGeneral.
    SettingsShader,
    // Configs: zwischen den benannten Einstellungs-Dateien wechseln, neue anlegen, umbenennen,
    // loeschen -- wie im Launcher, aber im laufenden Spiel (s. App::switch_config).
    SettingsConfigs,
    // Lichtstaerken: je Lichtquelle ein Faktor, mit Suche. Unterscreen von SettingsShader.
    SettingsLightLevels,
    // Partikel-Anpassung: je Partikelart an/aus, Dauer, Deckkraft, Tempo. Unterscreen von
    // SettingsVideo (Knopf neben der Partikel-Stufe).
    SettingsParticles,
    // Sonstiges: was zu keiner anderen Seite passt (bisher: Schliessen durch den Server
    // ignorieren, s. Settings::no_ui_close).
    SettingsMisc,
    // Einrichtung: ganz unten in der Kategorienleiste, erste Seite beim allerersten Oeffnen der
    // Einstellungen. Hier kommt der Tastenbelegungs-Assistent hin.
    SettingsSetup,
    HudEditor,
    // Gestorben-Screen: erzwungen, wenn der Spieler tot ist (Leben <= 0). Kein Weg zurueck
    // ausser Respawn oder Disconnect -- Esc tut hier nichts.
    Death,
}

impl MenuScreen {
    // Zu welcher Kategorie der Einstellungen ein Screen gehoert: Kategorien zu sich selbst,
    // Unterseiten (Rechner, Shader, ...) zu der Kategorie, von der aus man sie oeffnet.
    // None = keine Einstellungsseite.
    fn settings_category(self) -> Option<MenuScreen> {
        match self {
            MenuScreen::SettingsSensCalc => Some(MenuScreen::SettingsControls),
            MenuScreen::SettingsShader | MenuScreen::SettingsLightLevels => Some(MenuScreen::SettingsGeneral),
            MenuScreen::SettingsParticles => Some(MenuScreen::SettingsVideo),
            MenuScreen::SettingsSetup => Some(self),
            s if SETTINGS_CATEGORIES.iter().any(|(c, _)| *c == s) => Some(s),
            _ => None,
        }
    }

    // Eine Kategorie selbst (keine Unterseite): dort ersetzt die Kategorienleiste den
    // Zurueck-Knopf.
    fn is_settings_category(self) -> bool {
        self.settings_category() == Some(self)
    }

    // Name in der Einstellungsdatei (settings_category=), unabhaengig von der Sprache.
    fn settings_key(self) -> &'static str {
        match self {
            MenuScreen::SettingsGeneral => "render",
            MenuScreen::SettingsVideo => "video",
            MenuScreen::SettingsAudio => "audio",
            MenuScreen::SettingsControls => "controls",
            MenuScreen::SettingsInventory => "inventory",
            MenuScreen::SettingsSkin => "skin",
            MenuScreen::SettingsFont => "font",
            MenuScreen::SettingsDesign => "design",
            MenuScreen::SettingsLanguage => "language",
            MenuScreen::SettingsModules => "modules",
            MenuScreen::SettingsConfigs => "configs",
            MenuScreen::SettingsMisc => "misc",
            _ => "setup",
        }
    }

    fn from_settings_key(key: &str) -> Option<MenuScreen> {
        SETTINGS_CATEGORIES.iter().map(|(c, _)| *c).chain([MenuScreen::SettingsSetup]).find(|c| c.settings_key() == key)
    }

    // Seiten im gemeinsamen Zeilenraster mit Seiten-Scroll (s. SettingsPage). None: eigenes
    // Layout (Tabellen, Listen mit eigenem Scroll) oder noch nicht umgestellt.
    fn settings_page(self) -> Option<SettingsPage> {
        match self {
            MenuScreen::SettingsGeneral => Some(SettingsPage {
                rows: SETTINGS_ROW_COUNT,
                sections: &[("Bildrate", FPS_LIMIT_ROW), ("Chunks", MESH_BUDGET_ROW), ("Tearing", TEARING_TEST_ROW), ("System", CPU_ROW)],
            }),
            MenuScreen::SettingsVideo => Some(SettingsPage {
                rows: VIDEO_ROW_COUNT,
                sections: &[("Sichtweite", RENDER_DISTANCE_ROW), ("Kamera", VIDEO_CAMERA_ROW), ("Darstellung", SMOOTH_LIGHTING_ROW), ("Treffer", DAMAGE_TINT_FIRST_ROW), ("Spielerliste", PLAYER_LIST_SCALE_ROW), ("Hurt-Cam", HURT_CAM_ROW), ("Feuer", FIRE_MODE_ROW), ("Tod", DEATH_ANIM_ROW)],
            }),
            MenuScreen::SettingsControls => Some(SettingsPage { rows: controls_rows().len(), sections: controls_sections() }),
            // Zeile 4 = Zusammenfassen bei Hover, Zeilen 5..7 = Trank-Buchstaben.
            MenuScreen::SettingsInventory => Some(SettingsPage { rows: 8, sections: &[("Allgemein", 0), ("Tränke", 5)] }),
            MenuScreen::SettingsMisc => Some(SettingsPage { rows: 5, sections: &[] }),
            MenuScreen::SettingsDesign => Some(SettingsPage { rows: design_row_count(), sections: &[("Allgemein", 0), ("Theme", DESIGN_THEME_ROW)] }),
            MenuScreen::SettingsAudio => Some(SettingsPage { rows: AUDIO_PITCH_ROW + 1, sections: &[("Lautstärke", AUDIO_MASTER_ROW), ("UI-Klänge", AUDIO_UI_SOUND_FIRST_ROW), ("Ausgabe", AUDIO_DEVICE_ROW)] }),
            // Aussehen (Groesse, Breite, Hintergrund, Abdunkeln), dann Verlauf (Zeilen, Ausblenden).
            MenuScreen::SettingsFont => Some(SettingsPage { rows: STABLE_NUMBERS_ROW + 1, sections: &[("Standard", 0), ("Ausnahmen", FONT_EXCEPTIONS_ROW), ("Zahlen", STABLE_NUMBERS_ROW)] }),
            MenuScreen::SettingsLanguage => Some(SettingsPage { rows: LOANWORDS_ROW + 1, sections: &[("Sprachen", 0), ("Schreibweise", LATIN_MACRONS_ROW)] }),
            _ => None,
        }
    }
}

// Eine Einstellungsseite mit Seiten-Scroll: wie viele Zeilen sie hat und wo ihre Abschnitte
// beginnen (Name, erste Zeile). Ab zwei Abschnitten stehen oben Reiter, die sofort zum
// Abschnitt scrollen, und vor jedem weiteren Abschnitt eine Trennlinie mit seinem Namen rechts
// (s. App::build_settings_page_frame). Die Seite selbst setzt ihre Zeilen wie immer ueber
// settings_row_y; den Platz fuer die Trennlinien rechnet das dort hinein.
#[derive(Clone, Copy)]
struct SettingsPage {
    rows: usize,
    sections: &'static [(&'static str, usize)],
}

impl SettingsPage {
    // Bitmaske fuer settings_row_y_in. Der erste Abschnitt bekommt keine Trennlinie -- direkt
    // darueber stehen die Reiter.
    fn section_starts(self) -> u128 {
        self.sections.iter().filter(|&&(_, row)| row > 0 && row < 128).fold(0, |m, &(_, row)| m | 1 << row)
    }
}

// Verschiebbare HUD-Elemente im HudEditor (s. hud_drag_offset). Weitere Elemente (Leben,
// Hunger, Hotbar) bekommen spaeter eigene Varianten nach demselben Muster.
#[derive(Clone, Copy, PartialEq, Eq)]
enum HudElement {
    Perf,
    Crosshair,
    // Server-HUD, jetzt ebenfalls verschiebbar (s. build_server_hud). Positionen normiert wie
    // Perf (obere linke Ecke), Groesse aus dem tatsaechlichen Inhalt bzw. Platzhalter im Editor.
    ActionBar,
    Scoreboard,
    // Die Hotbar selbst (Sheet + Icons + Auswahlrahmen) -- verschiebbar wie alles andere.
    Hotbar,
    // Der Chat-Nachrichtenblock. Die Eingabezeile gehoert bewusst NICHT dazu: die bleibt am
    // unteren Bildschirmrand, wo eine Texteingabe hingehoert.
    Chat,
    // Die eigene Schild-Cooldown-Zahl (Schild-Modul), gezeichnet in Fadenkreuzfarbe.
    ShieldCooldown,
    // Die Munitionsanzeige des Pfeil-Moduls.
    Arrows,
    // Titel und Untertitel (Title-Pakete), je fuer sich verschiebbar, ausrichtbar und
    // skalierbar.
    Title,
    Subtitle,
    // Die Statuseffekte oben rechts (Gui.extractEffects), verschiebbar und skalierbar; dazu
    // die Schalter fuer die Anzeige im HUD und neben dem Inventar. Die Spielerliste steht
    // bewusst NICHT im Editor -- sie sitzt fest oben mittig wie in Vanilla.
    Effects,
    // Die Bossbars (BossBarHud), alle zusammen als ein Block.
    BossBar,
    // Der Name des gewaehlten Items ueber der Hotbar (s. build_held_name).
    HeldName,
    // Das Ruestungs-HUD (Modul "Ruestung", s. build_armor_hud).
    Armor,
    // Die Keystrokes (Modul, s. push_keystrokes).
    Keystrokes,
    // Die Session-Info (Modul, s. push_session_info).
    Session,
}

